["Here is an example of how you might implement this in C using pthreads for thread safety and a simple cleanup mechanism. This code does not include the integration with external data sources or partial updates to the `NR_RLC_PDU` list, as these would require more specific details about your system's requirements.

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct NR_DL_FRAME_TRANSPORT_CONTEXT {
    int DL_FRAME_TRANSPORT_TAG;
    void* RLC_PDU_LIST; // Assuming this is a pointer to a list of some sort
    int QoS_CONFIGURATION;
} NR_DL_FRAME_TRANSPORT_CONTEXT;

typedef struct DynamicArray {
    pthread_mutex_t lock;
    NR_DL_FRAME_TRANSPORT_CONTEXT* array;
    int size;
    int capacity;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    pthread_mutex_init(&da->lock, NULL);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    return da;
}

void destroyDynamicArray(DynamicArray* da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

void addFrame(DynamicArray* da, NR_DL_FRAME_TRANSPORT_CONTEXT frame) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        // Double the capacity when full
        da->capacity = da->capacity ? da->capacity * 2 : 1;
        da->array = realloc(da->array, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT) * da->capacity);
    }

    // Add the frame to the array
    memcpy(&da->array[da->size], &frame, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    da->size++;

    pthread_mutex_unlock(&da->lock);
}

void removeFrame(DynamicArray* da, int index) {
    pthread_mutex_lock(&da->lock);

    if (index < da->size) {
        // Shift all elements after the removed one to fill the gap
        for (int i = index; i < da->size - 1; i++) {
            memcpy(&da->array[i], &da->array[i + 1], sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
        }

        // Decrease the size and potentially shrink the array
        da->size--;
        if (da->capacity >= 4 * da->size) {
            da->capacity /= 2;
            da->array = realloc(da->array, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT) * da->capacity);
        }
    }

    pthread_mutex_unlock(&da->lock);
}
```
This code provides a simple dynamic array with thread safety. It uses a mutex to ensure that only one thread can modify the array at a time, which minimizes contention and ensures thread safety. The `addFrame` function doubles the capacity of the array when it is full, while the `removeFrame` function halves the capacity when it is less than a quarter full. This balances memory usage with performance by avoiding frequent reallocations.
"]

["Here is an example of how you might implement this in C using POSIX threads (pthreads) for threading and the pthread_mutex_t type for synchronization. Note that this code does not include logging or error handling, which would be quite complex to show here. Also, it's important to note that C is a low-level language and managing memory manually can lead to many issues such as memory leaks, dangling pointers, etc. It's recommended to use higher level languages like C++ or even better, use existing libraries for this kind of task.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager* manager = malloc(sizeof(ArrayManager));
    if (manager == NULL) return NULL;

    manager->offsets = malloc(initial_capacity * sizeof(long));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->records = malloc(initial_capacity * sizeof(Record*));
    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void add_record(ArrayManager* manager, long offset, int key, Record* record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;

        long* new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
        int* new_keys = realloc(manager->keys, new_capacity * sizeof(int));
        Record** new_records = realloc(manager->records, new_capacity * sizeof(Record*));

        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->offsets[manager->count] = offset;
    manager->keys[manager->count] = key;
    manager->records[manager->count] = record;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

Record* get_record(ArrayManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->keys[i] == key) {
            Record* record = manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}
```
This code provides a basic example of how you might manage dynamic memory allocation and concurrent access to an array of records. It uses a mutex for synchronization, which ensures that only one thread can modify the arrays at a time. When adding a record, it checks if there's enough space in the arrays; if not, it doubles their size using realloc.
"]

