std::mutex mtx; // Mutex for thread safety

void insertAfterTarget(std::forward_list<int>& flist, int target, int value) {
    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread safety

    auto it = find(flist.begin(), flist.end(), target); // Find the first occurrence of the target integer within the list

    if (it != flist.end()) { // If the target is found, insert the value after it
        flist.insert_after(it, value);
    } else { // If the target is not found, append the value to the end of the list
        flist.push_back(value);
    }
}
