using System.Xml.Serialization;
using System.Configuration;
using System.Threading;
using System.Reflection;

public class ConfigManager
{
    private Dictionary<string, object> _configs = new Dictionary<string, object>();
    private FileSystemWatcher _watcher;

    public ConfigManager(string configPath)
    {
        LoadConfigFromFile(configPath);

        // Watch for changes in the configuration file.
        _watcher = new FileSystemWatcher(Path.GetDirectoryName(configPath), Path.GetFileName(configPath));
        _watcher.Changed += (sender, e) => LoadConfigFromFile(e.FullPath);
        _watcher.EnableRaisingEvents = true;
    }

    private void LoadConfigFromFile(string path)
    {
        var extension = Path.GetExtension(path).ToLower();

        switch (extension)
        {
            case ".json":
                LoadJsonConfig(path);
                break;
            case ".xml":
                LoadXmlConfig(path);
                break;
            default:
                throw new NotSupportedException("Unsupported config file format.");
        }
    }

    private void LoadJsonConfig(string path)
    {
        var json = File.ReadAllText(path);
        _configs = JsonConvert.DeserializeObject<Dictionary<string, object>>(json);

        // Notify the game engine about the changes.
        GameEngine.Instance.UpdateConfig(_configs);
    }

    private void LoadXmlConfig(string path)
    {
        var serializer = new XmlSerializer(typeof(Dictionary<string, object>));

        using (var reader = new StreamReader(path))
        {
            _configs = (Dictionary<string, object>)serializer.Deserialize(reader);
        }

        // Notify the game engine about the changes.
        GameEngine.Instance.UpdateConfig(_configs);
    }

    public void LoadFromEnvironmentVariables()
    {
        var appSettings = ConfigurationManager.AppSettings;

        foreach (var key in appSettings.AllKeys)
        {
            _configs[key] = appSettings[key];
        }

        // Notify the game engine about the changes.
        GameEngine.Instance.UpdateConfig(_configs);
    }
}
```
