["Here's an example of how you might implement this using Node.js with built-in modules like `fs` and `readline` for reading files, `archiver` for handling zip archives, and `winston` for logging. This is a simplified version and does not include all the mentioned features:

```javascript
const fs = require('fs');
const readline = require('readline');
const archiver = require('archiver');
const winston = require('winston');

async function processFiles(directoryPath, logFile) {
  const logger = winston.createLogger({
    level: 'info',
    format: winston.format.json(),
    transports: [new winston.transports.File({ filename: logFile })],
  });

  let totalLines = 0;
  let emptyLineCount = 0;

  const files = fs.readdirSync(directoryPath);

  for (const file of files) {
    logger.info(`Processing ${file}...`);

    if (file.endsWith('.zip')) {
      // Handle zip archive
      const archive = archiver('zip', { zlib: { level: 9 } });
      await new Promise((resolve, reject) => {
        fs.createReadStream(`${directoryPath}/${file}`)
          .pipe(archive)
          .on('error', reject);
        archive.finalize();
      });
    } else {
      // Handle text file
      const stream = readline.createInterface({
        input: fs.createReadStream(`${directoryPath}/${file}`),
        crlfDelay: Infinity,
      });

      for await (const line of stream) {
        totalLines++;
        if (!line.trim()) emptyLineCount++;
      }
    }
  }

  logger.info('Finished processing files');

  return {
    totalLines,
    emptyLineCount,
  };
}
```
This function reads all the files in a directory synchronously to avoid blocking the event loop while reading large numbers of files. It then processes each file asynchronously using `readline` for text files and `archiver` for zip archives. Progress is logged to a specified log file using `winston`, which can be monitored separately from the primary processing tasks.

Please note that this function does not handle errors or edge cases such as empty directories, non-existent paths, or unsupported archive formats. It also doesn't support multi-threading or thread safety, and it assumes all files are text files unless they end with `.zip`. You would need to add error handling code for these scenarios, potentially using a try/catch block around the file processing logic, and you might want to use a library like `async` to handle concurrent file operations more efficiently.
