function generateFooter(config) {
    if (!Array.isArray(config)) return '';

    let html = '<footer>';
    config.forEach((module) => {
        if (typeof module !== 'object' || module === null) return;

        const src = module.src ? ` src="${module.src}"` : '';
        const async = module.async ? ' async' : '';
        const defer = module.defer ? ' defer' : '';
        const type = module.type ? ` type="${module.type}"` : '';

        html += `<script${src}${async}${defer}${type}></script>`;

        if (Array.isArray(module.children)) {
            module.children.forEach((child) => {
                html += generateFooter([child]);
            });
        }
    });

    return html + '</footer>';
}
