import com.google.firebase.storage.*;

public class ThemeManager {
    private static final String TAG = "ThemeManager";
    private static final int MAX_CACHE_SIZE = 10; // Adjust as needed

    private ConcurrentHashMap<String, Bitmap> themeCache = new ConcurrentHashMap<>();
    private StorageReference storageRef;
    private HandlerThread workerThread;
    private ExecutorService executor;

    public ThemeManager(Context context) {
        FirebaseStorage storage = FirebaseStorage.getInstance();
        storageRef = storage.getReference().child("themes");

        workerThread = new HandlerThread("ThemeWorker");
        workerThread.start();
        executor = Executors.newFixedThreadPool(4); // Adjust as needed
    }

    public void loadThemeAsync(String themeId) {
        executor.execute(() -> {
            Bitmap bitmap = getBitmapFromCache(themeId);

            if (bitmap == null) {
                try {
                    File localFile = downloadThemeFile(themeId);
                    bitmap = BitmapFactory.decodeFile(localFile.getAbsolutePath());

                    addBitmapToCache(themeId, bitmap);
                } catch (IOException e) {
                    Log.e(TAG, "Failed to load theme: " + themeId, e);
                }
            }
        });
    }

    private synchronized void addBitmapToCache(String key, Bitmap value) {
        while (themeCache.size() >= MAX_CACHE_SIZE) {
            String oldestKey = (String) themeCache.keySet().toArray()[0];
            themeCache.remove(oldestKey);
        }

        themeCache.put(key, value);
    }

    private Bitmap getBitmapFromCache(String key) {
        return themeCache.get(key);
    }

    private File downloadThemeFile(String themeId) throws IOException {
        StorageReference fileRef = storageRef.child(themeId + ".png"); // Adjust as needed

        File localFile = new File(context.getFilesDir(), themeId + ".png");
        try (OutputStream os = new FileOutputStream(localFile)) {
            fileRef.getBytes(Long.MAX_VALUE).addOnSuccessListener(bytes -> {
                os.write(bytes);
            }).addOnFailureListener(e -> Log.w(TAG, "Failed to download theme: " + themeId, e));
        }

        return localFile;
    }

    public void backupThemeAsync(String themeId) {
        executor.execute(() -> {
            Bitmap bitmap = getBitmapFromCache(themeId);

            if (bitmap != null) {
                try {
                    ByteArrayOutputStream stream = new ByteArrayOutputStream();
                    bitmap.compress(Bitmap.CompressFormat.PNG, 100, stream); // Adjust as needed

                    StorageReference fileRef = storageRef.child(themeId + ".png");
                    fileRef.putBytes(stream.toByteArray()).addOnFailureListener(e -> Log.w(TAG, "Failed to backup theme: " + themeId, e));
                } catch (IOException e) {
                    Log.e(TAG, "Failed to compress bitmap for backup", e);
                }
            }
        });
    }

    // Add more methods as needed...
}
```
