import java.util.*;
import java.lang.*;

public class ServiceManager {
    private static final int MAX_CPU = 80; // Maximum CPU usage percentage
    private static final int MAX_MEMORY = 90; // Maximum memory usage percentage
    private static final int RETRY_ATTEMPTS = 5; // Number of retry attempts for network failures
    private static final long BACKOFF_TIME = 2000L; // Initial backoff time in milliseconds

    private Service service = new Service();
    private Metrics metrics = new Metrics();

    public void manageService() {
        while (true) {
            int cpuUsage = getCpuUsage();
            int memoryUsage = getMemoryUsage();

            if (cpuUsage > MAX_CPU || memoryUsage > MAX_MEMORY) {
                stopService();
            } else {
                startService();
            }
        }
    }

    private void startService() {
        int attempts = 0;

        while (attempts < RETRY_ATTEMPTS) {
            try {
                service.start();
                metrics.incrementStartAttempts();
                return;
            } catch (NetworkException e) {
                attempts++;

                if (attempts == RETRY_ATTEMPTS) {
                    metrics.incrementFailedStartAttempts();
                    break;
                }

                try {
                    Thread.sleep(BACKOFF_TIME * ((long) Math.pow(2, attempts)));
                } catch (InterruptedException ex) {
                    // Handle exception
                }
            }
        }
    }

    private void stopService() {
        int attempts = 0;

        while (attempts < RETRY_ATTEMPTS) {
            try {
                service.stop();
                metrics.incrementStopAttempts();
                return;
            } catch (NetworkException e) {
                attempts++;

                if (attempts == RETRY_ATTEMPTS) {
                    metrics.incrementFailedStopAttempts();
                    break;
                }

                try {
                    Thread.sleep(BACKOFF_TIME * ((long) Math.pow(2, attempts)));
                } catch (InterruptedException ex) {
                    // Handle exception
                }
            }
        }
    }

    private int getCpuUsage() {
        // Implement this method to return the current CPU usage percentage
        return 0;
    }

    private int getMemoryUsage() {
