#include <string.h>

typedef struct ConfigNode {
    char* key;
    char* value;
    struct ConfigNode* next;
} ConfigNode;

ConfigNode* load_config(const char* dir, const char* filename) {
    FILE *file;
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", dir, filename);

    file = fopen(path, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    ConfigNode* head = NULL;
    ConfigNode* tail = NULL;
    char line[1024];

    while(fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        if (key == NULL) continue; // skip invalid lines

        char *value = strtok(NULL, "\n");
        if (value == NULL) continue; // skip invalid lines

        ConfigNode* node = malloc(sizeof(ConfigNode));
        if (node == NULL) {
            printf("Error allocating memory\n");
            fclose(file);
            return NULL;
        }

        node->key = strdup(key);
        node->value = strdup(value);
        node->next = NULL;

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    fclose(file);
    return head;
}
```
This function reads a configuration file line by line, parsing each line into key and value. It then creates a new ConfigNode for each parsed pair and adds it to the linked list. The memory allocated for each node is freed when the list is no longer needed. 

