['Here is a basic implementation using JavaCompiler API from javax.tools package. This program will compile all .java files in a specified directory, clean it before each compilation and check for the presence of a specific method within the compiled class. 

```Java
import java.io.*;
import java.net.URI;
import javax.tools.*;
import java.util.*;
import java.nio.file.*;

public class DynamicCompiler {
    private JavaCompiler compiler;
    private StandardJavaFileManager manager;

    public DynamicCompiler() {
        this.compiler = ToolProvider.getSystemJavaCompiler();
        this.manager = compiler.getStandardFileManager(null, null, null);
    }

    public boolean compile(Path pathToSrc) throws IOException {
        Iterable<? extends JavaFileObject> fileObjects = manager.getJavaFileObjectsFromFiles(Arrays.asList(pathToSrc.toFile()));
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        StandardJavaFileManager fileManager = compiler.getStandardFileManager(diagnostics, null, null);

        boolean success = compiler.getTask(null, fileManager, diagnostics, null, null, fileObjects).call();
        for (Diagnostic<? extends JavaFileObject> diagnostic : diagnostics.getDiagnostics()) {
            System.out.format("Error on line %d in %s%n", diagnostic.getLineNumber(), diagnostic);
        }

        return success;
    }

    public boolean checkMethod(String className, String methodName) throws Exception {
        Class<?> clazz = Class.forName(className);
        for (java.lang.reflect.Method m : clazz.getDeclaredMethods()) {
            if (m.getName().equals(methodName)) return true;
        }

        return false;
    }

    public void cleanDirectory(Path pathToSrc) throws IOException {
        Files.walk(pathToSrc)
             .map(Path::toFile)
             .forEach(File::delete);
    }
}
```

