#include <stdio.h>
#include <string.h>
#include <openssl/des.h>
#include <openssl/bio.h>
#include <openssl/evp.h>
#include <iconv.h>

typedef struct {
    char *title;
    int (*callback)(char*);
    size_t maxLength;
} ConnectionInfo;

typedef struct {
    char *password;
    ConnectionInfo *connection;
} CredentialInfo;

int processCredential(CredentialInfo *credential, const unsigned char *key, const unsigned char *iv) {
    if (credential == NULL || credential->password == NULL || strlen(credential->password) == 0) {
        return -1; // Error: Password is either empty or NULL.
    }

    if (credential->connection == NULL || credential->connection->title == NULL || strlen(credential->connection->title) == 0) {
        return -2; // Error: Connection title is not set.
    }

    if (credential->connection->callback == NULL) {
        return -3; // Error: Callback function pointer is NULL.
    }

    if (credential->connection->maxLength <= 0) {
        return -4; // Error: Maximum allowed length of the decrypted message is not set or invalid.
    }

    BIO *b64, *bmem, *bdes;
    char *decryptedMessage = malloc(credential->connection->maxLength + 1);
    if (decryptedMessage == NULL) {
        return -5; // Error: Memory allocation failure.
    }

    b64 = BIO_new(BIO_f_base64());
    bmem = BIO_new_mem_buf(credential->password, -1);
    bdes = BIO_new(BIO_f_des());

    BIO_push(b64, bmem);
    DES_set_key_unchecked((const_DES_cblock*) key, &bdes->des.ks1);
    DES_set_key_unchecked((const_DES_cblock*) key, &bdes->des.ks2);
    DES_set_key_unchecked((const_DES_cblock*) key, &bdes->des.ks3);
    DES_set_2keys((const_DES_cblock*) iv, &bdes->des.ks1);

    BIO_read(b64, decryptedMessage, credential->connection->maxLength);

    iconv_t cd = iconv_open("UTF-8", "UTF-8");
    if (cd == (iconv_t) -1 || iconv(cd, NULL, NULL, NULL, NULL) == -1) {
        return -6; // Error: Decryption or UTF-8 conversion failed.
    }

    int ret = credential->connection->callback(decryptedMessage);

    free(decryptedMessage);
    BIO_free_all(b64);
    iconv_close(cd);

    return ret;
}
```
