['Here is a basic implementation of `DataEncryptor` in C# using AES-CBC encryption with padding modes. This code does not include logging, error handling for network failures or retry mechanisms, asynchronous processing and key rotation policies. 

```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public class DataEncryptor
{
    private readonly Aes aesAlgorithm;
    private readonly ICryptoTransform encryptorTransform;
    private readonly ICryptoTransform decryptorTransform;

    public DataEncryptor(byte[] key, byte[] iv)
    {
        if (key == null || key.Length <= 0)
            throw new ArgumentNullException("Key cannot be empty");
        if (iv == null || iv.Length <= 0)
            throw new ArgumentNullException("IV cannot be empty");

        aesAlgorithm = Aes.Create();
        aesAlgorithm.Padding = PaddingMode.PKCS7; // or any other padding mode
        aesAlgorithm.Key = key;
        aesAlgorithm.IV = iv;

        encryptorTransform = aesAlgorithm.CreateEncryptor(aesAlgorithm.Key, aesAlgorithm.IV);
        decryptorTransform = aesAlgorithm.CreateDecryptor(aesAlgorithm.Key, aesAlgorithm.IV);
    }

    public byte[] EncryptData(byte[] dataToEncrypt)
    {
        return PerformCryptography(dataToEncrypt, encryptorTransform);
    }

    public byte[] DecryptData(byte[] dataToDecrypt)
    {
        return PerformCryptography(dataToDecrypt, decryptorTransform);
    }

    private static byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransformer)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var cryptoStream = new CryptoStream(memoryStream, cryptoTransformer, CryptoStreamMode.Write))
            {
                cryptoStream.Write(data, 0, data.Length);
                cryptoStream.FlushFinalBlock();

                return memoryStream.ToArray();
            }
        }
    }
}
```
This class uses the AesCryptoServiceProvider for encryption and decryption. The key and IV are passed in as byte arrays, which should be securely generated and stored. 

Please note that this is a basic implementation and does not include error handling or logging. For production use, you would need to add appropriate error handling, logging, and possibly other features such as network failure handling, retry mechanisms, asynchronous processing, key rotation policies etc.
']

