["Here's a basic implementation of such a function using Node.js with Axios for HTTP requests and LRU-Cache for caching. This example uses OpenWeatherMap API but you can easily modify it to support other APIs. 

```javascript
const axios = require('axios');
const LRU = require('lru-cache');

// Create an instance of the cache with a max size of 100 items
const cache = new LRU({max: 100});

class WeatherAPI {
    constructor(apiKey, baseURL) {
        this.apiKey = apiKey;
        this.baseURL = baseURL;
    }

    async getWeatherData(cityName) {
        const cacheKey = `weather_${cityName}`;

        // Check if the data is in the cache
        let weatherData = cache.get(cacheKey);

        if (!weatherData) {
            console.log('Fetching from API');

            try {
                const response = await axios.get(`${this.baseURL}/data/2.5/weather?q=${cityName}&appid=${this.apiKey}`);

                weatherData = response.data;

                // Store the data in the cache for future use
                cache.set(cacheKey, weatherData);
            } catch (error) {
                console.log('Error fetching from API:', error);
                return null;
            }
        } else {
            console.log('Fetching from cache');
        }

        return weatherData;
    }
}

// Usage
const apiKey = 'your_api_key'; // replace with your actual API key
const baseURL = 'http://api.openweathermap.org';
const weatherAPI = new WeatherAPI(apiKey, baseURL);

async function getWeatherForCity(cityName) {
    const weatherData = await weatherAPI.getWeatherData(cityName);

    if (weatherData) {
        console.log('Weather data for', cityName, ':', weatherData);
    } else {
        console.log('Failed to fetch weather data for', cityName);
    }
}

getWeatherForCity('London');
```
