["Here is a basic implementation in C using pthread library for thread safety. This code does not include error handling or retry mechanisms as it's quite complex to implement without knowing more about your specific requirements. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char* string;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record* allocate_records(size_t count, size_t strlen) {
    srand((unsigned int) time(NULL)); // seed the random number generator

    pthread_mutex_lock(&mutex);
    record *records = (record*) malloc(count * sizeof(record));
    if (!records) {
        pthread_mutex_unlock(&mutex);
        return NULL; // handle memory allocation failure here
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].offset = rand();
        records[i].key = rand();

        records[i].string = malloc(strlen + 1); // +1 for null terminator
        if (!records[i].string) {
            free_records(records, i);
            pthread_mutex_unlock(&mutex);
            return NULL; // handle memory allocation failure here
        }

        for (size_t j = 0; j < strlen; ++j) {
            int randomChar = rand() % (26 + 26 + 10);
            if (randomChar < 26)
                records[i].string[j] = 'a' + randomChar;
            else if (randomChar < 52)
                records[i].string[j] = 'A' + randomChar - 26;
            else
                records[i].string[j] = '0' + randomChar - 52;
        }
        records[i].string[strlen] = '\0'; // null terminate the string
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

void free_records(record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].string);
    }

    pthread_mutex_lock(&mutex);
    free(records);
    pthread_mutex_unlock(&mutex);
}
```
