    if(res == JNI_ERR) {
        printf("Failed to create JVM\n");
        exit(1);
    }

    channelClass = (*env)->FindClass(env, "Channel"); 
    if(channelClass == NULL) {
        printf("Failed to find Channel class\n");
        exit(1);
    }

    jmethodID initMethodId = (*env)->GetMethodID(env, channelClass, "<init>", "()V"); 
    if(initMethodId == NULL) {
        printf("Failed to find Channel constructor\n");
        exit(1);
    }

    jobject channelObject = (*env)->NewObject(env, channelClass, initMethodId); 
    if(channelObject == NULL) {
        printf("Failed to create Channel object\n");
        exit(1);
    }
}

void addRecord(int key) {
    pthread_mutex_lock(&arrayManager.lock);

    // Resize arrays if necessary
    if (arrayManager.count == arrayManager.capacity) {
        size_t newCapacity = arrayManager.capacity * 2;

        long* newOffsets = realloc(arrayManager.offsets, sizeof(long) * newCapacity);
        Record* newRecords = realloc(arrayManager.records, sizeof(Record) * newCapacity);

        if (newOffsets == NULL || newRecords == NULL) {
            // Handle allocation failure
            pthread_mutex_unlock(&arrayManager.lock);
            return;
        }

        arrayManager.offsets = newOffsets;
        arrayManager.records = newRecords;
        arrayManager.capacity = newCapacity;
    }

    // Add record
    Record record;
    record.key = key;
    arrayManager.records[arrayManager.count] = record;
    ++arrayManager.count;

    pthread_mutex_unlock(&arrayManager.lock);
}

Record* getRecord(int index) {
    pthread_mutex_lock(&arrayManager.lock);

    if (index < 0 || index >= arrayManager.count) {
        // Handle out of bounds access
        pthread_mutex_unlock(&arrayManager.lock);
        return NULL;
    }

    Record* record = &arrayManager.records[index];

    pthread_mutex_unlock(&arrayManager.lock);

    return record;
}
