class RandomGenerator {
public:
    RandomGenerator(int range_start, int range_end, size_t limit) : 
        mt_(std::random_device{}()), 
        dist_(range_start, range_end), 
        limit_(limit), 
        current_size_(0) {}

    void generate() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (current_size_ >= limit_) return;

        int num = dist_(mt_);
        while (!data_.insert(num).second) {
            num = dist_(mt_);
        }
        current_size_++;
    }

    void seedFromAPI() {
        CURL *curl;
        CURLcode res;
        std::string readBuffer;

        curl = curl_easy_init();
