using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Serilog;

public class WebService
{
    private static readonly HttpClient client = new HttpClient();
    private static readonly MemoryCache cache = new MemoryCache(new MemoryCacheOptions());
    private static readonly ConcurrentDictionary<string, SemaphoreSlim> locks = new ConcurrentDictionary<string, SemaphoreSlim>();

    public async Task UpdateHtmlContentAsync(string sectionId, string elementId, string html)
    {
        var key = $"{sectionId}_{elementId}";

        if (!locks.TryGetValue(key, out var @lock))
        {
            @lock = new SemaphoreSlim(1, 1);
            locks.TryAdd(key, @lock);
        }

        await @lock.WaitAsync();

        try
        {
            if (!cache.TryGetValue(key, out string cachedHtml))
            {
                // Fetch from database or other source
                Log.Information("Fetched HTML content for sectionId:{SectionId}, elementId:{ElementId}", sectionId, elementId);

                cache.Set(key, html, new MemoryCacheEntryOptions().SetSlidingExpiration(TimeSpan.FromMinutes(5)));
            }

            // Apply changes to HTML content
            Log.Information("Updated HTML content for sectionId:{SectionId}, elementId:{ElementId}", sectionId, elementId);
        }
        finally
        {
            @lock.Release();
        }
    }

    public HttpClient CreateHttpClient(string url, bool disableCertificateValidation = false)
    {
        var handler = new HttpClientHandler();

        if (disableCertificateValidation)
        {
            handler.ServerCertificateCustomValidationCallback = (sender, cert, chain, sslPolicyErrors) => true;
        }

        return new HttpClient(handler);
    }
}
