int maxLogSize = 1024 * 1024; // Maximum log size in bytes

void* allocateMessage(char* string, int timestamp, double value) {
    Message* message = malloc(sizeof(Message));
    if (message == NULL) return NULL;

    message->string = strdup(string);
    message->timestamp = timestamp;
    message->value = value;

    pthread_mutex_init(&message->mutex, NULL);

    return message;
}

void freeMessage(Message* message) {
    if (message == NULL) return;

    free(message->string);
    pthread_mutex_destroy(&message->mutex);
    free(message);
}

LogEntry* allocateLogEntry() {
    LogEntry* logEntry = malloc(sizeof(LogEntry));
    if (logEntry == NULL) return NULL;

    pthread_mutex_init(&logEntry->mutex, NULL);

    return logEntry;
}

void freeLogEntry(LogEntry* logEntry) {
    if (logEntry == NULL) return;

    freeMessage(logEntry->message);
    pthread_mutex_destroy(&logEntry->mutex);
    free(logEntry);
}

int addToLogs(Message* message) {
    LogEntry* logEntry = allocateLogEntry();
    if (logEntry == NULL) return -1;

    logEntry->message = message;

    pthread_mutex_lock(&logsMutex);
    g_array_append_val(logs, logEntry);
