                // Implement Binary loading here
                break;
        }

        lock_.EnterWriteLock();
        try
        {
            data.AddRange((List<dynamic>)loadedData);
        }
        finally
        {
            lock_.ExitWriteLock();
        }
    }

    public void Filter(Func<dynamic, bool> filterFunction)
    {
        lock_.EnterReadLock();

        try
        {
            data = data.Where(filterFunction).ToList();
