#include <string.h>
#include <stdlib.h>
#include <sys/wait.h>

typedef struct {
    char* selector;
    int sizeLimit;
} SelectorConfig;

char* processString(const char* str, const char* configFilePath, const char* command) {
    xmlDocPtr doc = NULL;
    xmlNodePtr root_element = NULL;

    // Parse the XML file 
    LIBXML_TEST_VERSION
    doc = xmlReadFile(configFilePath, NULL, 0);
    if (doc == NULL) {
        printf("Failed to parse configuration file\n");
        return NULL;
    }

    // Get the root element node 
    root_element = xmlDocGetRootElement(doc);

    // Parse selectors and size limits from XML
    SelectorConfig* configs = malloc(sizeof(SelectorConfig) * xmlChildElementCount(root_element));
    int i = 0;
    for (xmlNodePtr cur = root_element->children; cur; cur = cur->next) {
        if (cur->type != XML_ELEMENT_NODE || xmlStrcmp(cur->name, "selector")) continue;

        configs[i].selector = strdup((char*)xmlNodeGetContent(cur));
        configs[i].sizeLimit = 1024; // TODO: parse size limit from XML
        i++;
    }

    char* resultStr = malloc(strlen(str) + 1);
    strcpy(resultStr, str);

    pid_t pid = fork();
    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(EXIT_FAILURE);
    } else if (pid < 0) { // Fork failed
        printf("Failed to fork\n");
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for child process to finish

        FILE* cmdOutput = fopen("cmd_output.txt", "r");
        if (cmdOutput != NULL) {
            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), cmdOutput)) {
                strcat(resultStr, "/");
                strcat(resultStr, buffer);
            }
            fclose(cmdOutput);
        } else {
            printf("Failed to open command output file\n");
        }
    }

    // TODO: traverse DOM tree and append '/' if element matches selector and its length is within size limit

    return resultStr;
}
```
