['This task is quite complex and involves multiple aspects of system programming, which cannot be fully covered in a single code block due to its complexity. However, I can provide you with a basic outline for how such a function might look like. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <zlib.h> // For compression
#include <log4c.h> // For logging
#include <sqlite3.h> // For archiving

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    record* records;
    log4c_category_t *logger;
    sqlite3 *db;
} RecordArray;

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray* array = malloc(sizeof(RecordArray));
    if (array == NULL) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->records = calloc(initial_capacity, sizeof(record));
    if (array->records == NULL) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    array->logger = log4c_category_get("record.array");
    sqlite3_open("records.db", &array->db); // Open database for archiving

    return array;
}

void add_record(RecordArray* array, record rec) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        // Resize the array
        size_t new_capacity = array->capacity * 2;
        record* new_records = realloc(array->records, new_capacity * sizeof(record));

        if (new_records == NULL) {
            log4c_category_log(array->logger, LOG4C_PRIORITY_ERROR, "Failed to resize array");
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->records = new_records;
        array->capacity = new_capacity;
    }

    // Add the record
    array->records[array->size++] = rec;

    pthread_mutex_unlock(&array->lock);
}
```
