typedef struct {
    char timestamp[25];
    int metadata1;
    float metadata2;
} LogEntry;

int main(int argc, char *argv[]) {
    // Parse command-line parameters
    if (argc != 3) {
        printf("Usage: %s <log_file> <chunk_size>\n", argv[0]);
        return 1;
    }

    char *filename = argv[1];
    int chunkSize = atoi(argv[2]) * 1024 * 1024; // Convert to bytes

    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file: %s\n", filename);
        return 1;
    }

    LogEntry *chunk = malloc(chunkSize);
    if (chunk == NULL) {
        printf("Failed to allocate memory for chunk.\n");
        fclose(file);
        return 1;
    }

    int totalMetadata1 = 0;
    float totalMetadata2 = 0.0f;
    int numEntries = 0;

    // Read file in chunks
    while (fread(chunk, sizeof(LogEntry), chunkSize / sizeof(LogEntry), file) > 0) {
        for (int i = 0; i < chunkSize / sizeof(LogEntry); i++) {
            totalMetadata1 += chunk[i].metadata1;
            totalMetadata2 += chunk[i].metadata2;
            numEntries++;
        }
    }

    // Calculate averages
    float averageMetadata1 = (float)totalMetadata1 / numEntries;
    float averageMetadata2 = totalMetadata2 / numEntries;

    printf("Average Metadata 1: %.2f\n", averageMetadata1);
    printf("Average Metadata 2: %.2f\n", averageMetadata2);

    // Clean up
    free(chunk);
    fclose(file);

    return 0;
}
```
