typedef struct {
    char old_name[256];
    char new_name[256];
    time_t timestamp;
} LogEntry;

void* renameFile(void *arg) {
    char *filename = (char*) arg;
    char newFilename[256] = "";

    // Generate the sequence based on first and last characters of filename
    int len = strlen(filename);
    if (len < 4) {
        for (int i = 0; i < (4 - len); ++i) {
            sprintf(newFilename, "%s%c", newFilename, filename[i % len]);
        }
    } else {
        sprintf(newFilename, "%c%c", filename[0], filename[len-1]);
    }

    // Append the sequence to the extension
    char *dot = strrchr(filename, '.');
    if (dot != NULL) {
        sprintf(newFilename, "%s%s", newFilename, dot);
    }

    // Rename the file
    int result = rename(filename, newFilename);
    if (result == 0) {
        LogEntry log;
        strncpy(log.old_name, filename, sizeof(log.old_name));
        strncpy(log.new_name, newFilename, sizeof(log.new_name));
        log.timestamp = time(NULL);

        // Call the callback function to handle logging
        handleLogging(&log);
    } else {
        fprintf(stderr, "Failed to rename file %s: %s\n", filename, strerror(errno));
    }

    return NULL;
}

void handleLogging(LogEntry *entry) {
