#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct UserProfile {
    char* name;
    int age;
    char* email;
    unsigned long id;
} UserProfile;

typedef struct HashTable {
    pthread_mutex_t lock;
    UserProfile** profiles;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* create_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    pthread_mutex_init(&table->lock, NULL);
    table->profiles = calloc(initial_capacity, sizeof(UserProfile*));
    if (!table->profiles) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->count = 0;
    return table;
}

void destroy_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->profiles[i]) {
            free(table->profiles[i]->name);
            free(table->profiles[i]->email);
            free(table->profiles[i]);
