// Global semaphore for resource locking
sem_t sem;

NFAPI_CRC_INDICATION_PDU_T* initializeNFapiAndResourceManagement(int numStructs) {
    // Initialize the semaphore
    if (sem_init(&sem, 0, 1) == -1) {
        perror("Semaphore initialization failed");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T* structs = malloc(numStructs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structs == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize each structure in a thread-safe manner
    for (int i = 0; i < numStructs; ++i) {
        sem_wait(&sem);  // Acquire the lock

        // Perform necessary operations on structs[i]

        sem_post(&sem);  // Release the lock
    }

    return structs;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T* structs, int numStructs) {
    for (int i = 0; i < numStructs; ++i) {
        sem_wait(&sem);  // Acquire the lock

        // Perform necessary cleanup on structs[i]

        sem_post(&sem);  // Release the lock
    }

    free(structs);

    // Clean up the semaphore
    if (sem_destroy(&sem) == -1) {
        perror("Semaphore destruction failed");
        exit(EXIT_FAILURE);
    }
}
