    pthread_mutex_lock(&manager->lock);
    ++manager->count;
    manager->sessions = realloc(manager->sessions, sizeof(USER_SESSION*) * manager->count);
    manager->sessions[manager->count - 1] = session;
    pthread_mutex_unlock(&manager->lock);
