void removeSession(SessionManager* manager, USER_SESSION* session) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->sessions[i] == session) {
            --(session->refcount);
            if (atomic_load(&(session->refcount)) == 0) {
                pthread_mutex_lock(&session->lock);
                for (size_t j = 0; j < session->numPackets; ++j) {
                    free(session->packets[j]);
                }
                free(session->packets);
                pthread_mutex_unlock(&session->lock);
                pthread_mutex_destroy(&session->lock);
                free(session);
            }
            if (i != manager->count - 1) {
                manager->sessions[i] = manager->sessions[manager->count - 1];
            }
            --manager->count;
            manager->sessions = realloc(manager->sessions, sizeof(USER_SESSION*) * manager->count);
            break;
