    int null_terminate;
} Config;

char* processFilePath(const char* filepath, size_t maxSize, const Config* config) {
    if (filepath == NULL || strlen(filepath) == 0) return NULL; // handle empty paths

    size_t len = strlen(filepath);
    if (len > maxSize) return NULL; // handle path length exceeding limit

    char* result = malloc(maxSize + 1); // allocate memory for the result string
    if (result == NULL) return NULL; // handle allocation failure

    strncpy(result, filepath, len < maxSize ? len : maxSize); // copy path to result

    if (config != NULL && config->truncate && len > maxSize) {
        strcpy(&result[maxSize - 3], "..."); // append ellipsis at the end of truncated path
    }

    if (config != NULL && config->null_terminate) {
        result[len < maxSize ? len : maxSize] = '\0'; // null terminate if required
    }

    return result;
}
