#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

// Define a struct to hold the AES context and IV
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AESContext;

// Function to initialize an AES-256-CBC cipher with a given password
AESContext* init_aes(const char *password, int keyLength) {
    AESContext *ctx = malloc(sizeof(AESContext));

    // Generate random IV
    RAND_bytes(ctx->iv, EVP_MAX_IV_LENGTH);

    // Initialize the cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, strlen(password), keyLength/8, ctx->iv, NULL);

    return ctx;
}

// Function to encrypt data with the AES context
int aes_encrypt(AESContext *ctx, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    int ciphertext_len = 0;

    // Initialize encryption operation
    EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, NULL, ctx->iv);

    // Encrypt the plaintext
    EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len);
    ciphertext_len += len;

    // Finalize encryption operation
    EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len);
    ciphertext_len += len;

    return ciphertext_len;
}

// Function to decrypt data with the AES context
int aes_decrypt(AESContext *ctx, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;
    int plaintext_len = 0;

    // Initialize decryption operation
    EVP_DecryptInit_ex(ctx->ctx, NULL, NULL, NULL, ctx->iv);

    // Decrypt the ciphertext
    EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len);
    plaintext_len += len;

    // Finalize decryption operation
    EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len);
    plaintext_len += len;

    return plaintext_len;
}

// Function to clean up the AES context and free memory
void cleanup_aes(AESContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```
