#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define BASE_OFFSET 1024

typedef struct {
    int key;
    int value;
} Record;

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long* createOffsetArray(int nOffsets) {
    long* offsetArray = allocate(sizeof(long) * nOffsets);
    for (int i = 0; i < nOffsets; ++i) {
        offsetArray[i] = BASE_OFFSET + i;
    }
    return offsetArray;
}

int* createKeyArray(const long* offsetArray, int nOffsets) {
    int* keyArray = allocate(sizeof(int) * nOffsets);
    for (int i = 0; i < nOffsets; ++i) {
        double sqrtValue = sqrt((double)offsetArray[i]);
        if (sqrtValue > INT_MAX) {
            fprintf(stderr, "Precision loss in square root calculation\n");
            exit(EXIT_FAILURE);
        }
        keyArray[i] = (int)sqrtValue;
    }
    return keyArray;
}

Record* createRecordArray(const int* keyArray, int nRecords, int minValue, int maxValue) {
    srand((unsigned int)time(NULL));
    Record* recordArray = allocate(sizeof(Record) * nRecords);
    for (int i = 0; i < nRecords; ++i) {
        recordArray[i].key = keyArray[i % nRecords];
        recordArray[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
    return recordArray;
}

Record* manageMemory(int nOffsets, int nRecords, int minValue, int maxValue) {
    long* offsetArray = createOffsetArray(nOffsets);
    int* keyArray = createKeyArray(offsetArray, nOffsets);
    Record* recordArray = createRecordArray(keyArray, nRecords, minValue, maxValue);

    free(offsetArray);
    free(keyArray);

    return recordArray;
}
```
This code creates three separate structures: `OffsetArray`, `KeyArray`, and `RecordArray`. It uses dynamic memory allocation for each structure and handles potential overflow in the square root calculation gracefully by checking if the result exceeds INT_MAX. If any allocation fails, it prints an error message and exits the program. After creating these structures, it frees the memory allocated for `OffsetArray` and `KeyArray` as they are no longer needed.
']

