public class BatchProcessor {
    private static final Logger logger = LoggerFactory.getLogger(BatchProcessor.class);
    private static final int MAX_BATCH_SIZE = 50;
    private static final long MAX_MEMORY_FOOTPRINT = 75 * 1024 * 1024; // 75MB in bytes
    private static final Semaphore semaphore = new Semaphore(MAX_BATCH_SIZE);
    private static final BasicDataSource dataSource = new BasicDataSource();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(MAX_BATCH_SIZE);
    private static final MessageDigest sha256Digest;

    static {
        try {
            sha256Digest = MessageDigest.getInstance("SHA-256");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public List<ProcessingResult> processBatchAndManageResources(List<String> batch) throws InterruptedException, ExecutionException {
        Set<String> duplicates = findDuplicates(batch);

        List<ListenableFuture<ProcessingResult>> futures = new ArrayList<>();
        for (String s : batch) {
            if (!duplicates.contains(s)) {
                semaphore.acquire();
                ListenableFuture<ProcessingResult> future = executorService.submit(() -> processString(s));
                futures.add(future);
            }
        }

        // Wait for all tasks to complete and collect results
        List<ProcessingResult> results = Futures.allAsList(futures).get();

        // Release semaphores
        for (int i = 0; i < futures.size(); i++) {
            semaphore.release();
        }

        return results;
    }

    private ProcessingResult processString(String s) {
        long startTime = System.currentTimeMillis();
        byte[] hashBytes = sha256Digest.digest(s.getBytes());
        String hashValue = bytesToHex(hashBytes);

        try (Connection conn = dataSource.getConnection()) {
            // Perform database operations here...
        } catch (Exception e) {
            logger.error("Database operation failed", e);
        }

        long endTime = System.currentTimeMillis();
        return new ProcessingResult(UUID.randomUUID(), hashValue, endTime - startTime);
    }

    private Set<String> findDuplicates(List<String> batch) {
        return batch.stream()
                .filter(i -> Collections.frequency(batch, i) > 1)
                .collect(Collectors.toSet());
    }

    private String bytesToHex(byte[] hashBytes) {
        // Convert byte array to hex string...
    }
}
```

