        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: ./program [OPTIONS]... FILES...\n");
            return EXIT_SUCCESS;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            ++i; // Skip output file name
            continue;
        } else if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "-c") == 0) {
            continue; // Skip option without value
        }

        FILE *file = fopen(argv[i], "r");
        if (file == NULL) {
            perror("Error opening file");
            return EXIT_FAILURE;
        }
        files[i - 1] = file; // Store file pointer
    }

    for (int j = 0; j < i - 1; ++j) {
        while (fgets(buffer, sizeof(buffer), files[j])) {
            printf("%s", buffer);
        }

        if (ferror(files[j])) {
            perror("Error reading file");
            return EXIT_FAILURE;
        }

        fclose(files[j]); // Close each file after processing
    }

    free(files); // Free memory allocated for file pointers
    return EXIT_SUCCESS;
