#[derive(Debug)]
enum FileFormat {
    Json,
    Yaml,
    Toml,
}

struct Config {
    format: FileFormat,
    arch: Option<String>,
    max_instructions: usize,
}

fn parse_config(path: &str) -> Result<Config, Box<dyn std::error::Error>> {
    let file = File::open(path)?;
    let mut buffer = String::new();
    file.read_to_string(&mut buffer)?;

    let format = match path.split('.').last() {
        Some("json") => FileFormat::Json,
        Some("yaml") => FileFormat::Yaml,
        Some("toml") => FileFormat::Toml,
        _ => return Err(format![Unsupported file format]),
    };

    let config = match format {
        FileFormat::Json => serde_json::from_str(&buffer)?,
        FileFormat::Yaml => serde_yaml::from_str(&buffer)?,
        FileFormat::Toml => toml::from_str(&buffer)?,
    };

    let arch = config.get("arch")?.as_str().map(ToOwned::to_owned);
    let max_instructions = *config.get("max_instructions")?.as_u64() as usize;

    Ok(Config { format, arch, max_instructions })
}

fn compile_and_optimize(path: &str) -> Option<Vec<u8>> {
