public class BatchProcessor
{
    private static Logger logger = LogManager.GetCurrentClassLogger();
    private JSchema schema;
    private int successCount = 0, failureCount = 0;

    public BatchProcessor(string schemaPath)
    {
        using (StreamReader file = File.OpenText(schemaPath))
        {
            using (var reader = new JsonTextReader(file))
            {
                this.schema = JSchema.Load(reader);
            }
        }
    }

    public async Task ProcessBatchAsync(IEnumerable<string> jsonDocuments)
    {
        var policy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        await Task.WhenAll(jsonDocuments.Select(async document =>
        {
            try
            {
                var jObject = JObject.Parse(document);
                if (!jObject.IsValid(schema))
                {
                    logger.Error("Invalid JSON: " + document);
                    Interlocked.Increment(ref failureCount);
                    return;
                }

                await policy.ExecuteAsync(async () =>
                {
                    // Process the document here...
                });

                Interlocked.Increment(ref successCount);
            }
            catch (Exception ex)
            {
                logger.Error("Failed to process JSON: " + document, ex);
                Interlocked.Increment(ref failureCount);
            }
        }));
    }

    public void PrintSummary()
    {
        Console.WriteLine($"Successful operations: {successCount}");
        Console.WriteLine($"Failed operations: {failureCount}");
    }
}
