['Here is a Java solution using CompletableFuture for asynchronous processing, ExecutorService for concurrency control, and Apache Commons IOUtils for efficient file reading. Note that this code does not include error handling for brevity. In a real-world scenario, you would want to add appropriate exception handling and logging.

```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.codec.digest.*;
import org.apache.commons.io.*;

public class FileProcessor {
    private static final Digester MD5_DIGESTER = new Digester(DigestUtils.getMd5Digest());

    public static Summary processDirectoryContents(String directoryPath, Config config) throws IOException {
        ExecutorService executorService = Executors.newFixedThreadPool(config.concurrencyLevel);

        List<CompletableFuture<FileSummary>> futures = new ArrayList<>();

        Files.walk(Paths.get(directoryPath))
            .filter(Files::isRegularFile)
            .forEach(file -> {
                CompletableFuture<FileSummary> future = CompletableFuture.supplyAsync(() -> processFile(file, config), executorService);
                futures.add(future);
            });

        Summary summary = new Summary();
        for (CompletableFuture<FileSummary> future : futures) {
            try {
                FileSummary fileSummary = future.get();
                summary.totalFiles++;
                summary.totalLines += fileSummary.lineCount;
                if (fileSummary.hasEmptyLine) summary.emptyLineFiles++;
                if (config.computeMD5Hash) summary.md5Hashes.put(fileSummary.path, fileSummary.md5Hash);
            } catch (InterruptedException | ExecutionException e) {
                // Handle exception here
            }
        }

        executorService.shutdown();
        return summary;
    }

    private static FileSummary processFile(Path file, Config config) {
        FileSummary fileSummary = new FileSummary();
        fileSummary.path = file.toString();

        try (InputStream inputStream = Files.newInputStream(file)) {
            String line;
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));

            while ((line = reader.readLine()) != null) {
                fileSummary.lineCount++;
                if (line.trim().isEmpty()) fileSummary.hasEmptyLine = true;

                if (config.computeMD5Hash) MD5_DIGESTER.update(line.getBytes());
            }

            if (config.computeMD5Hash) {
                byte[] md5Digest = MD5_DIGESTER.digest();
                fileSummary.md5Hash = DigestUtils.md5Hex(md5Digest);
                MD5_DIGESTER.reset();
            }
        } catch (IOException e) {
            // Handle exception here
        }

        return fileSummary;
    }

    public static class Config {
        int concurrencyLevel;
        boolean computeMD5Hash;
    }

    public static class Summary {
        int totalFiles = 0;
        long totalLines = 0;
        int emptyLineFiles = 0;
        Map<String, String> md5Hashes = new HashMap<>();
    }

    private static class FileSummary {
        String path;
        long lineCount = 0;
        boolean hasEmptyLine = false;
        String md5Hash;
    }
}
```
