#include <pthread.h>

typedef struct Pokemon {
    int key;
    long* offsets;
} Pokemon;

// A simple library function to retrieve the type and name of a Pokemon
char* getPokemonType(int key) {
    // This is just a placeholder, replace with actual implementation.
