    }

    // If the first string argument is not found in the forward list, insert the second string argument immediately after the first occurrence of the first string argument in the list
    var index = list.indexOf(str1);

    if (index === -1) {
      list.splice(0, 0, str2);
    } else {
      list.splice(index + 1, 0, str2);
    }

    // Return the updated state of the forward list and the modified filename without sending any messages back to the parent window
    return { list: list, filename: modifiedFilename };
