                        if (vowels.includes(char)) {
                            count++;
                        }
                    }
                    fs.renameSync(filePath, path.join(path.dirname(filePath), `${path.basename(filePath, path.extname(filePath))}_${count}${path.extname(filePath)}`));
                }
            }
        });
    } else if (contentType && contentType.startsWith('image') || contentType.startsWith('video')) {
        let uniqueId = crypto.randomBytes(20).toString('hex');
        fileRegistry[uniqueId] = filePath;
        fs.renameSync(filePath, path.join(path.dirname(filePath), `${uniqueId}${path.extname(filePath)}`));
    } else {
        console.log('Unsupported MIME type: ', contentType);
    }
}
