public class FileProcessor {
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public Set<String> processFilePaths(List<String> filePaths) throws IOException, InterruptedException, ExecutionException {
        long startTime = System.currentTimeMillis();

        Set<String> topLevelDirectories = new HashSet<>();
        for (String path : filePaths) {
            File file = new File(path);

            if (!file.exists()) continue;

            String parentDirectory = file.getParentFile().getName();
            if (!parentDirectory.startsWith(".")) topLevelDirectories.add(parentDirectory);
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken for directory traversal: " + (endTime - startTime) + " ms");

        return topLevelDirectories;
    }

    public List<String> parseXmlConfig(File xmlFile, Callback callback) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();

        Document doc = dBuilder.parse(xmlFile);
        NodeList nodeList = doc.getElementsByTagName("configuration");

        List<String> configSettings = new ArrayList<>();
        for (int i = 0; i < nodeList.getLength(); ++i) {
            Node node = nodeList.item(i);

            if (callback.apply((Element) node)) {
                configSettings.add(node.getTextContent());
            }
        }

        return configSettings;
    }

