        let mut cache = cache.lock().await;
        if let Some((time, data)) = cache.get(city)? {
            // Refresh the data every 5 minutes.
            if time.elapsed() > Duration::from_secs(5 * 60) {
                spawn_blocking(move || {
                    let new_data = api::fetch_weather_data(city).unwrap();
                    cache.insert(city.to_string(), (Instant::now(), new_data));
                });
            }
            Some(data)
        } else {
            None
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), ReqwestError> {
    let cache = Mutex::new(HashMap::new());
    loop {
        println![Enter a city name (or 'quit' to exit)];
        let mut input = String::new();
        std::io::stdin().read_line(&mut input)?;
        let input = input.trim();
        if input == "quit" {
            break;
        }
        match cache::get(&cache, &input).await {
            Some(data) => println![Weather data for {}: {:?}], input, data),
            None => println![No weather data available for {}], input,
        };
    }
    Ok(())
}
```
