function updatePassword($userId, $oldPassword, $newPassword) {
    // Validate password strength
    if (!validatePasswordStrength($newPassword)) {
        throw new Exception('Invalid password');
    }

    $dao = new UserDao();
    $lock = $dao->acquireLockForUser($userId);

    try {
        $currentPasswordHash = $dao->getCurrentPasswordHash($userId);

        if (!password_verify($oldPassword, $currentPasswordHash)) {
            throw new Exception('Invalid old password');
        }

        $newPasswordHash = password_hash($newPassword, PASSWORD_DEFAULT);
        $dao->updateUserPasswordWithRetry($userId, $newPasswordHash);
    } catch (Exception $e) {
        $lock->release();
        throw $e;
    }

    $lock->release();
}
