2. C function that processes financial transactions:
```c
#include <pthread.h>
#define MAX_TRANSACTIONS 10000
#define WINDOW_SIZE 5

typedef struct {
    int id;
    double priority;
} Transaction;

Transaction slidingWindow[WINDOW_SIZE];
int windowIndex = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
double totalProcessingTime = 0.0;
int transactionsCount = 0;
int maxPriorityId = 0;

void* processTransaction(void* arg) {
    Transaction transaction = *((Transaction*)arg);

    pthread_mutex_lock(&mutex);

    slidingWindow[windowIndex] = transaction;
    windowIndex = (windowIndex + 1) % WINDOW_SIZE;

    if (transaction.priority > maxPriorityId) {
        maxPriorityId = transaction.id;
    }

    transactionsCount++;

    pthread_mutex_unlock(&mutex);
