async function reduceAsync(array, initialValue, callback) {
    let accumulator = initialValue;
    const promises = array.map(async (obj) => {
        try {
            if (!obj || typeof obj.numericValue !== 'number') {
                throw new Error('Invalid object or numeric value');
            }
            accumulator = await callback(accumulator, obj, obj.numericValue);
        } catch (error) {
            console.log(`Error in reduction: ${error}`);
        }
    });

    try {
        await Promise.all(promises);
        return accumulator;
    } catch (error) {
        throw new Error('Reduction failed');
    }
}
