int hashSHA256(HashData* hd) {
    SHA256_CTX context;
    if(!SHA256_Init(&context)) return 1; // Error initializing
    if(!SHA256_Update(&context, hd->data, hd->length)) return 2; // Error updating
    if(!SHA256_Final(hd->hash, &context)) return 3; // Error finalizing
    return 0; // Success
}

int hashMD5(HashData* hd) {
    MD5_CTX context;
    if(!MD5_Init(&context)) return 1; // Error initializing
    if(!MD5_Update(&context, hd->data, hd->length)) return 2; // Error updating
    if(!MD5_Final(hd->hash, &context)) return 3; // Error finalizing
    return 0; // Success
}

int crc32(CRC32Data* cd) {
