    uLongf compressedLength = compressBound(zd->length);
    zd->compressed = (unsigned char*)malloc(sizeof(unsigned char)*compressedLength);
    if(compress2(zd->compressed, &compressedLength, zd->data, zd->length, Z_BEST_COMPRESSION) != Z_OK) return 1; // Error compressing
