['Here is an example of how you might implement such a utility in Java using `javac` and `java` commands through `Runtime.getRuntime().exec()`. This code does not include all the details mentioned in your request due to its complexity, but it provides a good starting point for building a multi-threaded compiler/executor with error handling and logging:

```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DynamicCompiler {
    private static final Logger logger = LoggerFactory.getLogger(DynamicCompiler.class);
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public void compileAndRun(String className, String sourceCode) throws Exception {
        Path pathToClassFile = compileSourceCode(className, sourceCode);
        executeCompiledClass(pathToClassFile);
    }

    private Path compileSourceCode(String className, String sourceCode) throws IOException, InterruptedException, ExecutionException {
        File javaFile = new File(className + ".java");
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(javaFile))) {
            writer.write(sourceCode);
        }

        String[] command = {"javac", javaFile.getAbsolutePath()};
        Process process = Runtime.getRuntime().exec(command);
        process.waitFor();

        if (process.exitValue() != 0) {
            logger.error("Compilation failed for class: {}", className);
            throw new IOException("Compilation failed");
        } else {
            logger.info("Class compiled successfully: {}", className);
        }

        return javaFile.toPath().getParent().resolve(className + ".class");
    }

    private void executeCompiledClass(Path pathToClassFile) throws IOException, InterruptedException {
        String[] command = {"java", "-cp", pathToClassFile.getParent().toString(), Paths.get(pathToClassFile.toString()).getFileName().toString()};

        Process process = Runtime.getRuntime().exec(command);
        executor.submit(() -> printOutput(process.getInputStream()));
        executor.submit(() -> printError(process.getErrorStream()));

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            logger.error("Execution failed for class: {}", pathToClassFile);
            throw new IOException("Execution failed");
        } else {
            logger.info("Class executed successfully: {}", pathToClassFile);
        }
    }

    private void printOutput(InputStream inputStream) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logger.info("STDOUT: {}", line);
            }
        }
    }

    private void printError(InputStream inputStream) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logger.error("STDERR: {}", line);
            }
        }
    }
}
