['Here is a basic implementation in C using libjansson for JSON parsing and pthreads for thread safety. This code does not include all the details you asked for (like web server integration or session_id uniqueness checks), but it should give you an idea of how to approach this problem. 

```c
#include <stdbool.h>
#include <jansson.h>
#include <pthread.h>
#include <time.h>

// Predefined roles
const char* ROLES[] = {"admin", "moderator", "viewer"};
int NUM_ROLES = 3;

// Mutex for thread safety
pthread_mutex_t lock;

bool validate_role(json_t *root, const char *field) {
    json_t *value = json_object_get(root, field);
    if(!json_is_string(value)) return false;

    const char *role = json_string_value(value);
    for(int i = 0; i < NUM_ROLES; ++i) {
        if(strcmp(role, ROLES[i]) == 0) return true;
    }
    return false;
}

bool validate_timestamp(json_t *root, const char *field) {
    json_t *value = json_object_get(root, field);
    if(!json_is_integer(value)) return false;

    time_t expiration_time = (time_t)json_integer_value(value);
    return difftime(expiration_time, time(NULL)) > 0;
}

bool validate_session(const char *json_str) {
    // Parse JSON string
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if(!json_is_object(root)) return false;

    pthread_mutex_lock(&lock);

    // Check required fields
    bool valid = json_object_get(root, "session_id") && validate_timestamp(root, "expiration_time") 
        && validate_role(root, "user_role");

    if(!json_is_string(json_object_get(root, "reset_token"))) valid = false;

    pthread_mutex_unlock(&lock);

    json_decref(root);
    return valid;
}
```

This code uses the Jansson library for JSON parsing and pthreads for thread safety. It first checks if the root is an object, then it locks a mutex to ensure that only one thread can validate a session at a time. Afterwards, it checks if all required fields exist and are of the correct type. If any check fails, it returns false. Otherwise, it returns true.

Please note that this code does not include all the details you asked for (like web server integration or session_id uniqueness checks), but it should give you an idea of how to approach this problem. Also, please make sure to handle errors properly in a production environment. This is just a basic example and may need adjustments based on your specific requirements.
']

