using System;
using System.Text;
using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.Crypto.Engines;
using Org.BouncyCastle.Crypto.Modes;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.Security;
using System.Threading;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Linq;
using System.Net.Http;
using Newtonsoft.Json;

public class DecryptionService
{
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private readonly HttpClient _httpClient;
    private readonly Stopwatch _stopwatch = new Stopwatch();
    private int _successCount = 0;
    private int _failureCount = 0;

    public DecryptionService()
    {
        _httpClient = new HttpClient();
    }

    public async Task<string> DecryptAsync(string cipherText, string keyId)
    {
        var cacheKey = $"{cipherText}_{keyId}";
        if (_cache.TryGetValue(cacheKey, out var decrypted))
            return decrypted;

        await _semaphore.WaitAsync();
        try
        {
            if (_cache.TryGetValue(cacheKey, out decrypted))
                return decrypted;

            _stopwatch.Restart();
            var key = await GetKeyFromConfigStoreAsync(keyId);
            var iv = await GetIvFromConfigStoreAsync(keyId);

            try
            {
                decrypted = DecryptWithTripleDes(cipherText, key, iv) ?? DecryptWithAes256Cbc(cipherText, key, iv);
                _cache.TryAdd(cacheKey, decrypted);
                Interlocked.Increment(ref _successCount);
            }
            catch (Exception ex)
            {
                await LogAsync("Decryption failed", ex);
                Interlocked.Increment(ref _failureCount);
                throw;
            }
        }
        finally
        {
            _semaphore.Release();
        }

        return decrypted;
    }

    private string DecryptWithTripleDes(string cipherText, byte[] key, byte[] iv)
    {
        var tripleDesEngine = new TripleDESEngine();
        var parameters = new ParametersWithIV(new KeyParameter(key), iv);
        var cipher = new PaddedBufferedBlockCipher(new CbcBlockCipher(tripleDesEngine), new Pkcs7Padding());
        cipher.Init(false, parameters);

        byte[] plainTextBytes = new byte[cipher.GetOutputSize(cipherText.Length)];
        int length = cipher.ProcessBytes(Encoding.UTF8.GetBytes(cipherText), 0, cipherText.Length, plainTextBytes, 0);
        length += cipher.DoFinal(plainTextBytes, length);

        return Encoding.UTF8.GetString(plainTextBytes, 0, length);
    }

    private string DecryptWithAes256Cbc(string cipherText, byte[] key, byte[] iv)
    {
        var aesEngine = new AesFastEngine();
        var parameters = new ParametersWithIV(new KeyParameter(key), iv);
        var cipher = new PaddedBufferedBlockCipher(new CbcBlockCipher(aesEngine), new Pkcs7Padding());
        cipher.Init(false, parameters);

        byte[] plainTextBytes = new byte[cipher.GetOutputSize(cipherText.Length)];
        int length = cipher.ProcessBytes(Encoding.UTF8.GetBytes(cipherText), 0, cipherText.Length, plainTextBytes, 0);
        length += cipher.DoFinal(plainTextBytes, length);

        return Encoding.UTF8.GetString(plainTextBytes, 0, length);
    }

