    private Dictionary<string, string> _configPlaceholders = new Dictionary<string, string>();

    public void ProcessLogFile(string logPath)
    {
        try
        {
            using (StreamReader sr = File.OpenText(logPath))
            {
                string line;
                while ((line = sr.ReadLine()) != null)
                {
                    Console.WriteLine("Processing line: " + line);

                    // Calculate MD5 hash for each line
                    using (MD5 md5Hash = MD5.Create())
                    {
                        string hash = GetMd5Hash(md5Hash, line);
                        Console.WriteLine("Line hash: " + hash);
                    }
                }
            }
        }
        catch (Exception e)
        {
            // Log error
            Console.WriteLine("Error processing log file: " + e.Message);
        }
    }

    private string GetMd5Hash(MD5 md5Hash, string input)
    {
        byte[] data = md5Hash.ComputeHash(Encoding.UTF8.GetBytes(input));

        StringBuilder sBuilder = new StringBuilder();

        for (int i = 0; i < data.Length; i++)
        {
            sBuilder.Append(data[i].ToString("x2"));
        }

        return sBuilder.ToString();
    }

    public void ModifyConfigFile(string configPath, Dictionary<string, string> placeholders)
