public class ConfigLoader
{
    private string defaultPath = "default/path"; // replace with your default path

    public T LoadConfig<T>(string fileName, bool isRemote = false) where T : class
    {
        var fullPath = Path.Combine(isRemote ? GetRemoteStoragePath() : defaultPath, fileName);

        if (!File.Exists(fullPath))
            throw new FileNotFoundException("Configuration file not found", fullPath);

        try
        {
            using (var stream = File.OpenRead(fullPath))
            {
                BinaryFormatter formatter = new BinaryFormatter();

                if (fileName.EndsWith(".json")) // check for json file extension
