```cpp
#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <iostream>
#include <string>

namespace net = boost::asio;            // from <boost/asio.hpp>
namespace beast = boost::beast;         // from <boost/beast.hpp>
using tcp = boost::asio::ip::tcp;        // from <boost/asio/ip/tcp.hpp>

int main() {
    net::io_context ioc;
    beast::error_code ec;
    tcp::resolver resolver(ioc);
    beast::tcp_stream stream(ioc);

    auto const results = resolver.resolve("localhost", "80");
    stream.connect(results, ec);

    if (ec) {
        std::cerr << "Error: " << ec.message() << "\n";
        return EXIT_FAILURE;
    }

    beast::http::request<beast::http::string_body> req{beast::http::verb::get, "/", 11};
    req.set(beast::http::field::host, "localhost");
    req.set(beast::http::field::user_agent, BOOST_BEAST_VERSION_STRING);

    beast::http::write(stream, req, ec);

    if (ec) {
        std::cerr << "Error: " << ec.message() << "\n";
        return EXIT_FAILURE;
    }

    beast::flat_buffer buffer;
    beast::http::response<beast::http::dynamic_body> res;

    beast::http::read(stream, buffer, res, ec);

    if (ec) {
        std::cerr << "Error: " << ec.message() << "\n";
        return EXIT_FAILURE;
    }

    std::cout << res << "\n";

    beast::error_code shutdown_ec;
    stream.socket().shutdown(tcp::socket::shutdown_both, shutdown_ec);

    if (shutdown_ec) {
        std::cerr << "Error: " << ec.message() << "\n";
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```
This code creates a simple HTTP GET request to localhost on port 80 and prints the response. It does not cover all aspects of your task, but it should give you a good starting point. You would need to add error handling for duplicate vertex identifiers, malformed edge specifications, probabilistic network delay mechanism, thread pool management, configuration mechanism, user interaction simulation, logging capabilities, etc.
