#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    int* key;
    long offset;
} record;

void manage_memory(long *offsets, int *keys, record **records, size_t n) {
    // Allocate memory for arrays
    offsets = malloc(n * sizeof(long));
    keys = malloc(n * sizeof(int));
    records = malloc(n * sizeof(record*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays and structures
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = i * 10;  // Replace with actual values
        keys[i] = i;         // Replace with actual values

        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        records[i]->value = i;  // Replace with actual values
        records[i]->key = &keys[i];
        records[i]->offset = offsets[i];
    }

    // Use the arrays and structures...
}
```
This code initializes three distinct data structures: an array of 'long' offset values, an array of 'int' keys, and an array of 'record' structures. It handles memory allocation failures gracefully by checking if each malloc call returned NULL and exiting with a failure message if it did. 

