['Here is an example implementation in C using pthreads for threading and a simple logging mechanism to enable or disable logging based on a configuration flag. Note that this code does not include the integration into a larger application as it would require additional context, but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

Record* allocate_records(int count, int minKey, int maxKey, bool logEnabled) {
    srand(time(NULL)); // seed the random number generator

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records && logEnabled) printf("Memory allocation failed.\n");

    for (int i = 0; i < count; ++i) {
        records[i].key = rand() % (maxKey - minKey + 1) + minKey; // random int within range
        records[i].offset = 0L;

        if (logEnabled) printf("Initialized record with key: %d\n", records[i].key);
    }

    return records;
}

void free_records(Record* records, bool logEnabled) {
    free(records);

    if (logEnabled) printf("Freed allocated memory.\n");
}

// Thread-safe initialization and cleanup of records
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
void* thread_func(void* arg) {
    pthread_mutex_lock(&mutex); // lock the mutex before accessing shared data

    Record* records = allocate_records(10, 0, 100, true);

    /* Perform operations on records */

    free_records(records, true);

    pthread_mutex_unlock(&mutex); // unlock the mutex after accessing shared data
}
