            temp = temp->next;
        }

        if (temp->data.RNTI == data.RNTI) {
            printf("Duplicate RNTI found\n");
            return;
        }

        temp->next = newNode;
    }

    count++;

    pthread_mutex_unlock(&lock);
}

void clear() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
