#include <vector>
#include <functional>

class TransformationPipeline {
public:
    using TransformFunc = std::function<std::string(const std::string&)>;

    void addStage(TransformFunc func) {
        stages.push_back(func);
    }

    std::vector<std::string> process(const std::vector<std::string>& input) const {
        std::vector<std::string> output;

        for (const auto& str : input) {
            std::string transformed = str;

            for (const auto& stage : stages) {
                transformed = stage(transformed);
            }

            output.push_back(transformed);
        }

        return output;
    }

private:
    std::vector<TransformFunc> stages;
};
