#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Node {
    double value;
    struct Node* next;
} Node;

Node** node_pool = NULL;
int pool_size = 0;
int used_nodes = 0;
pthread_mutex_t lock;

void init_node_pool(int size) {
    if (node_pool != NULL) free(node_pool);

    node_pool = malloc(sizeof(Node*) * size);
    for (int i = 0; i < size; ++i) {
        node_pool[i] = malloc(sizeof(Node));
        if (node_pool[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    pool_size = size;
}

void cleanup() {
    for (int i = 0; i < used_nodes; ++i) {
        free(node_pool[i]);
    }
    free(node_pool);
}

Node* create_list(int count, double min, double max) {
    if (used_nodes + count > pool_size) {
        fprintf(stderr, "Not enough nodes in the node pool\n");
        return NULL;
    }

    srand(time(NULL));
    Node* head = NULL;
    Node* tail = NULL;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < count; ++i) {
        double random_value = min + ((double)rand() / RAND_MAX) * (max - min);

        if (head == NULL) {
            head = node_pool[used_nodes];
            tail = head;
        } else {
            tail->next = node_pool[used_nodes];
            tail = tail->next;
        }

        tail->value = random_value;
        tail->next = NULL;
        ++used_nodes;
    }
    pthread_mutex_unlock(&lock);

    return head;
}
```
This code creates a node pool and uses it to create linked lists. It ensures thread safety by locking the mutex before accessing the node pool, and releases the lock after modifying the node pool. The cleanup function frees all allocated nodes when the application shuts down. 

