        records[i].key = rand() % (max - min + 1) + min;
        records[i].offset = 0L;
    }

    // Unlock the mutex to allow other threads to access the memory.
    pthread_mutex_unlock(&mutex);

    return records;
}

void free_records(record_t *records) {
    // Lock the mutex to ensure thread-safe cleanup.
    pthread_mutex_lock(&mutex);

    free(records);

    // Unlock the mutex to allow other threads to access the memory.
    pthread_mutex_unlock(&mutex);
}
