#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct NR_DL_FRAME_TRANSPORT_CONTEXT {
    int DL_FRAME_TRANSPORT_TAG;
    void* RLC_PDU_list; // Assuming it's a pointer to some list structure
    int QoS_config;
} NR_DL_FRAME_TRANSPORT_CONTEXT;

typedef struct DynamicArray {
    NR_DL_FRAME_TRANSPORT_CONTEXT* array;
    atomic_int size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;

    da->array = NULL;
    atomic_init(&da->size, 0);
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

void insert(DynamicArray* da, NR_DL_FRAME_TRANSPORT_CONTEXT element) {
    pthread_mutex_lock(&da->lock);

    int oldSize = atomic_load(&da->size);
    da->array = realloc(da->array, (oldSize + 1) * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    if (da->array == NULL) {
        pthread_mutex_unlock(&da->lock);
        return;
    }

    da->array[oldSize] = element;
    atomic_fetch_add(&da->size, 1);

    pthread_mutex_unlock(&da->lock);
}
```
This code creates a dynamic array and provides a thread-safe way to insert elements into it. It uses `pthread_mutex_t` for mutual exclusion and `atomic_int` for atomic operations on the size of the array. The `insert` function is protected by a mutex, ensuring that only one thread can modify the array at a time.

