import os
import logging
from threading import Lock
import requests
from cryptography.fernet import Fernet

# Set up logger
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

class KickstartModifier:
    def __init__(self, api_url):
        self.api_url = api_url
        self.lock = Lock()
        self.key = None
        self.fetch_encryption_key()

    def fetch_encryption_key(self):
        try:
            response = requests.get(self.api_url)
            if response.status_code == 200:
                data = response.json()
                self.key = Fernet(data['key'])
            else:
                logger.error("Failed to fetch encryption key")
        except Exception as e:
            logger.exception("Exception occurred", exc_info=e)

    def modify_file(self, filepath, replacements):
        if not os.path.exists(filepath):
            raise FileNotFoundError('File does not exist')

        with self.lock:
            # Create backup of original file
            backup_file = f'{filepath}.bak'
            os.rename(filepath, backup_file)

            try:
                with open(backup_file, 'r') as read_obj, \
                     open(filepath, 'w') as write_obj:
                    for line in read_obj:
                        new_line = self.replace_placeholders(line, replacements)

                        if 'password' in new_line:
                            encrypted_pwd = self.encrypt_password('dummy_password')  # replace with actual password
                            new_line += f'\nencrypted_password={encrypted_pwd}'

                        write_obj.write(new_line)
            except Exception as e:
                logger.exception("Exception occurred", exc_info=e)

                # If any error occurs, restore backup file
                os.rename(backup_file, filepath)

    def replace_placeholders(self, line, replacements):
        for placeholder, replacement in replacements.items():
            if placeholder in line:
                line = line.replace(placeholder, replacement)
        return line

    def encrypt_password(self, password):
        if self.key is None:
            raise Exception('Encryption key not available')

        encoded_pwd = password.encode()
        encrypted_pwd = self.key.encrypt(encoded_pwd)
        return encrypted_pwd.decode()
