SSL_CTX *createDirAndSetEnv(const char* dirName, const char* envVar) {
    // Validate command line option
    if (dirName == NULL || envVar == NULL) {
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    struct stat st = {0};

    // Check for the existence of the specified directory
    if (stat(dirName, &st) == -1) {
        mkdir(dirName, 0700);

        // Handle creation of the directory and error checking
        if (errno == EEXIST) {
            fprintf(stderr, "Directory %s already exists\n", dirName);
            return NULL;
        } else if (errno == ENOSPC || errno == EROFS || errno == EACCES) {
            perror("Failed to create directory");
            return NULL;
        }
    }

    // Set or update the environment variable
    setenv(envVar, dirName, 1);

    // Create a new SSL_CTX object (you may need to adjust this depending on your actual use case)
    SSL_CTX *ctx = SSL_CTX_new(TLS_method());
    if (!ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        return NULL;
    }

    // Return the pointer to the cipher object
    return ctx;
}
```
