    if (manager == NULL) return NULL;

    manager->contexts = calloc(initialCapacity, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT*));
    if (manager->contexts == NULL) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void addFrame(FrameManager* manager, NR_DL_FRAME_TRANSPORT_CONTEXT* context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        // Double the capacity when full
        size_t newCapacity = manager->capacity * 2;
        NR_DL_FRAME_TRANSPORT_CONTEXT** newContexts = realloc(manager->contexts, newCapacity * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT*));

        if (newContexts == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->contexts = newContexts;
        manager->capacity = newCapacity;
    }

    manager->contexts[manager->count++] = context;

    pthread_mutex_unlock(&manager->lock);
}

