int maxSize = 5000; // Default maximum size
bool loggingEnabled = false; // Enable or disable logging

void insert(LTEUEContextInfoStructure data) {
    assert(data.UE_ID != -1 && data.ServingCellID != -1); // Validation checks

    pthread_mutex_lock(&lock);
    if (loggingEnabled) printf("Inserting UE ID: %d\n", data.UE_ID);

    Node* temp = malloc(sizeof(Node));
    temp->data = data;
    temp->next = head;
    head = temp;

    // Check if we've exceeded the maximum size and remove elements as needed.
    int count = 0;
    for (Node* curr = head; curr != NULL; curr = curr->next) {
        if (++count > maxSize) {
            Node* toRemove = curr;
            curr = curr->next;

            if (loggingEnabled) printf("Removing UE ID: %d\n", toRemove->data.UE_ID);
            free(toRemove);
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list for the dynamic list of LTE UE Context Information Structures, with each node containing an instance of `LTEUEContextInfoStructure`. The function `insert()` is thread-safe and ensures that no two threads can modify the list at the same time by using a mutex lock.

