```c
#include <pthread.h>
#include <glib.h>
#include <stdlib.h>

typedef struct {
    long offset;
    int key;
    char* identifier;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
GHashTable* cache = NULL;
Node** array = NULL;
int size = 0;

void init() {
    cache = g_hash_table_new(g_direct_hash, g_direct_equal);
}

Record* getRecord(long offset) {
    Record* record = (Record*)g_hash_table_lookup(cache, GINT_TO_POINTER(offset));

    if (!record) {
        pthread_mutex_lock(&lock);

        // Check again after locking to avoid race condition
        record = (Record*)g_hash_table_lookup(cache, GINT_TO_POINTER(offset));
        if (!record) {
            record = malloc(sizeof(Record));

            if (!record) {
                pthread_mutex_unlock(&lock);
                return NULL; // Handle memory allocation failure
            }

            g_hash_table_insert(cache, GINT_TO_POINTER(offset), record);
        }

        pthread_mutex_unlock(&lock);
    }

    return record;
}

void addRecord(long offset, int key, char* identifier) {
    Record* record = getRecord(offset);

    if (!record) {
        // Handle memory allocation failure
        return;
    }

    record->offset = offset;
    record->key = key;
    record->identifier = identifier;

    Node* node = malloc(sizeof(Node));

    if (!node) {
        // Handle memory allocation failure
        return;
    }

    node->record = record;
    pthread_mutex_lock(&lock);
    array[size++] = node;
    pthread_mutex_unlock(&lock);
}
```
