// Define a struct to hold file information and results
typedef struct {
    char *filename;
    int line_count;
} FileInfo;

// Global variables for thread synchronization and logging
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void *processFile(void *arg) {
    // Cast the argument back to a FileInfo struct
    FileInfo *info = (FileInfo *) arg;

    // Open the file and handle errors
    FILE *file = fopen(info->filename, "r");
    if (!file) {
        pthread_mutex_lock(&log_lock);
        fprintf(log_file, "Error opening file %s\n", info->filename);
        pthread_mutex_unlock(&log_lock);
        return NULL;
    }

    // Count the lines in the file and handle errors
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        info->line_count++;

        // Handle command-line options for filtering specific types of lines
        if (/* filter condition */) {
            continue;
        }
    }

    fclose(file);

    return NULL;
}

int main(int argc, char *argv[]) {
    // Open the log file and handle errors
    log_file = fopen("log.txt", "w");
    if (!log_file) {
        printf("Error opening log file\n");
        return 1;
    }

    // Create an array of FileInfo structs for each input file
    int numFiles = argc - 1;
    FileInfo *files = malloc(numFiles * sizeof(FileInfo));
    pthread_t threads[numFiles];

    for (int i = 0; i < numFiles; i++) {
        files[i].filename = argv[i + 1];
        files[i].line_count = 0;

        // Create a thread to process each file and handle errors
        if (pthread_create(&threads[i], NULL, processFile, &files[i])) {
            pthread_mutex_lock(&log_lock);
            fprintf(log_file, "Error creating thread for file %s\n", files[i].filename);
            pthread_mutex_unlock(&log_lock);
        }
    }

    // Wait for all threads to finish and handle errors
    for (int i = 0; i < numFiles; i++) {
        if (pthread_join(threads[i], NULL)) {
            pthread_mutex_lock(&log_lock);
            fprintf(log_file, "Error joining thread for file %s\n", files[i].filename);
            pthread_mutex_unlock(&log_lock);
        }
    }

    // Aggregate the line counts and print results
    int total = 0;
    for (int i = 0; i < numFiles; i++) {
        printf("File %s: %d lines\n", files[i].filename, files[i].line_count);
        total += files[i].line_count;
    }

    printf("Total: %d lines\n", total);

    // Handle command-line options for exporting results to a CSV file
    if (/* export condition */) {
        FILE *csv = fopen("results.csv", "w");

        // Write the line counts to the CSV file and handle errors
        if (!csv) {
            pthread_mutex_lock(&log_lock);
            fprintf(log_file, "Error opening CSV file for writing\n");
            pthread_mutex_unlock(&log_lock);
        } else {
            for (int i = 0; i < numFiles; i++) {
                fprintf(csv, "%s,%d\n", files[i].filename, files[i].line_count);
            }

            fclose(csv);
        }
    }

    // Clean up and exit
    free(files);
    fclose(log_file);
    return 0;
}
```
