import gzip
import brotli
from collections import Counter
from heapq import nlargest

def process_sessions(file_list):
    behavior_counter = Counter()
    first_occurrence = {}
    last_occurrence = {}

    for file in file_list:
        if file.endswith('.gz'):
            open_func = gzip.open
        elif file.endswith('.br'):
            open_func = brotli.open
        else:
            open_func = open

        with open_func(file, 'rt') as f:
            for line in f:
                try:
                    timestamp, behavior = line.strip().split('\t')  # assuming tab-separated values

                    if behavior not in first_occurrence:
                        first_occurrence[behavior] = timestamp

                    last_occurrence[behavior] = timestamp

                    behavior_counter[behavior] += 1
                except Exception as e:
                    print(f"Error processing line {line}: {str(e)}")

    top_behaviors = nlargest(10, behavior_counter, key=behavior_counter.get)

    result = {}
    for behavior in top_behaviors:
        result[behavior] = {'count': behavior_counter[behavior], 
                            'first_occurrence': first_occurrence[behavior], 
                            'last_occurrence': last_occurrence[behavior]}

    return result
```
This function reads each file in the list, decompresses it if necessary, and processes each line. It keeps track of the count of each behavior, as well as the first and last occurrence timestamp for each behavior. Finally, it returns a dictionary with the top 10 behaviors along with their counts and timestamps.
