['Here is a basic implementation of `parseXMLHashStream` in C using libxml2 for XML parsing and OpenSSL for cryptographic hashing. This code does not include all the features you mentioned (like logging, concurrency control, partial hash computation, error recovery, etc.), but it provides a starting point:

```c
#include <libxml/parser.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <string.h>

typedef enum {SHA256, SHA3, BLAKE2B} HashAlgorithm;

void* parseXMLHashStream(const char *xmlDoc, const char *targetElementName, HashAlgorithm algorithm) {
    xmlDocPtr doc;
    xmlNodePtr cur;
    SHA_CTX ctx;

    // Parse XML document
    doc = xmlReadMemory(xmlDoc, strlen(xmlDoc), "", NULL, 0);
    if (doc == NULL) {
        printf("Failed to parse XML\n");
        return NULL;
    }

    // Initialize hash context
    switch (algorithm) {
        case SHA256:
            SHA256_Init(&ctx);
            break;
        /* Add cases for other algorithms */
        default:
            printf("Unsupported algorithm\n");
            return NULL;
    }

    // Find target element and compute hash
    cur = xmlDocGetRootElement(doc);
    while (cur != NULL) {
        if ((cur->type == XML_ELEMENT_NODE) && (xmlStrEqual(cur->name, (const xmlChar *)targetElementName))) {
            xmlChar *content = xmlNodeListGetString(doc, cur->xmlChildrenNode, 1);
            switch (algorithm) {
                case SHA256:
                    SHA256_Update(&ctx, content, strlen((char *)content));
                    break;
                /* Add cases for other algorithms */
            }
            xmlFree(content);
        }

        cur = cur->next;
    }

    // Finalize hash and return context
    switch (algorithm) {
        case SHA256:
            SHA256_Final(&ctx, NULL);
            break;
        /* Add cases for other algorithms */
    }

    xmlFreeDoc(doc);

    // Allocate and return dynamically allocated context
    void *hashCtx = malloc(sizeof(SHA_CTX));
    memcpy(hashCtx, &ctx, sizeof(SHA_CTX));
    return hashCtx;
}
```
