public class DataProcessor
{
    private const int BASE_OFFSET = 10;
    private long[] OffsetArray { get; set; }
    private int[] KeyArray { get; set; }
    private Record[] RecordArray { get; set; }
    private MetaData MetaData { get; set; }

    public DataProcessor(int nOffsets, int minValue, int maxValue, int nRecords)
    {
        OffsetArray = new long[nOffsets];
        for (int i = 0; i < nOffsets; i++)
            OffsetArray[i] = checked((long)i + BASE_OFFSET); // Checked to prevent overflow

        KeyArray = new int[nOffsets];
        for (int i = 0; i < nOffsets; i++)
            KeyArray[i] = SqrtRoundedDown(OffsetArray[i]);

        RecordArray = new Record[nRecords];
        Random rand = new Random();
        for (int i = 0; i < nRecords; i++)
            RecordArray[i] = new Record { Key = KeyArray[rand.Next(KeyArray.Length)], Value = rand.Next(minValue, maxValue + 1) };
    }

    private int SqrtRoundedDown(long n)
    {
        if (n < 0) throw new ArgumentOutOfRangeException("Cannot calculate square root of negative number");
        long result = (long)Math.Sqrt(n);
        return unchecked((int)result); // Unchecked to allow overflow and truncate towards zero
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        sb.AppendLine("DataProcessor:");
        sb.AppendLine($"OffsetArray length: {OffsetArray.Length}");
        sb.AppendLine($"KeyArray length: {KeyArray.Length}");
        sb.AppendLine($"RecordArray length: {RecordArray.Length}");
        return sb.ToString();
    }
}

