typedef struct Node {
    char *class;
    char *id;
    char *textContent;
    struct Node **children;
} Node;

void processDocument(Node *root, const char *selector, int sizeLimit, void (*callback)(Node*, char**)) {
    if (root == NULL) return;

    // Check selector against class or id of current node
    if ((strcmp(selector, root->class) == 0 || strcmp(selector, root->id) == 0) && 
        strlen(root->textContent) > sizeLimit) {

        char **result = malloc(sizeof(char*)); // Dynamically allocate memory for result string
        *result = NULL;

        callback(root, result); // Call the provided callback function

        if (*result != NULL) printf("%s\n", *result); // Print the result string

        free(result); // Free the dynamically allocated memory
    }

    // Recursively process children nodes
    for (int i = 0; root->children[i] != NULL; i++) {
        processDocument(root->children[i], selector, sizeLimit, callback);
    }
}

void callbackExample(Node *node, char **result) {
    if (*result == NULL) { // If result string is empty, allocate memory for it
        *result = malloc((strlen(node->textContent) + 2) * sizeof(char)); 
        strcpy(*result, "/");
    } else { // Otherwise, reallocate memory to make room for the new text content
        *result = realloc(*result, (strlen(*result) + strlen(node->textContent) + 2) * sizeof(char)); 
        strcat(*result, "/");
    }

    // Append the node's text content to the result string
    strcat(*result, node->textContent);
}
