typedef struct DynamicArray {
    NR_DL_FRAME_TRANSPORT_CONTEXT *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initArray(DynamicArray *a, size_t initialSize) {
    a->array = (NR_DL_FRAME_TRANSPORT_CONTEXT *)malloc(initialSize * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertArray(DynamicArray *a, NR_DL_FRAME_TRANSPORT_CONTEXT element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (NR_DL_FRAME_TRANSPORT_CONTEXT *)realloc(a->array, a->size * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void freeArray(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
    pthread_mutex_destroy(&a->lock);
}
```
