        fprintf(stderr, "Error: Attempted to allocate more than the maximum allowed PDUs\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for PDUs: %s\n", strerror(errno));
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num; ++i) {
        pdu[i].RX_UE_INFORMATION_TAG = MIN_RX_UE_INFORMATION_TAG + rand() % (MAX_RX_UE_INFORMATION_TAG - MIN_RX_UE_INFORMATION_TAG + 1);
        assert(pdu[i].RX_UE_INFORMATION_TAG >= MIN_RX_UE_INFORMATION_TAG && pdu[i].RX_UE_INFORMATION_TAG <= MAX_RX_UE_INFORMATION_TAG);

        pdu[i].RNTI = rand();
        pdu[i].CRC_INDICATION_REL8_TAG = MIN_CRC_INDICATION_REL8_TAG + rand() % (MAX_CRC_INDICATION_REL8_TAG - MIN_CRC_INDICATION_REL8_TAG + 1);
        assert(pdu[i].CRC_INDICATION_REL8_TAG >= MIN_CRC_INDICATION_REL8_TAG && pdu[i].CRC_INDICATION_REL8_TAG <= MAX_CRC_INDICATION_REL8_TAG);
    }

    return pdu;
}
