Record** records = NULL;
Metadata** metadata = NULL;
int numRecords = 0;
pthread_mutex_t lock;
char* predefinedWords[] = {"word1", "word2", "word3"}; // replace with your words
const int numPredefinedWords = sizeof(predefinedWords) / sizeof(char*);

void initRecord(Record* record, float min, float max) {
    if (record == NULL) return;

    record->value = ((float)rand()/(float)(RAND_MAX)) * (max - min) + min;
    int index = rand() % numPredefinedWords;
    record->str = malloc(sizeof(char) * (strlen(predefinedWords[index]) + 1));
    strcpy(record->str, predefinedWords[index]);

    time(&record->timestamp);
    record->refCount = 0;
}

void initMetadata(Metadata* metadata) {
    if (metadata == NULL) return;

    time(&metadata->timestamp);
    metadata->record = NULL;
}

Record* createRecord(float min, float max) {
    Record* record = malloc(sizeof(Record));
    initRecord(record, min, max);
    return record;
}

Metadata* createMetadata() {
    Metadata* metadata = malloc(sizeof(Metadata));
    initMetadata(metadata);
    return metadata;
}

void addRecord(float min, float max) {
    pthread_mutex_lock(&lock);

    Record* record = createRecord(min, max);
    Metadata* meta = createMetadata();
    meta->record = record;

    records = realloc(records, sizeof(Record*) * (numRecords + 1));
    metadata = realloc(metadata, sizeof(Metadata*) * (numRecords + 1));

    records[numRecords] = record;
    metadata[numRecords] = meta;

    numRecords++;

    pthread_mutex_unlock(&lock);
}

void freeRecord(Record* record) {
    if (record == NULL) return;

    free(record->str);
    free(record);
}

void removeRecord(int index) {
    pthread_mutex_lock(&lock);

    if (index < 0 || index >= numRecords) {
        pthread_mutex_unlock(&lock);
        return;
    }

    freeRecord(records[index]);
    free(metadata[index]);

    for (int i = index; i < numRecords - 1; ++i) {
        records[i] = records[i + 1];
        metadata[i] = metadata[i + 1];
    }

    numRecords--;
    records = realloc(records, sizeof(Record*) * numRecords);
    metadata = realloc(metadata, sizeof(Metadata*) * numRecords);

    pthread_mutex_unlock(&lock);
}
```
