```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    float value;
    time_t timestamp;
} record;

typedef struct {
    long* offsets;
    unsigned short* ids;
    record* records;
    size_t count;
    pthread_mutex_t mutex;
} DataStructures;

DataStructures* initialize(size_t count, float min, float max) {
    srand(time(NULL));

    DataStructures* ds = malloc(sizeof(DataStructures));
    if (ds == NULL) return NULL;

    pthread_mutex_init(&ds->mutex, NULL);

    ds->offsets = calloc(count, sizeof(long));
    ds->ids = calloc(count, sizeof(unsigned short));
    ds->records = malloc(count * sizeof(record));

    if (ds->offsets == NULL || ds->ids == NULL || ds->records == NULL) {
        cleanup(ds);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        float random = ((float)rand()/(float)(RAND_MAX)) * max + min;

        ds->records[i].value = random;
        ds->records[i].timestamp = time(NULL);
    }

    return ds;
}

void cleanup(DataStructures* ds) {
    pthread_mutex_lock(&ds->mutex);

    free(ds->offsets);
    free(ds->ids);
    free(ds->records);
    pthread_mutex_unlock(&ds->mutex);

    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}
```
This code uses a mutex to ensure that only one thread can access the data structures at a time. This is necessary because multiple threads could potentially be trying to modify or deallocate the same memory concurrently, which would lead to undefined behavior. 

The `initialize` function allocates and initializes all of the required data structures. It uses calloc for the arrays of longs and unsigned shorts to ensure that they are initialized with zeroes, which can be important in some contexts. The records array is allocated using malloc because we need to manually initialize each record. 

The `cleanup` function deallocates all of the memory associated with a DataStructures object. It locks the mutex before freeing any memory to ensure that no other thread is accessing it, then unlocks the mutex and destroys it to prevent future access attempts. Finally, it frees the DataStructures object itself. 

This code assumes that the system has sufficient memory for all of the allocated structures. If this assumption does not hold, additional error checking would be necessary to handle out-of-memory conditions gracefully. It also assumes that the random number generator is sufficiently random and uniformly distributed over its range. Finally, it assumes that the time function returns a valid timestamp.
