namespace RandomEngine {
    class RandomNumberGenerator {
        private:
            std::mt19937 gen;
            std::uniform_int_distribution<uint64_t> dis;
            uint64_t seed;
            static std::mutex mtx;
            static std::ofstream logFile;

        public:
            RandomNumberGenerator(uint64_t seed) : gen(seed), dis(1, 1000), seed(seed) {
                std::lock_guard<std::mutex> lock(mtx);
                logFile << "Initialized with seed: " << seed << std::endl;
            }

            ~RandomNumberGenerator() {
                std::lock_guard<std::mutex> lock(mtx);
                logFile << "Destroyed" << std::endl;
            }

            static std::vector<uint64_t> generateSequence(uint64_t seed) {
                auto start = std::chrono::high_resolution_clock::now();

                RandomNumberGenerator gen(seed);
                std::vector<uint64_t> sequence;
                for (int i = 0; i < 1000; ++i) {
                    sequence.push_back(gen.dis(gen.gen));
                }

                auto end = std::chrono::high_resolution_clock::now();
                double elapsedTimeMs = std::chrono::duration<double, std::milli>(end-start).count();

                std::lock_guard<std::mutex> lock(mtx);
                logFile << "Generated sequence with seed: " << seed 
                        << ", start time: " << start.time_since_epoch().count()
                        << ", end time: " << end.time_since_epoch().count()
                        << ", elapsed time: " << elapsedTimeMs << std::endl;

                return sequence;
            }
    };

    std::mutex RandomNumberGenerator::mtx;
    std::ofstream RandomNumberGenerator::logFile("generator.log");
}
```
