        // Update display settings based on parsed values and current ambient light level...

        pthread_mutex_unlock(&g_displaySettings.lock);
    }

    json_decref(root);
}

void handleRequests() {
    while (1) {
        // Receive JSON string from network...
        char *jsonStr = receiveJson();

        if (!jsonStr) continue;  // Handle temporary failures...

        json_error_t error;
        json_t *root = json_loads(jsonStr, 0, &error);
        free(jsonStr);

        if(!root) {
            // Handle JSON parsing errors...
        } else {
            pthread_t threadId;
            int result = pthread_create(&threadId, NULL, updateCallback, root);

            if (result != 0) {
                // Handle thread creation error...
            } else {
                pthread_detach(threadId);  // Reclaim resources when done.
            }
        }
    }
}
