['Here is an example of how you might implement such a database in C. This code does not include thread safety or stress testing optimizations as those would significantly increase the complexity of this example, but they are important considerations for any real-world application. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record* records;
} Database;

// Initialize the database with a specified number of records
void initDatabase(Database* db, size_t initialCapacity) {
    db->records = (Record*)malloc(initialCapacity * sizeof(Record));
    if (!db->records) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    db->capacity = initialCapacity;
    db->count = 0;
}

// Populate the records with unique integer values within a given range
void populateDatabase(Database* db, int minValue, int maxValue) {
    if (db->count >= db->capacity) {
        // Handle database full error
        return;
    }

    Record newRecord = {.key = db->count, .value = rand() % (maxValue - minValue + 1) + minValue};
    db->records[db->count] = newRecord;
    db->count++;
}

// Retrieve a record by its key using a linear search approach
Record* getRecord(Database* db, int key) {
    for (size_t i = 0; i < db->count; ++i) {
        if (db->records[i].key == key) {
            return &db->records[i];
        }
    }

    // Handle non-existent key error
    return NULL;
}

// Resize the database to a new capacity
void resizeDatabase(Database* db, size_t newCapacity) {
    Record* newRecords = (Record*)realloc(db->records, newCapacity * sizeof(Record));
    if (!newRecords) {
        // Handle memory allocation failure
        return;
    }

    db->records = newRecords;
    db->capacity = newCapacity;
}

// Free the allocated memory for the database records
void freeDatabase(Database* db) {
    free(db->records);
    db->count = 0;
    db->capacity = 0;
}
```
This code provides a simple and efficient way to manage a dynamic database of records. It uses `malloc` for initial allocation, `realloc` for resizing the database, and `free` for deallocation. The linear search approach is used for retrieving records by key, which is suitable for small databases but could be improved for larger ones using more efficient data structures or algorithms.
']

