class DynamicArrayManager {
public:
    DynamicArrayManager() = default;
    ~DynamicArrayManager();

    void addFrame(const NR_DL_FRAME_TRANSPORT_CONTEXT& frame);
    void updateFrame(int tag, const NR_DL_FRAME_TRANSPORT_CONTEXT& newFrame);
    void cleanup();

private:
    std::vector<NR_DL_FRAME_TRANSPORT_CONTEXT> frames;
    std::mutex mtx; // For thread safety.
};

DynamicArrayManager::~DynamicArrayManager() {
    cleanup();
}

void DynamicArrayManager::addFrame(const NR_DL_FRAME_TRANSPORT_CONTEXT& frame) {
    std::lock_guard<std::mutex> lock(mtx);
    frames.push_back(frame);
}

void DynamicArrayManager::updateFrame(int tag, const NR_DL_FRAME_TRANSPORT_CONTEXT& newFrame) {
    std::lock_guard<std::mutex> lock(mtx);
    for (auto& frame : frames) {
        if (frame.DL_FRAME_TRANSPORT_TAG == tag) {
            frame = newFrame;
            return;
        }
    }
    throw std::runtime_error("No frame with the given tag exists.");
}

void DynamicArrayManager::cleanup() {
    std::lock_guard<std::mutex> lock(mtx);
    frames.clear();
}
