    record->string = strdup(string);
    record->value = value;
    record->timestamp = time(NULL);
    record->refCount = 0;
    record->parent = NULL;

    pthread_mutex_lock(&lock);

    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        free(record);
        return;
    }

    node->record = record;
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
}
