['Here is a high-level implementation of your requirements in Java. Please note that this is just a skeleton, you would need to fill out the details based on your specific needs. 

```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.io.*;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.concurrent.atomic.AtomicInteger;
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.*;

public class BatchProcessor {
    private static final Logger logger = LoggerFactory.getLogger(BatchProcessor.class);
    private static final int MAX_STRING_SIZE = 1024 * 1024; // 1MB
    private static final int MAX_CONCURRENT_PROCESSING = 100;
    private static final long MAX_MEMORY_FOOTPRINT = 50L * 1024 * 1024; // 50MB

    private ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_PROCESSING);
    private Map<String, String> cache = new ConcurrentHashMap<>();
    private AtomicInteger totalProcessedStrings = new AtomicInteger(0);

    public void processBatch(List<String> batch) {
        List<Future<String>> futures = new ArrayList<>();

        for (String str : batch) {
            if (str.length() > MAX_STRING_SIZE) {
                logger.error("Invalid string: {}", str);
                continue;
            }

            Future<String> future = executor.submit(() -> process(str));
            futures.add(future);
        }

        for (Future<String> future : futures) {
            try {
                String hash = future.get();
                logger.info("Processed string: {}", hash);
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                logger.error("Failed to process string", e);
            }
        }

        logger.info("Total processed strings: {}", totalProcessedStrings.get());
    }

    private String process(String str) {
        if (cache.containsKey(str)) {
            return cache.get(str);
        }

        long startTime = System.currentTimeMillis();
        String hash = DigestUtils.md5Hex(str);
        long endTime = System.currentTimeMillis();

        logger.info("Processing time for string: {} ms", (endTime - startTime));

        cache.put(str, hash);
        totalProcessedStrings.incrementAndGet();

        return hash;
    }

    public static void main(String[] args) {
        BatchProcessor processor = new BatchProcessor();
        List<String> batch = Arrays.asList("string1", "string2", "string3");
        processor.processBatch(batch);
    }
}
```
This code uses Apache Commons Codec for MD5 hashing, SLF4J for logging, and Java's built-in concurrency utilities for threading and synchronization. It also uses a ConcurrentHashMap to implement a simple cache of processed strings. The processBatch method processes each string in its own thread using an ExecutorService. If the string is already in the cache, it retrieves the hash from the cache instead of re-computing it.
']

