    const response = await axios.get('http://external-service/resource/' + req.params.id);
    if (response.data.state !== 'valid') return res.status(403).send('Resource is not valid');

    // Update resource in database
    const updatedResource = await updateResourceInDatabase(req.params.id, req.body);
    res.send(updatedResource);
  } catch (err) {
    console.error(err);
    res.status(500).send('An error occurred while updating the resource');
  }
});

