['This task is quite complex and involves multiple aspects of programming including dynamic memory management, concurrent access control, efficient memory usage, string generation, random number generation, etc. Here's a simplified version of the code to get you started:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char* string;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NR_DL_FRAME_TRANSPORT_CONTEXT;

NR_DL_FRAME_TRANSPORT_CONTEXT* createContext(size_t offset_count, size_t key_count, size_t string_length, int min_value, int max_value) {
    srand(time(NULL));

    NR_DL_FRAME_TRANSPORT_CONTEXT* context = malloc(sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    if (context == NULL) return NULL;

    context->offsets = calloc(offset_count, sizeof(long));
    context->keys = calloc(key_count, sizeof(int));
    context->records = malloc(sizeof(record*) * key_count);
    if (context->offsets == NULL || context->keys == NULL || context->records == NULL) {
        freeContext(context);
        return NULL;
    }

    for (int i = 0; i < key_count; ++i) {
        record* rec = malloc(sizeof(record));
        if (rec == NULL) {
            freeContext(context);
            return NULL;
        }

        rec->value = rand() % (max_value - min_value + 1) + min_value;
        rec->string = malloc(sizeof(char) * (string_length + 1));
        if (rec->string == NULL) {
            freeContext(context);
            return NULL;
        }

        strcpy(rec->string, "PREFIX");
        for (int j = 6; j < string_length; ++j) {
            rec->string[j] = rand() % ('z' - 'a' + 1) + 'a';
        }
        rec->string[string_length] = '\0';

        context->records[i] = rec;
    }

    pthread_mutex_init(&context->lock, NULL);
    return context;
}

void freeContext(NR_DL_FRAME_TRANSPORT_CONTEXT* context) {
    if (context == NULL) return;

    for (int i = 0; i < context->count; ++i) {
        free(context->records[i]->string);
        free(context->records[i]);
    }

    free(context->offsets);
    free(context->keys);
    free(context->records);
    pthread_mutex_destroy(&context->lock);
    free(context);
}
```
This code creates a `NR_DL_FRAME_TRANSPORT_CONTEXT` structure with the specified parameters. It uses dynamic memory allocation for each element in the arrays and for the records, ensuring efficient use of memory. The strings are initialized with a prefix "PREFIX" followed by random alphanumeric characters.

