int compare(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;

    if(pduA->rx_ue_information_tag.RNTI == pduB->rx_ue_information_tag.RNTI) {
        return pduB->crc_indication_rel8_tag.CRCFLAG - pduA->crc_indication_rel8_tag.CRCFLAG;
    } else {
        return pduA->rx_ue_information_tag.RNTI - pduB->rx_ue_information_tag.RNTI;
    }
}

int generatePDU(NFAPI_CRC_INDICATION_PDU_T **list, int maxSize) {
    srand(time(NULL));

    *list = malloc(maxSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(*list == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    for(int i = 0; i < maxSize; i++) {
        (*list)[i].rx_ue_information_tag.RNTI = rand() % 65536; // Assuming RNTI is a 16-bit value
        (*list)[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Assuming CRCFLAG is binary
    }

    qsort(*list, maxSize, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);

    for(int i = 1; i < maxSize; i++) {
        if((*list)[i].rx_ue_information_tag.RNTI == (*list)[i-1].rx_ue_information_tag.RNTI) {
            printf("Duplicate RNTI found, regenerating list\n");
            free(*list);
            return generatePDU(list, maxSize); // Recursive call to handle duplicates
        }
    }

    return 0;
}
