#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

typedef struct {
    int key;
    size_t offset;
    int value;
} Record;

Record* createRecord(int key, size_t offset, int min, int max) {
    if (min > max) {
        fprintf(stderr, "Invalid range: %d to %d\n", min, max);
        return NULL;
    }

    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        return NULL;
    }

    record->key = key;
    record->offset = offset;
    record->value = min + rand() % (max - min + 1);

    return record;
}

void destroyRecord(Record* record) {
    free(record);
}

int serializeRecord(const Record* record, char** buffer) {
    *buffer = malloc(sizeof(Record));
    if (!(*buffer)) {
        perror("Failed to allocate memory for serialized record");
        return -1;
    }

    memcpy(*buffer, record, sizeof(Record));

    return 0;
}

int deserializeRecord(const char* buffer, Record** record) {
    *record = malloc(sizeof(Record));
    if (!(*record)) {
        perror("Failed to allocate memory for deserialized record");
        return -1;
    }

    memcpy(*record, buffer, sizeof(Record));

    return 0;
}

int executeSQLCommand(sqlite3* db, const char* command) {
    char* errorMessage = NULL;
    int result = sqlite3_exec(db, command, NULL, NULL, &errorMessage);

    if (result != SQLITE_OK) {
        fprintf(stderr, "Failed to execute SQL command: %s\n", errorMessage);
        sqlite3_free(errorMessage);
    }

    return result;
}
```
