```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Node {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct Node* next;
} Node;

Node* nodePool = NULL;
int poolSize = 0;
pthread_mutex_t lock;

void init(int size) {
    srand(time(NULL));
    pthread_mutex_init(&lock, NULL);

    nodePool = (Node*) malloc(sizeof(Node) * size);
    for (int i = 0; i < size; ++i) {
        nodePool[i].next = (i == size - 1) ? NULL : &nodePool[i + 1];
    }

    poolSize = size;
}

Node* allocate() {
    pthread_mutex_lock(&lock);
    Node* node = nodePool;
    if (node != NULL) {
        nodePool = node->next;
    } else {
        printf("Memory allocation failed\n");
    }
    pthread_mutex_unlock(&lock);

    return node;
}

void deallocate(Node* node) {
    if (node != NULL) {
        pthread_mutex_lock(&lock);
        node->next = nodePool;
        nodePool = node;
        pthread_mutex_unlock(&lock);
    }
}

void cleanup() {
    free(nodePool);
    pthread_mutex_destroy(&lock);
}
```
