import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class FileProcessor {
    private static final int MAX_FILENAME_LENGTH = 255;
    private static final String FILE_EXTENSIONS = "txt,docx,pdf"; // replace with your file extensions

    public void processFiles(List<String> filenames) throws Exception {
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (String filename : filenames) {
            executorService.execute(() -> {
                try {
                    String sanitizedFilename = sanitizeFileName(filename);
                    String md5Hash = getMD5Hash(sanitizedFilename);
                    String newFilename = generateNewName(md5Hash, sanitizedFilename);

                    // Assuming you have a logging system in place.
                    Logger.log("Processed file: " + filename + ". New name: " + newFilename);
                } catch (Exception e) {
                    Logger.error("Error processing file: " + filename, e);
                }
            });
        }

        executorService.shutdown();
    }

    private String sanitizeFileName(String filename) {
        return filename.replaceAll("[^a-zA-Z0-9]", "");
    }

    private String getMD5Hash(String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        return new BigInteger(1, messageDigest).toString(16);
    }

    private String generateNewName(String hash, String sanitizedFilename) {
        String fileExtension = getFileExtension(sanitizedFilename);

        if (fileExtension == null) {
            throw new IllegalArgumentException("Invalid filename: " + sanitizedFilename);
        }

        int sequenceNumber = 1; // replace with your logic to generate a unique numeric sequence
        String newName = hash + "_" + sequenceNumber + "." + fileExtension;

        if (newName.length() > MAX_FILENAME_LENGTH) {
            throw new IllegalArgumentException("New filename too long: " + newName);
        }

        return newName;
    }

    private String getFileExtension(String sanitizedFilename) {
        List<String> extensions = Arrays.asList(FILE_EXTENSIONS.split(","));

        for (String extension : extensions) {
            if (sanitizedFilename.endsWith(extension)) {
                return extension;
            }
        }

        return null;
    }
}
```
