['Here is a basic implementation of your request in Java. This solution does not include actual integration with an external data source, as it would require specific details about the API you are using. 

```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.time.*;
import java.util.concurrent.*;

public class HashProcessor {
    private static final int MAX_SIZE = 1024;
    private static final double CPU_LIMIT = 0.9;

    public Map<String, String> processStrings(List<String> strings) {
        Map<String, String> hashes = new HashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool((int)(Runtime.getRuntime().availableProcessors() * CPU_LIMIT));

        for (String string : strings) {
            if (string.length() > MAX_SIZE) {
                System.out.println("Invalid string: " + string);
                continue;
            }

            executor.submit(() -> {
                long start = System.nanoTime();
                String hash = getSHA256(string);
                hashes.put(hash, string);
                long end = System.nanoTime();

                System.out.println("Processing time for " + string + ": " + (end - start) + " ns");
            });
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS)) {
                System.out.println("Processing timeout!");
                executor.shutdownNow();
            } 
        } catch (InterruptedException ex) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        return hashes;
    }

    public Map<String, String> processFile(Path filePath) throws IOException {
        if (!filePath.toString().endsWith(".txt")) {
            System.out.println("Invalid file extension: " + filePath);
            return Collections.emptyMap();
        }

        List<String> strings = new ArrayList<>();
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.length() > MAX_SIZE) {
                    System.out.println("Invalid string in file: " + line);
                    continue;
                }

                strings.add(line);
            }
        }

        return processStrings(strings);
    }

    private String getSHA256(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes());

            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException ex) {
            throw new RuntimeException(ex);
        }
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();

        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);

            if(hex.length() == 1) {
                hexString.append('0');
            }

            hexString.append(hex);
        }

        return hexString.toString();
    }
}
```
This code creates a `HashProcessor` class that processes strings and files, validating their size and extension, computing SHA-256 hashes in parallel using an executor service, and logging the processing time for each string. It also includes methods to convert bytes to hexadecimal and compute SHA-256 hash of a string.
']

