        (*output)[len - i - 1] = temp;
    }
}

void manage_memory(long** offsets, int** keys, record*** records, size_t size) {
    srand((unsigned int) time(NULL)); // Seed the random number generator

    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) {
