    *keys = malloc(size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    *records = malloc(size * sizeof(record*));
    if (*records == NULL) {
