['Here is an example of how you might implement this task using C with POSIX threads (pthreads) for threading, and a simple logging library for logging operations. Please note that this is just a basic implementation and does not include all the features mentioned in your request. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct Packet {
    char* sourceIP;
    char* destIP;
    int protocolType;
    size_t payloadSize;
} Packet;

typedef struct Pool {
    pthread_mutex_t lock;
    Packet** packets;
    size_t size;
    size_t capacity;
} Pool;

Pool* createPool(size_t initialCapacity) {
    Pool* pool = malloc(sizeof(Pool));
    if (pool == NULL) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->packets = calloc(initialCapacity, sizeof(Packet*));
    if (pool->packets == NULL) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initialCapacity;
    log_info("Pool initialized with capacity: %zu", initialCapacity);
    return pool;
}

void resizePool(Pool* pool, size_t newCapacity) {
    pthread_mutex_lock(&pool->lock);

    Packet** newPackets = realloc(pool->packets, newCapacity * sizeof(Packet*));
    if (newPackets != NULL) {
        pool->packets = newPackets;
        pool->capacity = newCapacity;
    } else {
        log_error("Failed to resize the pool");
    }

    pthread_mutex_unlock(&pool->lock);
}

void addToPool(Pool* pool, Packet* packet) {
    if (pool->size == pool->capacity) {
        resizePool(pool, pool->capacity * 2);
    }

    pthread_mutex_lock(&pool->lock);
    pool->packets[pool->size++] = packet;
