['Here is an example of how you might implement this task using C with POSIX threads (pthreads) and a simple logging library. This code does not include all the features mentioned, but it provides a starting point for your requirements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "logging.h" // Assuming you have a logging library

typedef struct {
    int value;
    char* string;
} Record;

typedef struct {
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t size;
} Dataset;

Dataset dataset = {PTHREAD_MUTEX_INITIALIZER, NULL, NULL, NULL, 0, 0};

void* resize(void* ptr, size_t oldSize, size_t newSize) {
    if (newSize == 0) {
        free(ptr);
        return NULL;
    } else if (ptr == NULL) {
        return malloc(newSize);
    } else {
        return realloc(ptr, newSize);
    }
}

void addRecord(int key, int value, const char* string) {
    pthread_mutex_lock(&dataset.lock);

    if (dataset.size == dataset.capacity) {
        size_t newCapacity = dataset.capacity == 0 ? 1 : dataset.capacity * 2;

        dataset.offsets = resize(dataset.offsets, sizeof(long) * dataset.capacity, sizeof(long) * newCapacity);
        dataset.keys = resize(dataset.keys, sizeof(int) * dataset.capacity, sizeof(int) * newCapacity);
        dataset.records = resize(dataset.records, sizeof(Record*) * dataset.capacity, sizeof(Record*) * newCapacity);

        dataset.capacity = newCapacity;
    }

    dataset.keys[dataset.size] = key;
    dataset.offsets[dataset.size] = value;

    Record* record = malloc(sizeof(Record));
    record->value = value;
    record->string = strdup(string);
    dataset.records[dataset.size] = record;

    dataset.size++;

    pthread_mutex_unlock(&dataset.lock);
}

void* threadFunction(void* arg) {
    int value = *((int*)arg);
    char string[20];
    sprintf(string, "PREFIX%d", rand());

    addRecord(rand(), value, string);

    return NULL;
}

int main() {
    srand(time(NULL));

    int values[] = {10, 20, 30, 40}; // Example data
    size_t numValues = sizeof(values) / sizeof(int);

    pthread_t threads[numValues];

    for (size_t i = 0; i < numValues; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunction, &values[i]) != 0) {
            logError("Failed to create thread");
            return 1;
        }
    }

    for (size_t i = 0; i < numValues; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            logError("Failed to join thread");
            return 1;
        }
    }

    // Find the largest integer in the dataset
    int max = INT_MIN;
    for (size_t i = 0; i < dataset.size; ++i) {
        if (dataset.records[i]->value > max) {
            max = dataset.records[i]->value;
        }
    }

    printf("Largest integer: %d\n", max);

    // Cleanup
    for (size_t i = 0; i < dataset.size; ++i) {
        free(dataset.records[i]->string);
        free(dataset.records[i]);
    }
    free(dataset.offsets);
    free(dataset.keys);
    free(dataset.records);

    return 0;
}
```
This code creates a `Dataset` structure to hold the data, and uses a mutex for thread safety. The `addRecord` function is used by each thread to add records to the dataset, resizing it if necessary. The main function then waits for all threads to finish, finds the largest integer in the dataset, and cleans up the memory.
']

["Here is a basic implementation of your requirements using C language. Please note that this code does not include all the details you mentioned in your task such as error handling, integration issues, performance constraints and system dependencies. Also, it's important to mention that dynamic memory allocation can be complex and requires careful management to avoid leaks or segmentation faults.

```c
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define BASE_OFFSET 100

typedef struct {
    long* offsetArray;
    int* keyArray;
    Record* recordArray;
    int nOffsets;
    int nRecords;
    bool isInitialized;
} MetaData;

typedef struct {
    int key;
    int value;
} Record;

MetaData* manageDynamicMemory(int nOffsets, int nRecords, int minValue, int maxValue) {
    srand(time(NULL)); // seed the random number generator

    MetaData* meta = malloc(sizeof(MetaData));
    if (meta == NULL) return NULL;

    meta->offsetArray = aligned_alloc(alignof(long), nOffsets * sizeof(long));
    meta->keyArray = calloc(nOffsets, sizeof(int));
    meta->recordArray = malloc(nRecords * sizeof(Record));

    if (meta->offsetArray == NULL || meta->keyArray == NULL || meta->recordArray == NULL) {
        free(meta->offsetArray);
        free(meta->keyArray);
        free(meta->recordArray);
        free(meta);
        return NULL;
    }

    for (int i = 0; i < nOffsets; ++i) {
        meta->offsetArray[i] = BASE_OFFSET + i;
        meta->keyArray[i] = floor(sqrt((double)meta->offsetArray[i]));
    }

    for (int i = 0; i < nRecords; ++i) {
        meta->recordArray[i].key = meta->keyArray[rand() % nOffsets];
        meta->recordArray[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    meta->nOffsets = nOffsets;
    meta->nRecords = nRecords;
    meta->isInitialized = true;

    return meta;
}
```
This code assumes that the `aligned_alloc` function is available, which is not standard C but is supported by some compilers. It also uses the `floor` and `sqrt` functions from the math library to round down the square root of an offset and calculate it respectively. The random number generator is seeded with the current time for reproducibility across runs.
"]

