typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int manageArray(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    FILE *logFile = fopen("error.log", "a"); // Open log file in append mode

    if (size <= 0) {  // Handle edge case where size is zero or negative
        if (*array != NULL) {
            free(*array);  // Free allocated memory when size is zero
            *array = NULL;
        }
        return 1;  // Return success code
    }

    srand(time(NULL));  // Seed random number generator

    if (*array == NULL) {  // Allocate new array if it doesn't exist yet
        *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);

        if (*array == NULL) {  // Handle allocation failure
            fprintf(logFile, "Allocation failed\n");
            return -1;  // Return error code
        }
    } else {  // Reallocate existing array with new size
        *array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);

        if (*array == NULL && size > 0) {  // Handle reallocation failure
            fprintf(logFile, "Reallocation failed\n");
            return -1;  // Return error code
        }
    }

    for (int i = 0; i < size; ++i) {  // Initialize array elements
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100;  // Random value within acceptable range
        (*array)[i].RNTI = rand() % 100;  // Random value within acceptable range
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2;  // Random CRCFLAG value
    }

    fclose(logFile);  // Close log file

    return 1;  // Return success code
}
```
