void addToArray(int key, char* value) {
    if (array == NULL) array = malloc(1000 * sizeof(Node*));
    Node *newNode = malloc(sizeof(Node));
    newNode->key = key;
    strcpy(newNode->value, value);
    array[key - 1] = newNode;
}

void addToHeapArray(int key, char* value) {
    if (heap_size == heap_capacity) {
        heap_capacity *= 2;
        heap_array = realloc(heap_array, heap_capacity * sizeof(Node));
    }
    Node newNode;
    newNode.key = key;
    strcpy(newNode.value, value);
    heap_array[heap_size++] = newNode;
}

void addToList(int key, char* value) {
    pthread_mutex_lock(&lock);
    Node *newNode = malloc(sizeof(Node));
    newNode->key = key;
    strcpy(newNode->value, value);
    NodeList *newNodeList = malloc(sizeof(NodeList));
    newNodeList->node = newNode;
    newNodeList->next = head;
    head = newNodeList;
    pthread_mutex_unlock(&lock);
}

void init() {
    for (int i = 1; i <= 1000; ++i) {
        char value[20];
        sprintf(value, "%d", i);
        addToArray(i, value);
        addToHeapArray(i, value);
        addToList(i, value);
    }
}
