#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct Packet {
    int id;
    int size;
    time_t arrivalTime;
} Packet;

// Union-Find data structure
int parent[100];
int rank[100];

void makeSet(int i) {
    parent[i] = i;
    rank[i] = 0;
}

int find(int i) {
    if (parent[i] != i)
        parent[i] = find(parent[i]);
    return parent[i];
}

void unionSet(int i, int j) {
    int iRoot = find(i);
    int jRoot = find(j);

    if (rank[iRoot] < rank[jRoot]) 
        parent[iRoot] = jRoot;
    else if (rank[iRoot] > rank[jRoot]) 
        parent[jRoot] = iRoot;
    else {
        parent[jRoot] = iRoot;
        rank[iRoot]++;
    }
}

// Function to process packets
void processPacket(Packet packet) {
    clock_t startTime = clock();

    // Filter based on size, frequency of arrivals and priority score
    if (packet.size > 1024 || find(packet.id) != packet.id) {
        printf("Packet %d rejected\n", packet.id);
        return;
    }

    // Update Union-Find structure
    unionSet(packet.id, (packet.id + 1) % 100);

    clock_t endTime = clock();
    double timeTaken = ((double)(endTime - startTime)) / CLOCKS_PER_SEC; // in seconds
    printf("Packet %d processed in %f milliseconds\n", packet.id, timeTaken * 1000);
}

// Function to modify file extension
void modifyExtension(char* filename) {
    char newFilename[256];

    sprintf(newFilename, "%s_modified.txt", filename);

    printf("New filename: %s\n", newFilename);
}
```
