```javascript
const { Transform, pipeline } = require('stream');
const logger = require('./logger'); // Assuming there's a logging framework available
const remoteStorageService = require('./remoteStorageService'); // Assuming there's a service for exporting data to a remote storage

class DataProcessingStream extends Transform {
  constructor(options) {
    super({ ...options, objectMode: true });
    this.isPaused = false;
  }

  _transform(chunk, encoding, callback) {
    if (this.isPaused) {
      logger.info('Processing is paused');
      return;
    }

    try {
      // Process the data here
      const processedData = chunk;

      remoteStorageService.export(processedData, (err) => {
        if (err) {
          logger.error('Error exporting data', err);
          callback(err);
        } else {
          callback(null, processedData);
        }
      });
    } catch (e) {
      logger.error('Corruption detected in the data', e);
      // Handle corruption here
      callback();
    }
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
  }
}

const dataProcessingStream = new DataProcessingStream();
pipeline(
  highThroughputDataSource, // Assuming there's a high-throughput streaming data source
  dataProcessingStream,
  (err) => {
    if (err) {
      logger.error('Pipeline failed', err);
    } else {
      logger.info('Pipeline succeeded');
    }
  },
);
```
