            logError("Memory allocation failed");
            free(newNode);  // clean up the allocated memory
            continue;  // skip this record and move to the next one
        }

        head = newNode;
        totalRecords++;
        totalSize += size;
        totalDuration += duration;

        pthread_mutex_unlock(&lock);
    }
