["Here's an example of how you might implement this in C# using ADO.NET and Entity Framework. This code does not include all the features you requested (like dynamic indexing based on system load or logging), but it should give you a good starting point for building your own solution. 

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public class MyDbContext : DbContext
{
    public MyDbContext(DbContextOptions<MyDbContext> options) : base(options) { }
}

public class SqlQueryExecutor
{
    private readonly string _connectionString;
    private readonly bool _logDetails;
    private readonly DependencyConfig _dependencyConfig;

    public SqlQueryExecutor(string connectionString, bool logDetails, DependencyConfig dependencyConfig)
    {
        _connectionString = connectionString;
        _logDetails = logDetails;
        _dependencyConfig = dependencyConfig;
    }

    public async Task<List<Dictionary<string, object>>> ExecuteQueryAsync(string commandTemplate, List<SqlParameter> parameters)
    {
        var stopwatch = new Stopwatch();
        var results = new List<Dictionary<string, object>>();

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            using (var command = new SqlCommand(commandTemplate, connection))
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                stopwatch.Start();

                using (var reader = await command.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                    {
                        var row = new Dictionary<string, object>();

                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            row[reader.GetName(i)] = await reader.IsDBNullAsync(i) ? null : reader.GetValue(i);
                        }

                        results.Add(row);
                    }
                }
            }
        }

        stopwatch.Stop();

        if (_logDetails)
        {
            // Log query execution details here, using _dependencyConfig to access logging service
        }

        return results;
    }
}
```

This code uses Entity Framework Core for database operations and async/await for non-blocking I/O. It logs query execution details if the `_logDetails` flag is set, but it doesn't include any logging service or caching mechanism in the provided code. You would need to implement these features yourself based on your specific requirements.
