static pthread_key_t thread_local_storage;
static pthread_once_t once_control = PTHREAD_ONCE_INIT;

void initializeAndManageDynamicArray() {
    // Initialize the thread-local storage key only once
    pthread_once(&once_control, [](){
        pthread_key_create(&thread_local_storage, [](void* arg){
            free(arg);  // Free memory when a thread exits
        });
    });

    NR_DL_FRAME_TRANSPORT_CONTEXT** context = (NR_DL_FRAME_TRANSPORT_CONTEXT**)pthread_getspecific(thread_local_storage);
    if (!context) {
