    newNode->next = NULL;

    return newNode;
}

void validate_list(Node* head){
    int count = 0;
    while (head != NULL) {
        if(count++ > 10000) exit(-2); // possible infinite loop

        if(head->next == head) printf("Dangling reference detected!\n");
        head = head->next;
    }
}

void traverse_and_print(Node* head){
    while (head != NULL) {
        printf("Data: %f, String: %s\n", head->data, head->str);
        head = head->next;
    }
}

int main() {
    srand(time(0)); // seed the random number generator

    Node *head = create_node((double) rand(), "example");
    Node *current = head;

    for (int i = 1; i < 10; ++i){
