    pthread_mutex_lock(&lock);
    initializeUserSpecificDataEntry(collection[userId - 1], userId); // User IDs start from 1.
    pthread_mutex_unlock(&lock);
    return NULL;
}

void manageCollection() {
    pthread_t threads[collectionSize];
    int threadArgs[collectionSize];
    for (int i = 0; i < collectionSize; ++i) {
        threadArgs[i] = i + 1; // User IDs start from 1.
