} FrameArray;

FrameArray* createFrameArray(size_t initialCapacity) {
    FrameArray* array = malloc(sizeof(FrameArray));
    if (array == NULL) return NULL;

    array->frames = calloc(initialCapacity, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT*));
    if (array->frames == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void addFrame(FrameArray* array, NR_DL_FRAME_TRANSPORT_CONTEXT* frame) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        // Resize the array and copy existing frames
        size_t newCapacity = array->capacity * 2;
        NR_DL_FRAME_TRANSPORT_CONTEXT** newFrames = realloc(array->frames, newCapacity * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT*));

        if (newFrames != NULL) {
            array->capacity = newCapacity;
            array->frames = newFrames;
        } else {
            // Handle error: memory allocation failed
        }
    }

    array->frames[array->count++] = frame;

    pthread_mutex_unlock(&array->lock);
}
