['Here is a basic implementation in C using pthreads for threading and mutexes for locking. This code does not include error handling or detailed logging mechanisms as these would significantly increase the complexity of this example. 

```c
#include <pthread.h>
#include <stdlib.h>

typedef struct MAC_HEADER {
    char destination[6];
    char source[6];
    int frame_control;
} MAC_HEADER;

typedef enum ConnectionState {
    IDLE,
    CONNECTING,
    ESTABLISHED
} ConnectionState;

typedef struct Node {
    MAC_HEADER *header;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ConnectionState state = IDLE;

void addHeader(MAC_HEADER *header) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->header = header;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void changeState(ConnectionState newState) {
    pthread_mutex_lock(&lock);

    state = newState;

    pthread_mutex_unlock(&lock);
}

MAC_HEADER *getHeaders() {
    MAC_HEADER *headers = NULL;
    int count = 0;

    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        headers = realloc(headers, sizeof(MAC_HEADER) * (count + 1));
        headers[count] = *(current->header);
        ++count;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return headers;
}
```
This code provides a basic implementation of the requirements. It uses a linked list to store MAC_HEADER structures, and a mutex for locking to ensure thread safety. The state machine is implemented as an enum and a simple function to change states. 

