['Here is an example of how you might implement such a system in C. This code does not include all the features mentioned (like network latency handling or data corruption detection), but it provides a basic structure for managing `struct item` pointers with thread safety. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct item {
    char* name;
    int value;
} Item;

typedef struct array_list {
    pthread_mutex_t lock;
    Item** items;
    size_t capacity;
    size_t size;
} ArrayList;

ArrayList* create_array_list() {
    ArrayList* list = malloc(sizeof(ArrayList));
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        return NULL;
    }
    list->capacity = 10;
    list->size = 0;
    list->items = malloc(sizeof(Item*) * list->capacity);
    return list;
}

void resize_array_list(ArrayList* list) {
    Item** newItems = malloc(sizeof(Item*) * list->capacity * 2);
    memcpy(newItems, list->items, sizeof(Item*) * list->capacity);
    free(list->items);
    list->items = newItems;
    list->capacity *= 2;
}

void add_item(ArrayList* list, Item* item) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        resize_array_list(list);
    }
    list->items[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
}

void remove_item(ArrayList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        printf("Index out of bounds\n");
        return;
    }
    free(list->items[index]->name);
    free(list->items[index]);
    for (size_t i = index; i < list->size - 1; ++i) {
        list->items[i] = list->items[i + 1];
    }
    --list->size;
    pthread_mutex_unlock(&list->lock);
}
```
This code uses a dynamic array to store the `struct item` pointers. When the array is full, it doubles its size. The operations on the array are protected by a mutex to ensure thread safety. 

The choice of using a linked list instead of a dynamic array for resizing would depend on factors like insertion and deletion times, memory overhead, and ease of implementation. A linked list would have faster insertions and deletions at any position but could be slower for random access. A dynamic array has faster random access but slower insertions and deletions. In this case, a dynamic array was chosen because it's simpler to implement and the performance trade-off is acceptable given that we are dealing with a large number of `struct item` pointers.
']

