```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double* numbers;
    char status;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Array;

Array array = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void resize(Array* array) {
    if (array->capacity == 0) {
        array->records = malloc(sizeof(Record));
        array->capacity = 1;
    } else {
        array->records = realloc(array->records, sizeof(Record) * array->capacity * 2);
        array->capacity *= 2;
    }
}

void add_record(Array* array, double value, char status) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        resize(array);
    }

    Record record;
    record.numbers = malloc(sizeof(double));
    *record.numbers = value;
    record.status = status;

    array->records[array->size++] = record;

    pthread_mutex_unlock(&array->lock);
}

void print_records(Array* array) {
    for (size_t i = 0; i < array->size; ++i) {
        printf("Record %zu: ", i);
        for (size_t j = 0; j < 1 /* replace with actual size */; ++j) {
            printf("%f ", array->records[i].numbers[j]);
        }
        printf(", status = %c\n", array->records[i].status);
    }
}
```
This code uses a mutex to ensure that only one thread can modify the array at a time, preventing race conditions. It also dynamically allocates memory for each record as it is added, which allows for varying numbers of floating-point values per record. 

Please note that this is a simplified example and does not include error checking or other important features you would need in a production environment. Also, the code assumes that there's only one double value per record, but if there are multiple values, you should adjust the `resize` function accordingly.
