pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;

void* performRequest(void* data) {
    RequestData *requestData = (RequestData*)data;

    // Check if URL is in cache
    pthread_mutex_lock(&cacheLock);
    gpointer result = g_hash_table_lookup(cache, requestData->url);
    pthread_mutex_unlock(&cacheLock);

    if (result != NULL) {
        // Return cached data
        return result;
    } else {
        // Perform HTTP request and store in cache
        CURLcode res = curl_easy_perform(requestData->handle);

        // Handle errors, retry logic, etc.

        pthread_mutex_lock(&cacheLock);
        g_hash_table_insert(cache, requestData->url, result);  // Store in cache
        pthread_mutex_unlock(&cacheLock);
    }

    return NULL;
}

int main() {
