function manipulateStrings(forwardList, filename, str1, str2, fieldNames, config) {
    let updatedFilename = '';
    let count = 0;
    for (let i = 0; i < filename.length; i++) {
        if (/[a-zA-Z]/.test(filename[i])) {
            count++;
        }
    }
    updatedFilename += `${count}`;
    let fileType = '';
    for (let i = 0; i < filename.length; i++) {
        if (/[a-z]/.test(filename[i])) {
            fileType += 'l';
        } else if (/[A-Z]/.test(filename[i])) {
            fileType += 'u';
        }
    }
    updatedFilename += `.${fileType}`;

    let str1Index = forwardList.indexOf(str1);
    if (str1Index !== -1) {
        forwardList.splice(str1Index + 1, 0, str2);
    }

    for (let fieldName of fieldNames) {
        let index = forwardList.indexOf(fieldName);
        if (index !== -1 && window.opener) {
            try {
                let result = window.opener.postMessage({ field: fieldName }, '*', [transfer]);
                setTimeout(() => {
                    if (result === 'success') {
                        forwardList[index] = result;
                    }
                }, config.frequency);
            } catch(error) {
                console.log('Error occurred while sending message to parent window:', error);
                if (config.handleErrors) {
                    throw error;
                }
            }
        }
    }

    return { forwardList, updatedFilename };
}
