u_char* resolveIP(const char* hostname) {
    // Check if IP is in cache
    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(hostname, cache[i].hostname) == 0 && time(NULL) - cache[i].timestamp <= IDLE_TIMEOUT) {
            pthread_mutex_unlock(&cacheMutex);
            return cache[i].ip;
        }
    }
    pthread_mutex_unlock(&cacheMutex);

    // Resolve IP using DNS
    struct hostent* host = gethostbyname(hostname);
    if (host == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    u_char* ip = malloc(sizeof(u_char) * 4);
    memcpy(ip, host->h_addr_list[0], sizeof(u_char) * 4);

    // Add to cache
    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].hostname == NULL || time(NULL) - cache[i].timestamp > IDLE_TIMEOUT) {
            free(cache[i].hostname);
            cache[i].hostname = strdup(hostname);
            memcpy(cache[i].ip, ip, sizeof(u_char) * 4);
            cache[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&cacheMutex);

    return ip;
}

