["This task is quite complex and involves multiple aspects such as concurrency control, serialization/deserialization, dynamic resizing of an array, handling bursts of data etc. Here's a simplified version of how you might implement some parts of it in C. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct item {
    char* name;
    int value;
    double weight;
} Item;

typedef struct array {
    pthread_mutex_t lock;
    Item** items;
    size_t capacity;
    size_t count;
} Array;

Array* create_array() {
    Array* arr = malloc(sizeof(Array));
    arr->capacity = 1000;
    arr->count = 0;
    arr->items = malloc(arr->capacity * sizeof(Item*));
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void resize_array(Array* arr) {
    size_t newCapacity = arr->count < 800 ? 2 * arr->capacity : arr->capacity + 1000;
    Item** newItems = malloc(newCapacity * sizeof(Item*));
    memcpy(newItems, arr->items, arr->count * sizeof(Item*));
    free(arr->items);
    arr->capacity = newCapacity;
    arr->items = newItems;
}

void add_item(Array* arr, Item* item) {
    pthread_mutex_lock(&arr->lock);
    if (arr->count == arr->capacity) {
        resize_array(arr);
    }
    arr->items[arr->count++] = item;
    pthread_mutex_unlock(&arr->lock);
}

void remove_item(Array* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    if (index < arr->count) {
        free(arr->items[index]);
        for (size_t i = index; i < arr->count - 1; ++i) {
            arr->items[i] = arr->items[i + 1];
        }
        --arr->count;
    }
    pthread_mutex_unlock(&arr->lock);
}
```
This is a very simplified version of the problem. It doesn't include serialization/deserialization, handling bursts of data or checkpointing mechanism for partial writes. Also, it assumes that all threads will only read from the array and not write to it concurrently. 

