['Here is an example of how you might implement this in C. This code does not include all the features you requested due to complexity and size constraints, but it should give you a good starting point for your task. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    size_t offsetSize;
    int* keys;
    size_t keySize;
    Record** records;
    size_t recordSize;
    pthread_mutex_t lock;
} DataStructures;

DataStructures* init(size_t offsetSize, size_t keySize, size_t recordSize) {
    srand(time(NULL));

    DataStructures* ds = malloc(sizeof(DataStructures));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(offsetSize, sizeof(long));
    ds->keys = calloc(keySize, sizeof(int));
    ds->records = malloc(recordSize * sizeof(Record*));
    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        freeDataStructures(ds);
        return NULL;
    }

    for (size_t i = 0; i < recordSize; ++i) {
        ds->records[i] = calloc(1, sizeof(Record));
        if (ds->records[i] == NULL) {
            freeDataStructures(ds);
            return NULL;
        }
    }

    ds->offsetSize = offsetSize;
    ds->keySize = keySize;
    ds->recordSize = recordSize;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void freeDataStructures(DataStructures* ds) {
    if (ds == NULL) return;

    for (size_t i = 0; i < ds->recordSize; ++i) {
        free(ds->records[i]);
    }
    free(ds->records);
    free(ds->offsets);
    free(ds->keys);

    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void setRandomValues(DataStructures* ds, int min, int max) {
    assert(min < max);

    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->recordSize; ++i) {
        ds->records[i]->value = min + rand() % ((max + 1) - min);
    }
    pthread_mutex_unlock(&ds->lock);
}

void reset(DataStructures* ds) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->recordSize; ++i) {
        free(ds->records[i]);
        ds->records[i] = calloc(1, sizeof(Record));
    }
    pthread_mutex_unlock(&ds->lock);
}
```
