// Function to initialize a user session
void init_session(uint64_t id, const char* name) {
    pthread_mutex_lock(&lock);

    if (session_count >= MAX_SESSIONS) {
        printf("Maximum number of sessions reached.\n");
        return;
    }

    user_session* session = malloc(sizeof(user_session));
    session->unique_session_id = id;
    session->username = strdup(name);

    // Initialize metadata fields here if needed

    sessions[session_count++] = session;

    pthread_mutex_unlock(&lock);
}

// Function to reset a user session
void reset_session(uint64_t id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < session_count; ++i) {
        if (sessions[i]->unique_session_id == id) {
            free(sessions[i]->username);
            free(sessions[i]);

            // Swap the last session with this one and decrement the count
            sessions[i] = sessions[--session_count];
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code provides a basic structure for managing user sessions. It uses a global array to store session pointers, and a mutex lock to ensure thread safety when modifying the array. The `init_session` function allocates memory for a new session and adds it to the array, while the `reset_session` function frees the memory associated with a session and removes it from the array.

