// Union-Find data structure for managing disjoint sets of USER_DATA_RECORD instances
typedef struct {
    int *parent, *rank;
    int n;
} UnionFind;

UnionFind uf;
USER_DATA_RECORD** cache;
int cacheSize;
pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;
time_t TTL = 60 * 60; // Time-to-Live in seconds (1 hour)

// Initialize UnionFind data structure
void initUnionFind(int n) {
    uf.n = n;
    uf.parent = malloc(n * sizeof(int));
    uf.rank = malloc(n * sizeof(int));

    for (int i = 0; i < n; ++i) {
        uf.parent[i] = i;
        uf.rank[i] = 0;
    }
}

// Find operation in UnionFind data structure
int find(int x) {
    if (uf.parent[x] != x)
        uf.parent[x] = find(uf.parent[x]);

    return uf.parent[x];
}

// Union operation in UnionFind data structure
void unionSet(int x, int y) {
    x = find(x), y = find(y);
    if (uf.rank[x] < uf.rank[y]) 
        uf.parent[x] = y;
    else 
        uf.parent[y] = x;

    if (uf.rank[x] == uf.rank[y]) 
        ++uf.rank[x];
}

// Add a new record to the cache
void addRecord(USER_DATA_RECORD* record) {
    pthread_mutex_lock(&cacheLock);

    if (record->uniqueId >= cacheSize) {
        // Resize the cache
        cache = realloc(cache, 2 * cacheSize * sizeof(USER_DATA_RECORD*));

        for (int i = cacheSize; i < 2 * cacheSize; ++i) {
            cache[i] = NULL;
        }

        cacheSize *= 2;
    }

    if (cache[record->uniqueId] == NULL) {
        // Add a new record to the UnionFind data structure
        initUnionFind(cacheSize);
        unionSet(find(record->uniqueId), find((record->uniqueId + 1) % cacheSize));
    } else {
        // Update an existing record in the UnionFind data structure
        unionSet(find(cache[record->uniqueId]->uniqueId), find(record->uniqueId));
    }

    pthread_mutex_unlock(&cacheLock);
}
```
