void enqueue(PacketQueue* queue, Packet packet) {
    if (queue->count >= MAX_PACKETS) {
        printf("Error: Queue is full\n");
        return;
    }

    queue->packets[queue->tail] = packet;
    queue->tail = (queue->tail + 1) % MAX_PACKETS;
    queue->count++;
}

Packet dequeue(PacketQueue* queue) {
    if (queue->count <= 0) {
        printf("Error: Queue is empty\n");
        return (Packet){.id = -1, .size = 0, .arrivalTime = 0};
    }

    Packet packet = queue->packets[queue->head];
    queue->head = (queue->head + 1) % MAX_PACKETS;
    queue->count--;
    return packet;
}

