    int state;
    struct Node* next;
} Node;

Node** simulateTransitions(int* states, int numStates, int* startStates, int numStarts, int** fsa, int maxTransitions) {
    Node** result = malloc(numStarts * sizeof(Node*));

    for (int i = 0; i < numStarts; ++i) {
        int currentState = startStates[i];
        Node* head = NULL, *tail = NULL;

        for (int j = 0; j < maxTransitions; ++j) {
            if (!head) {
                head = tail = malloc(sizeof(Node));
                head->state = currentState;
                head->next = NULL;
            } else {
                tail->next = malloc(sizeof(Node));
                tail = tail->next;
                tail->state = currentState;
                tail->next = NULL;
            }

            if (fsa[currentState] == NULL) break; // handle null pointers in FSA transition table
            currentState = fsa[currentState][j % numStates]; // loop back to the start of the states array when reaching the end
        }

        result[i] = head;
    }

    return result;
}
