#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    char* buffer;
} Record;

Record** allocate_records(int num_records, int min_key, int max_key, size_t buf_size, FILE* log) {
    if (num_records <= 0 || min_key >= max_key || buf_size < 1) {
        fprintf(log, "Invalid parameters\n");
        return NULL;
    }

    Record** records = malloc(num_records * sizeof(Record*));
    if (records == NULL) {
        fprintf(log, "Failed to allocate memory for records\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(log, "Failed to allocate memory for record %d\n", i);
            // Free previously allocated records
            while (--i >= 0) free(records[i]);
            free(records);
            return NULL;
        }

        record->key = min_key + rand() % (max_key - min_key + 1);
        record->buffer = malloc(buf_size * sizeof(char));
        if (record->buffer == NULL) {
            fprintf(log, "Failed to allocate memory for buffer of record %d\n", i);
            free(record);
            // Free previously allocated records
            while (--i >= 0) free(records[i]);
            free(records);
            return NULL;
        }

        memset(record->buffer, 0, buf_size * sizeof(char));
        records[i] = record;
    }

    fprintf(log, "Successfully allocated %d records\n", num_records);
    return records;
}

void deallocate_records(Record** records, int num_records, FILE* log) {
    if (records == NULL || num_records <= 0) {
        fprintf(log, "Invalid parameters\n");
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i]->buffer);
        free(records[i]);
    }

    free(records);
    fprintf(log, "Successfully deallocated %d records\n", num_records);
}
```
