    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        // Handle memory allocation error
        return;
    }

    node->offset = offset;
    node->key = key;
    node->record.value = rand() % 1000 + 1; // Random value between 1 and 1000
    node->next = NULL;

    if (callback != NULL) {
        callback(node, context);
    }
}

void deleteRecord(long offset, int key, Callback callback, void* context) {
    // Find the record and mark it as deleted
    Node* node = findNodeByOffsetAndKey(offset, key);

    if (node == NULL) {
        // Handle record not found error
        return;
    }

    node->record.value = -1; // Mark the record as deleted

    if (callback != NULL) {
        callback(node, context);
    }
}

Node* findNodeByOffsetAndKey(long offset, int key) {
    Node* current = head;

    while (current != NULL) {
        if (current->offset == offset && current->key == key) {
            return current;
        }

        current = current->next;
    }

    return NULL; // Record not found
}
```
