// Define a dynamic collection of records
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    Record** records;
} RecordsCollection;

// Initialize the collection
void init_collection(RecordsCollection* collection, size_t initial_capacity) {
    // Initialize mutex for thread-safe operations
    pthread_mutex_init(&collection->lock, NULL);

    collection->records = malloc(initial_capacity * sizeof(Record*));
    if (collection->records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
}

// Add a record to the collection
void add_record(RecordsCollection* collection, Record* record) {
    pthread_mutex_lock(&collection->lock);

    // Check if we need to resize the array
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = realloc(collection->records, new_capacity * sizeof(Record*));

        if (new_records == NULL) {
            perror("Failed to resize records array");
            pthread_mutex_unlock(&collection->lock);
            return;
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    // Add the record to the array
    collection->records[collection->size] = record;
    collection->size++;

    pthread_mutex_unlock(&collection->lock);
}
