```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>

typedef struct {
    char source_ip[INET6_ADDRSTRLEN];
    char dest_ip[INET6_ADDRSTRLEN];
    uint16_t protocol;
    size_t payload_size;
    struct timespec timestamp;
} packet_t;

typedef struct {
    pthread_mutex_t lock;
    packet_t *packets;
    size_t capacity;
    size_t count;
} pool_t;

pool_t* create_pool(size_t initial_capacity) {
    pool_t *pool = malloc(sizeof(pool_t));
    if (pthread_mutex_init(&pool->lock, NULL) != 0) {
        free(pool);
        return NULL;
    }
    pool->packets = calloc(initial_capacity, sizeof(packet_t));
    if (!pool->packets) {
        pthread_mutex_destroy(&pool->lock);
        free(pool);
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    return pool;
}

void destroy_pool(pool_t *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->packets);
    free(pool);
}

int add_packet(pool_t *pool, packet_t *packet) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        packet_t *new_packets = realloc(pool->packets, new_capacity * sizeof(packet_t));
        if (!new_packets) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->packets = new_packets;
        pool->capacity = new_capacity;
    }
    memcpy(&pool->packets[pool->count], packet, sizeof(packet_t));
    pool->count++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}
```
