        newNode->record.duration = duration;
        newNode->record.size = size;
        newNode->record.genre = strdup(genre);
        newNode->record.URL = strdup(URL);

        if (head == NULL) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}
