['Here is a high-level overview of how you might implement such a configuration manager in C. This code does not include all the details mentioned in your requirements as it would be quite complex to fully implement them here. However, this should give you an idea of how you could start implementing each requirement. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <fcntl.h>
#include <stdio.h>
#include <time.h>
#include "external_logging_library.h" // Assuming this exists and provides logging functions

// Define a struct to hold configuration data
typedef struct {
    char* key;
    void* value;
    time_t lastUpdated;
} ConfigEntry;

// Define a struct for the configuration manager
typedef struct {
    ConfigEntry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    sem_t* semaphore;
    int shm_fd;
} ConfigurationManager;

// Function to initialize the configuration manager
ConfigurationManager* initConfigManager(size_t initialCapacity) {
    ConfigurationManager* cm = malloc(sizeof(ConfigurationManager));
    if (cm == NULL) return NULL;

    // Initialize mutex and semaphore
    pthread_mutex_init(&cm->mutex, NULL);
    cm->semaphore = sem_open("/mySem", O_CREAT, 0644, 1);
    if (cm->semaphore == SEM_FAILED) return NULL;

    // Initialize shared memory for entries
    cm->shm_fd = shm_open("/myShm", O_CREAT | O_RDWR, 0666);
    if (cm->shm_fd < 0) return NULL;
    ftruncate(cm->shm_fd, initialCapacity * sizeof(ConfigEntry*));
    cm->entries = mmap(NULL, initialCapacity * sizeof(ConfigEntry*), PROT_READ | PROT_WRITE, MAP_SHARED, cm->shm_fd, 0);

    // Initialize other fields
    cm->capacity = initialCapacity;
    cm->count = 0;

    return cm;
}

// Function to add a configuration entry
void addConfigEntry(ConfigurationManager* cm, char* key, void* value) {
    sem_wait(cm->semaphore); // Lock the semaphore
    pthread_mutex_lock(&cm->mutex); // Lock the mutex

    if (cm->count >= cm->capacity * 0.7) {
        // If we're over 70% capacity, double the size of our shared memory
        ConfigEntry** newEntries = mremap(cm->entries, cm->capacity * sizeof(ConfigEntry*), cm->capacity * 2 * sizeof(ConfigEntry*));
        if (newEntries == MAP_FAILED) {
            // Handle error
        } else {
            cm->entries = newEntries;
            cm->capacity *= 2;
        }
    }

    ConfigEntry* entry = malloc(sizeof(ConfigEntry));
    if (entry == NULL) return;

    // Initialize the entry
    entry->key = strdup(key);
    entry->value = value;
    time(&entry->lastUpdated);

    cm->entries[cm->count++] = entry;

