#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
    char* str;
} Record;

Record** records = NULL;
int record_count = 0;
int max_records = 10;
pthread_mutex_t lock;

void* allocate_record(int value, size_t length) {
    if (record_count >= max_records) {
        printf("Error: Maximum records limit reached.\n");
        return NULL;
    }

    Record* record = malloc(sizeof(Record));
    if (!record) {
        printf("Error: Failed to allocate memory for record.\n");
        return NULL;
    }

    char* str = malloc(length + 1);
    if (!str) {
        free(record);
        printf("Error: Failed to allocate memory for string.\n");
        return NULL;
    }

    // Generate random alphanumeric characters for the string.
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';

    record->value = value;
    record->str = str;

    pthread_mutex_lock(&lock);
    records[record_count++] = record;
    pthread_mutex_unlock(&lock);

    return record;
}

void free_records() {
    for (int i = 0; i < record_count; ++i) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);

    pthread_mutex_destroy(&lock);
}

void* thread_function(void* arg) {
    int value = *((int*)arg);
    Record* record = allocate_record(value, 10);

    if (record) {
        printf("Record created: %d, %s\n", record->value, record->str);
    } else {
        printf("Failed to create record with value: %d\n", value);
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    records = malloc(max_records * sizeof(Record*));
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        return 1;
    }

    pthread_mutex_init(&lock, NULL);

    // Create multiple threads.
    const int thread_count = 5;
    pthread_t threads[thread_count];
    int values[thread_count] = {10, 20, 30, 40, 50};

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &values[i]) != 0) {
            printf("Error: Failed to create thread.\n");
            return 1;
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            printf("Error: Failed to join thread.\n");
            return 1;
        }
    }

    free_records();

    return 0;
}
```
