        pthread_mutex_lock(&lock);
        list = realloc(list, (size + 1) * sizeof(Node));
        if (list == NULL) {
            log("Failed to allocate memory for node");
            free(str);
            continue;
        }

        Node *node = &list[size];
        node->value = value;
        node->str = str;
        size++;
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return 0;
}
