} Record;

typedef struct {
    size_t count;
    size_t capacity;
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t lock;
} Store;

Store* create_store(size_t initialCapacity) {
    Store* store = malloc(sizeof(Store));
    if (store == NULL) return NULL;

    store->count = 0;
    store->capacity = initialCapacity;
    store->offsets = malloc(initialCapacity * sizeof(long));
    store->keys = malloc(initialCapacity * sizeof(int));
    store->records = malloc(initialCapacity * sizeof(Record*));

    if (store->offsets == NULL || store->keys == NULL || store->records == NULL) {
        free_store(store);
        return NULL;
    }

    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void add_record(Store* store, int key, Record* record) {
    if (store == NULL || record == NULL) return;

    pthread_mutex_lock(&store->lock);

    // Check for duplicate keys and update existing records
    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) {
            free(store->records[i]);
            store->records[i] = record;
            pthread_mutex_unlock(&store->lock);
            return;
        }
    }

    // Resize arrays if necessary
    if (store->count == store->capacity) {
        store->capacity *= 2;
        store->offsets = realloc(store->offsets, store->capacity * sizeof(long));
        store->keys = realloc(store->keys, store->capacity * sizeof(int));
        store->records = realloc(store->records, store->capacity * sizeof(Record*));
    }

    // Add new record
    store->offsets[store->count] = (char*)record - (char*)store;
    store->keys[store->count] = key;
    store->records[store->count] = record;
    ++store->count;

    pthread_mutex_unlock(&store->lock);
}

Record* get_record(Store* store, int key) {
    if (store == NULL) return NULL;

    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) {
            Record* record = store->records[i];
            pthread_mutex_unlock(&store->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&store->lock);
    return NULL;
}

void free_store(Store* store) {
    if (store == NULL) return;

    for (size_t i = 0; i < store->count; ++i) {
        free(store->records[i]);
    }

    pthread_mutex_destroy(&store->lock);
    free(store->offsets);
    free(store->keys);
    free(store->records);
    free(store);
}
```
