void removeRecord(TRAFFIC_RECORD record) {
    pthread_mutex_lock(&lock);

    NODE* current = head;
    NODE* prev = NULL;

    while (current != NULL && compareRecords(current->record, record)) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return; // Record not found

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&lock);
}

void updateRecord(TRAFFIC_RECORD oldRecord, TRAFFIC_RECORD newRecord) {
    removeRecord(oldRecord);
    addRecord(newRecord);
