    int qosConfig;
} NR_DL_FRAME_TRANSPORT_CONTEXT;

typedef struct FrameNode {
    NR_DL_FRAME_TRANSPORT_CONTEXT context;
    struct FrameNode* next;
} FrameNode;

FrameNode* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addFrame(NR_DL_FRAME_TRANSPORT_CONTEXT context) {
    pthread_mutex_lock(&lock);

    FrameNode* newNode = malloc(sizeof(FrameNode));
    newNode->context = context;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void updateFrame(DL_FRAME_TRANSPORT_TAG tag, NR_RLC_PDU* pduList, int qosConfig) {
    pthread_mutex_lock(&lock);

    FrameNode* current = head;
    while (current != NULL) {
        if (current->context.tag == tag) {
            current->context.pduList = pduList;
            current->context.qosConfig = qosConfig;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void cleanupFrames() {
    pthread_mutex_lock(&lock);

    FrameNode* current = head;
    while (current != NULL) {
        FrameNode* temp = current;
        current = current->next;

        free(temp);
    }
    head = NULL;

    pthread_mutex_unlock(&lock);
}
```
This code uses a simple linked list to manage the frames. Each frame is stored in a `FrameNode`, which contains a `NR_DL_FRAME_TRANSPORT_CONTEXT` and a pointer to the next node. The `addFrame` function adds a new frame at the head of the list, while the `updateFrame` function updates an existing frame based on its tag.

