Store* create_store(size_t initial_capacity) {
    Store* store = malloc(sizeof(Store));
    if (store == NULL) return NULL;

    store->records = calloc(initial_capacity, sizeof(Record));
    if (store->records == NULL) {
        free(store);
        return NULL;
    }

    store->capacity = initial_capacity;
    store->count = 0;
    pthread_mutex_init(&store->lock, NULL);

    return store;
}

void destroy_store(Store* store) {
    free(store->records);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

int add_record(Store* store, int key, Record record) {
    pthread_mutex_lock(&store->lock);

    if (store->count == store->capacity) {
        size_t new_capacity = store->capacity * 2;
        Record* new_records = realloc(store->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&store->lock);
            return -1; // Allocation failed
        }

        store->records = new_records;
        store->capacity = new_capacity;
    }

    store->records[key] = record;
    store->count++;

    pthread_mutex_unlock(&store->lock);
    return 0; // Success
}

// Similar functions for update and retrieve operations...
