pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FileData fileList[100];
int listIndex = 0;

void* readAndParse(void *arg) {
    char *filename = (char*) arg;

    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file %s\n", filename);
        return NULL;
    }

    // Parse the file and populate a NFAPI_CRC_INDICATION_PDU_T structure
    FileData data;
    fscanf(file, "%d %d %d", &data.pdu.RNTI, &data.rel8.CRCFLAG, &data.pdu.RX_UE_INFORMATION_TAG);

    pthread_mutex_lock(&lock);
    fileList[listIndex++] = data;
    pthread_mutex_unlock(&lock);

    fclose(file);
    return NULL;
}

void readFilesFromDir(char *dirname) {
    DIR *d;
    struct dirent *dir;
    d = opendir(dirname);
    if (d) {
        pthread_t threads[100];
        int threadCount = 0;

        while ((dir = readdir(d)) != NULL && threadCount < 100) {
            char filename[256];
            snprintf(filename, sizeof(filename), "%s/%s", dirname, dir->d_name);

            if (pthread_create(&threads[threadCount], NULL, readAndParse, strdup(filename)) == 0) {
                threadCount++;
            } else {
                printf("Failed to create thread for file %s\n", filename);
            }
        }

        // Wait for all threads to finish
        for (int i = 0; i < threadCount; i++) {
            pthread_join(threads[i], NULL);
        }

        closedir(d);
    } else {
        printf("Could not open directory %s\n", dirname);
    }
}
```
