typedef struct ConfigNode {
    int priority;
    char* key;
    void* value;
    pthread_mutex_t lock;
    struct ConfigNode *left, *right, *parent;
} ConfigNode;

ConfigNode* newNode(int item) {
    ConfigNode* temp = (ConfigNode*)malloc(sizeof(ConfigNode));
    temp->key = generateUniqueKey(); // Implement this function to generate unique keys
    temp->value = NULL;
    temp->priority = item;
    temp->left = temp->right = NULL;
    pthread_mutex_init(&temp->lock, NULL);
    return temp;
}

ConfigNode* insert(ConfigNode* node, int key) {
    if (node == NULL) return newNode(key);
    if (key < node->priority)
        node->left = insert(node->left, key);
    else if (key > node->priority)
        node->right = insert(node->right, key);
    return node;
}

ConfigNode* minValueNode(ConfigNode* node) {
    ConfigNode* current = node;
    while (current && current->left != NULL)
        current = current->left;
    return current;
}

ConfigNode* deleteNode(ConfigNode* root, int key) {
    if (root == NULL) return root;
    if (key < root->priority)
        root->left = deleteNode(root->left, key);
    else if (key > root->priority)
        root->right = deleteNode(root->right, key);
    else {
        if (root->left == NULL) {
            ConfigNode* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            ConfigNode* temp = root->left;
            free(root);
            return temp;
        }
        ConfigNode* temp = minValueNode(root->right);
        root->priority = temp->priority;
        root->right = deleteNode(root->right, temp->priority);
    }
    return root;
}
```
