void *allocate(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void hashAndCompress(const char* algorithm, const unsigned char *data, size_t dataLen, unsigned char **digest, unsigned int *digestLen) {
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (EVP_DigestInit_ex(mdctx, EVP_get_digestbyname(algorithm), NULL) != 1) {
        fprintf(stderr, "Failed to initialize digest context\n");
        exit(1);
    }
    if (EVP_DigestUpdate(mdctx, data, dataLen) != 1) {
        fprintf(stderr, "Failed to update digest\n");
        exit(1);
    }
    *digest = allocate(*digestLen);
    if (EVP_DigestFinal_ex(mdctx, *digest, digestLen) != 1) {
        fprintf(stderr, "Failed to finalize digest\n");
        exit(1);
    }
    EVP_MD_CTX_free(mdctx);
}

void compressData(const unsigned char *data, size_t dataLen, unsigned char **compressed, uLongf *compressedLen) {
    *compressed = allocate(*compressedLen);
    int ret = compress2(*compressed, compressedLen, data, dataLen, Z_BEST_COMPRESSION);
    if (ret != Z_OK) {
        fprintf(stderr, "Failed to compress data\n");
        exit(1);
    }
}

record* createRecord(size_t stringLen) {
    record *rec = allocate(sizeof(record));
    rec->string = allocate(stringLen + 1);
    srand((unsigned int) time(NULL));
    for (size_t i = 0; i < stringLen; ++i) {
        rec->string[i] = 'a' + rand() % 26; // Generates a random alphanumeric character
    }
    rec->string[stringLen] = '\0';
    rec->key = rand();
    return rec;
}

void processRecord(record *rec, const char* algorithm) {
    unsigned char *digest;
    unsigned int digestLen = 256 / 8; // Assuming SHA-256
    hashAndCompress(algorithm, (unsigned char*)rec->string, strlen(rec->string), &digest, &digestLen);

    uLongf compressedLen = compressBound(digestLen);
    unsigned char *compressed;
    compressData(digest, digestLen, &compressed, &compressedLen);

    free(rec->string);
    rec->string = (char*)compressed;
}

void processRecords(record **records, size_t numRecords, const char* algorithm) {
    for (size_t i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&lock);
        processRecord(records[i], algorithm);
        pthread_mutex_unlock(&lock);
    }
}
