    pthread_mutex_init(&dataset->lock, NULL);

    return dataset;
}

void resize_dataset(Dataset* dataset, size_t new_capacity) {
    if (new_capacity <= dataset->capacity) {
        fprintf(stderr, "New capacity must be greater than current capacity\n");
        return;
    }

    pthread_mutex_lock(&dataset->lock);

    long* new_offsets = realloc(dataset->offsets, new_capacity * sizeof(long));
    if (new_offsets == NULL) {
        fprintf(stderr, "Failed to resize offsets array\n");
        pthread_mutex_unlock(&dataset->lock);
        return;
    }

    int* new_keys = realloc(dataset->keys, new_capacity * sizeof(int));
    if (new_keys == NULL) {
        fprintf(stderr, "Failed to resize keys array\n");
        free(new_offsets);
        pthread_mutex_unlock(&dataset->lock);
        return;
    }

    Record** new_records = realloc(dataset->records, new_capacity * sizeof(Record*));
    if (new_records == NULL) {
        fprintf(stderr, "Failed to resize records array\n");
        free(new_offsets);
        free(new_keys);
        pthread_mutex_unlock(&dataset->lock);
        return;
    }

    dataset->offsets = new_offsets;
    dataset->keys = new_keys;
    dataset->records = new_records;
    dataset->capacity = new_capacity;

    pthread_mutex_unlock(&dataset->lock);
}

void add_record(Dataset* dataset, int key, char* str) {
    if (dataset->size == dataset->capacity) {
        resize_dataset(dataset, dataset->capacity * 2);
    }

    pthread_mutex_lock(&dataset->lock);

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        pthread_mutex_unlock(&dataset->lock);
        return;
    }

    record->value = key;
    record->str = str;

    dataset->records[dataset->size] = record;
    dataset->keys[dataset->size] = key;
    dataset->offsets[dataset->size] = (long)record;
    dataset->size++;

    pthread_mutex_unlock(&dataset->lock);
}

int find_largest(Dataset* dataset) {
    int max = 0;
    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i]->value > max) {
            max = dataset->records[i]->value;
        }
    }

    return max;
}

EVP_CIPHER* get_cipher(const char* name, const unsigned char* key, int keylen) {
