#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int value;
} record;

typedef struct {
    _Atomic(long) *offsets;
    _Atomic(int) *keys;
    record *records;
    size_t capacity;
    pthread_mutex_t lock;
} dynamic_arrays;

dynamic_arrays* init_arrays(size_t initial_capacity) {
    dynamic_arrays* arrays = malloc(sizeof(dynamic_arrays));
    if (arrays == NULL) return NULL;

    arrays->offsets = calloc(initial_capacity, sizeof(_Atomic(long)));
    arrays->keys = calloc(initial_capacity, sizeof(_Atomic(int)));
    arrays->records = calloc(initial_capacity, sizeof(record));

    if (arrays->offsets == NULL || arrays->keys == NULL || arrays->records == NULL) {
        free(arrays->offsets);
        free(arrays->keys);
        free(arrays->records);
        free(arrays);
        return NULL;
    }

    arrays->capacity = initial_capacity;
    pthread_mutex_init(&arrays->lock, NULL);

    return arrays;
}

void resize_arrays(dynamic_arrays* arrays, size_t new_capacity) {
    pthread_mutex_lock(&arrays->lock);

    if (new_capacity > arrays->capacity) {
        arrays->offsets = realloc(arrays->offsets, new_capacity * sizeof(_Atomic(long)));
        arrays->keys = realloc(arrays->keys, new_capacity * sizeof(_Atomic(int)));
        arrays->records = realloc(arrays->records, new_capacity * sizeof(record));

        if (new_capacity > arrays->capacity) {
            arrays->capacity = new_capacity;
        } else {
            // Resize failed, restore original capacity
            arrays->offsets = realloc(arrays->offsets, arrays->capacity * sizeof(_Atomic(long)));
            arrays->keys = realloc(arrays->keys, arrays->capacity * sizeof(_Atomic(int)));
            arrays->records = realloc(arrays->records, arrays->capacity * sizeof(record));
        }
    }

    pthread_mutex_unlock(&arrays->lock);
}

void set_random_values(dynamic_arrays* arrays, int min, int max) {
    for (size_t i = 0; i < arrays->capacity; ++i) {
        arrays->records[i].value = rand() % (max - min + 1) + min;
    }
}

void free_arrays(dynamic_arrays* arrays) {
    pthread_mutex_destroy(&arrays->lock);

    free(arrays->offsets);
    free(arrays->keys);
    free(arrays->records);
    free(arrays);
}
