WorkerThread* threads = NULL;
int num_threads = 0;
config_t cfg, *cf;

void* worker(void* arg) {
    // Your event processing logic here...
}

void adjust_num_threads() {
    int new_num_threads;
    if (config_lookup_int(cf, "numThreads", &new_num_threads)) {
        num_threads = new_num_threads;
        threads = realloc(threads, num_threads * sizeof(WorkerThread));
    } else {
        fprintf(stderr, "No 'numThreads' setting in configuration file.\n");
        exit(EXIT_FAILURE);
    }
}

void start_workers() {
    for (int i = 0; i < num_threads; ++i) {
        threads[i].id = i;
        pthread_create(&threads[i].thread, NULL, worker, &threads[i].id);
    }
}

void stop_workers() {
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i].thread, NULL);
    }
}

int main() {
    config_init(&cfg);

    if(!config_read_file(&cfg, "settings.cfg")) {
        fprintf(stderr, "%s:%d - %s\n", 
                config_error_file(&cfg),
                config_error_line(&cfg),
                config_error_text(&cfg));
        config_destroy(&cfg);
        return(EXIT_FAILURE);
    } else {
        cf = &cfg;
    }

    adjust_num_threads();
    start_workers();

    // Your network event processing logic here...

    stop_workers();
    config_destroy(&cfg);
    return 0;
}
