['Here is a basic implementation of such a system using C programming language. This code does not include all the features you mentioned due to their complexity and size but it provides a good starting point for your task. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Task {
    int priority;
    char* status;
    void* data;
} Task;

typedef struct Node {
    Task* task;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addTask(int priority, char* status, void* data) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->task = (Task*)malloc(sizeof(Task));
    newNode->task->priority = priority;
    newNode->task->status = status;
    newNode->task->data = data;

    if (head == NULL || head->task->priority > priority) {
        newNode->next = head;
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->task->priority < priority) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

Task* getTask(int priority) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL && current->task->priority < priority) {
        current = current->next;
    }

    Task* task = NULL;
    if (current != NULL && current->task->priority == priority) {
        task = current->task;
    }

    pthread_mutex_unlock(&lock);

    return task;
}

void updateTask(int priority, char* status) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL && current->task->priority < priority) {
        current = current->next;
    }

    if (current != NULL && current->task->priority == priority) {
        free(current->task->status);
        current->task->status = status;
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list to store tasks in order of their priorities. It also uses a mutex for thread safety. Note that this is a very basic implementation and does not include features such as cleaning up completed tasks, handling service failures or delays, optimizing memory usage, scaling the underlying data structure efficiently, etc. You would need to add these features yourself based on your specific requirements.
