    // Generate N unique RNTI values within the range.
    int* rntis = malloc(N * sizeof(int));
    for (int i = 0; i < N; ++i) {
        do {
            rntis[i] = minRnti + rand() % (maxRnti - minRnti + 1);
        } while (!isUnique(rntis, i));
    }

    // Populate the list.
    for (int i = 0; i < N; ++i) {
        Node* node = malloc(sizeof(Node));
        if (node == NULL) {
            pthread_mutex_unlock(&lock);
            return;
