        NFAPI_CRC_INDICATION_PDU_T* data = createData(rntis[i], template);
        if (data == NULL) {
            free(node);
            pthread_mutex_unlock(&lock);
            return;
        }

        node->data = data;
        node->next = head;
        head = node;
    }

    count += N;
    pthread_mutex_unlock(&lock);
}

int isUnique(int* rntis, int size) {
    for (int i = 0; i < size; ++i) {
        if (rntis[size] == rntis[i]) {
            return 0;
        }
    }

    return 1;
}
