void addElement(List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->size >= list->capacity) {
        // Reallocate memory with double the current capacity
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Check for duplicate RNTI values
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == element.RNTI) {
            printf("Error: Duplicate RNTI value detected.\n");
            return;
        }
    }

    // Add the new element to the list
    list->data[list->size++] = element;
}

void removeElement(List *list, int index) {
    if (index < 0 || index >= list->size) {
        printf("Error: Index out of bounds.\n");
        return;
    }

    // Shift all elements after the removed one to fill the gap
    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }

    --list->size;
}
