#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *next, *prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int size;
    int capacity;
    time_t timeout;
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
} List;

List* createList(int capacity, time_t timeout) {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL; // Handle memory allocation failure

    pthread_mutex_init(&list->lock, NULL);
    list->capacity = capacity;
    list->timeout = timeout;
    list->head = list->tail = NULL;
    list->size = 0;

    return list;
}

void addElement(List* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) { // If at capacity, evict LRU element
        removeElement(list, list->tail);
    }

    element->next = list->head;
    if (list->head != NULL) {
        list->head->prev = element;
    }
    list->head = element;
    if (list->tail == NULL) {
        list->tail = element;
    }

    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void removeElement(List* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);

    if (element == list->head) {
        list->head = element->next;
    }

    if (element == list->tail) {
        list->tail = element->prev;
    }

    if (element->next != NULL) {
        element->next->prev = element->prev;
    }

    if (element->prev != NULL) {
        element->prev->next = element->next;
    }

    free(element);
    list->size--;

    pthread_mutex_unlock(&list->lock);
}

void cleanupList(List* list) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (difftime(currentTime, current->timestamp) > list->timeout) {
            NFAPI_CRC_INDICATION_PDU_T* temp = current;
            current = current->next;
            removeElement(list, temp);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}
```
