Node* parseAndProcessCSV(FILE* file) {
    Node* head = NULL;
    Node* tail = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for a new record\n");
            continue;
        }

        char* token = strtok(line, ",");
        int field_index = 0;
        while (token != NULL) {
            switch (field_index) {
                case 0:
                    record->name = malloc(strlen(token) + 1);
                    if (!record->name) {
                        fprintf(stderr, "Failed to allocate memory for a name\n");
                        continue;
                    }
                    strcpy(record->name, token);
                    break;
                case 1:
                    record->email = malloc(strlen(token) + 1);
                    if (!record->email) {
                        fprintf(stderr, "Failed to allocate memory for an email\n");
                        continue;
                    }
                    strcpy(record->email, token);
                    break;
                case 2:
                    record->phone_number = malloc(strlen(token) + 1);
                    if (!record->phone_number) {
                        fprintf(stderr, "Failed to allocate memory for a phone number\n");
                        continue;
                    }
                    strcpy(record->phone_number, token);
                    break;
                default:
                    fprintf(stderr, "Too many fields in the record\n");
                    continue;
            }
            ++field_index;
            token = strtok(NULL, ",");
        }

        if (field_index != 3) {
            fprintf(stderr, "Not enough fields in the record\n");
            continue;
        }

        Node* node = malloc(sizeof(Node));
        if (!node) {
            fprintf(stderr, "Failed to allocate memory for a new node\n");
            continue;
        }
        node->record = record;
        node->next = NULL;

        if (tail) {
            tail->next = node;
            tail = node;
        } else {
            head = tail = node;
        }
    }

    return head;
}
```
