import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class RecordManager {
    private final ConcurrentHashMap<Integer, Record> records = new ConcurrentHashMap<>();
    private final Lock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();

    public void addRecord(int key, float weight, long offset) {
        lock.lock();
        try {
            while (records.size() >= 1000) // arbitrary limit for demonstration purposes
                notFull.await();

            Record record = new Record(key, weight, offset);
            records.putIfAbsent(key, record);
            notFull.signalAll();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            lock.unlock();
        }
    }

    public Record getRecord(int key) {
        return records.get(key);
    }
}

class Record {
