} UnionFind;

UnionFind uf;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize Union-Find data structure
void init(int n) {
    uf.n = n;
    uf.parent = (int*) malloc(n * sizeof(int));
    uf.rank = (int*) calloc(n, sizeof(int));

    for (int i = 0; i < n; ++i) {
        uf.parent[i] = i;
    }
}

// Function to find the root of an element in Union-Find data structure
int find(int x) {
    if (uf.parent[x] != x) {
        uf.parent[x] = find(uf.parent[x]);
    }

    return uf.parent[x];
}

// Function to merge two elements in Union-Find data structure
void union_(int x, int y) {
    pthread_mutex_lock(&lock);
    x = find(x), y = find(y);

    if (uf.rank[x] < uf.rank[y]) {
        uf.parent[x] = y;
    } else {
        uf.parent[y] = x;

        if (uf.rank[x] == uf.rank[y]) {
            ++uf.rank[x];
        }
    }

    pthread_mutex_unlock(&lock);
}

// Function to process incoming network packets in real-time
