    pthread_mutex_lock(&system->lock);

    if (system->count == system->capacity) {
        // Double the capacity when full
        system->capacity *= 2;
        system->offsets = realloc(system->offsets, system->capacity * sizeof(long));
        system->keys = realloc(system->keys, system->capacity * sizeof(int));
        system->entries = realloc(system->entries, system->capacity * sizeof(data_entry));
    }

    system->offsets[system->count] = offset;
    system->keys[system->count] = key;
    system->entries[system->count] = entry;
    system->count++;

    pthread_mutex_unlock(&system->lock);
}

void reset_logs(LogSystem* system) {
