    srand(time(0));

    // Allocating memory for arrays
    long *offsets = malloc(1024 * 1024); // 1 MB
    if (offsets == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    int *keys = calloc(1000, sizeof(int));
    if (keys == NULL) {
        printf("Memory allocation failed\n");
        free(offsets);
        return NULL;
    }

    Record *records = malloc(sizeof(Record) * 1000);
    if (records == NULL) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initializing arrays
    for (int i = 0; i < 1024 * 1024 / sizeof(long); i++) {
        offsets[i] = rand() % 100000;
    }

    int key_index = 0;
    for (int i = 0; i < 1000; i++) {
        while (keys[key_index]) {
            key_index = rand() % 1000;
        }

        keys[key_index] = i + 1;
    }

    int sum = 0;
    for (int i = 0; i < 1000; i++) {
        records[i].value = min + rand() % (max - min);
        sum += records[i].value;

        if (sum > 10000) {
            records[i].value = 10000 - (sum - records[i].value);
            break;
        }
    }

    // Returning allocated memory
    void *allocated_memory = malloc(sizeof(*offsets) + sizeof(*keys) + sizeof(*records));
    if (allocated_memory == NULL) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    allocated_memory = memcpy(allocated_memory, offsets, sizeof(*offsets));
    allocated_memory = mempcpy(allocated_memory, keys, sizeof(*keys));
    allocated_memory = mempcpy(allocated_memory, records, sizeof(*records));

    // Freeing individual arrays
    free(offsets);
    free(keys);
    free(records);

    return allocated_memory;
}
