    if (strstr(json, token_type) == NULL) return 0;

    const char* expires_in = "\"expires_in\":";
    const char* pos = strstr(json, expires_in);
    if (pos == NULL || !isdigit((unsigned char)*++pos)) return 0;
    int expiry = atoi(pos);
    while (isdigit((unsigned char)*pos)) ++pos;
    if (*pos != ',' || expiry <= 0 || expiry >= 3600) return 0;

    const char* access_token = "\"access_token\":";
    pos = strstr(json, access_token);
    if (pos == NULL || *++pos != '\"' || *(pos + 1) == '\0') return 0;

    const char* refresh_token = "\"refresh_token\":";
    pos = strstr(json, refresh_token);
    if (pos != NULL && (*++pos != '\"' || *(pos + 1) == '\0')) return 0;

    while(*pos != ',' && *pos != '}') ++pos;
    if (*pos != ',') return 0;

    return 1;
}
```
This function works by searching for the expected fields in the JSON string and checking their values. It uses `strstr` to find each field, then checks the value using `isdigit` for numeric values and simple pointer arithmetic to check leading/trailing whitespace and additional unexpected fields. 

