            u2 = (double)rand() / RAND_MAX;
        } while (u1 == 0.0); // to avoid division by zero

        double z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
        configurations[i].TX_POWER_LEVEL = meanPowerLevel + stdDeviation * z0;
    }

    fclose(file);
    return configurations;
}

void freeConfigurations(LTE_PHY_TESTER_TX_CONFIG* configurations) {
    free(configurations);
}
