    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Simple hash table for tracking unique RNTI values
#define MAX_RNTI 1024
int rnti_hash[MAX_RNTI];
pthread_mutex_t hash_lock = PTHREAD_MUTEX_INITIALIZER;

// Cache mechanism to store frequently accessed structures
