int conflicts[MAX_CONFLICTS];
int num_conflicts = 0;
pthread_mutex_t conflict_lock = PTHREAD_MUTEX_INITIALIZER;

// Allocate and initialize the array of structures
NFAPI_CRC_INDICATION_PDU_T *allocate_and_initialize(int N, unsigned int *seed, int base_RNTI) {
    assert(N > 0 && N <= 1000);
    assert(base_RNTI >= 0 && base_RNTI < MAX_RNTI);

