    for (int i = 0; i < N; ++i) {
        int RNTI;

        pthread_mutex_lock(&hash_lock);
        do {
            RNTI = rand_r(seed) % MAX_RNTI + base_RNTI;  // Generate a unique RNTI value

            if (rnti_hash[RNTI] == 1) {
                pthread_mutex_lock(&conflict_lock);
