        } while (rnti_hash[RNTI] == 1);
        pthread_mutex_unlock(&hash_lock);

        array[i].RNTI = RNTI;
        array[i].CRC_INDICATION_REL8_TAG = rand_r(seed) % 2;  // Set CRCFLAG to either 0 or 1 with equal probability
    }

