typedef struct {
    int value;
    long* offset;
    int* key;
} record;

void processData(size_t size, char* string) {
    if (size == 0) return; // handle edge case of zero-sized arrays

    srand((unsigned int)time(NULL)); // seed random number generator

    long* offsets = malloc(size * sizeof(long));
    int* keys = calloc(size, sizeof(int));
    record* records = malloc(size * sizeof(record));

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand(); // set random value to each offset

        int key;
        do {
            key = rand() % size; // generate a unique key within the range of keys array
        } while (keys[key]);
        keys[key] = 1;

        records[i].value = rand(); // set random value to each record's int field
        records[i].offset = &offsets[i];
        records[i].key = &keys[key];
    }

    unsigned char md5_result[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)string, strlen(string), md5_result); // compute the MD5 hash of a provided string

    int key;
    printf("Enter a key to search: ");
    scanf("%d", &key);

    if (key >= 0 && key < size) {
        for (size_t i = 0; i < size; ++i) {
            if (*records[i].key == key) {
                printf("Record found: value = %d, offset = %ld\n", records[i].value, *records[i].offset);
                break;
            }
        }
    } else {
        printf("Invalid key query.\n");
    }

    free(records); // deallocate memory for records array
    free(keys); // deallocate memory for keys array
    free(offsets); // deallocate memory for offsets array
}
