            } else {
                errorCount++;
            }

            if (*it == first && !found) {
                found = true;
                it = list.insert_after(it, second);
            }
        } catch (const std::exception& e) {
            mtx.lock();
            std::cerr << "Caught exception: " << e.what() << '\n';
            mtx.unlock();

            errorCount++;
        }
    }

    if (!found) {
        list.push_front(second);
    }
}
