['Here is a basic implementation in C using pthread library for thread safety. This code does not include logging mechanism or any optimization techniques as it would be quite complex to implement here. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long* offsets;
    int* keys;
    struct record* records;
} DatabaseIndexingSystem;

typedef struct {
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

DatabaseIndexingSystem* allocateMemory(size_t sizeLimit) {
    DatabaseIndexingSystem* system = malloc(sizeof(DatabaseIndexingSystem));

    if (system == NULL) {
        return NULL; // Out of memory error
    }

    pthread_mutex_lock(&lock);

    size_t totalSize = 0;
    system->offsets = malloc(sizeLimit / 3 * sizeof(long));
    if (system->offsets == NULL) {
        free(system);
        return NULL; // Out of memory error
    }

    totalSize += sizeLimit / 3 * sizeof(long);

    system->keys = malloc(sizeLimit / 3 * sizeof(int));
    if (system->keys == NULL) {
        free(system->offsets);
        free(system);
        return NULL; // Out of memory error
    }

    totalSize += sizeLimit / 3 * sizeof(int);

    system->records = malloc(sizeLimit / 3 * sizeof(Record));
    if (system->records == NULL) {
        free(system->offsets);
        free(system->keys);
        free(system);
        return NULL; // Out of memory error
    }

    totalSize += sizeLimit / 3 * sizeof(Record);

    if (totalSize > sizeLimit) {
        free(system->offsets);
        free(system->keys);
        free(system->records);
        free(system);
        return NULL; // Memory request exceeds limit error
    }

    pthread_mutex_unlock(&lock);

    return system;
}
```
This code allocates memory for the three main components of the database indexing system. It uses a mutex to ensure thread safety and handles allocation failures by releasing any partially allocated memory and returning an appropriate error code. 

