["Here is a basic implementation of your request in C using pthreads for thread safety and dynamic resizing with realloc to minimize overhead. Error handling is done by checking if malloc or realloc returned NULL. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long timestamp;
    int id;
    int status;
} event_t;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    long* timestamps;
    int* identifiers;
    event_t* events;
} event_manager_t;

event_manager_t* create_event_manager(size_t initial_capacity) {
    event_manager_t* manager = malloc(sizeof(event_manager_t));
    if (manager == NULL || pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->timestamps = malloc(initial_capacity * sizeof(long));
    manager->identifiers = malloc(initial_capacity * sizeof(int));
    manager->events = malloc(initial_capacity * sizeof(event_t));

    if (manager->timestamps == NULL || manager->identifiers == NULL || manager->events == NULL) {
        destroy_event_manager(manager);
        return NULL;
    }

    return manager;
}

void add_event(event_manager_t* manager, int status) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;

        long* new_timestamps = realloc(manager->timestamps, new_capacity * sizeof(long));
        int* new_identifiers = realloc(manager->identifiers, new_capacity * sizeof(int));
        event_t* new_events = realloc(manager->events, new_capacity * sizeof(event_t));

        if (new_timestamps == NULL || new_identifiers == NULL || new_events == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->capacity = new_capacity;
        manager->timestamps = new_timestamps;
        manager->identifiers = new_identifiers;
        manager->events = new_events;
    }

    long timestamp = time(NULL);
    int id = (int)manager->count;

    manager->timestamps[manager->count] = timestamp;
    manager->identifiers[manager->count] = id;
    manager->events[manager->count].timestamp = timestamp;
    manager->events[manager->count].id = id;
    manager->events[manager->count].status = status;
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

void destroy_event_manager(event_manager_t* manager) {
    if (manager != NULL) {
        free(manager->timestamps);
        free(manager->identifiers);
        free(manager->events);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
```
This code is a basic example and does not include all the error handling you might need in a real application. For instance, it doesn't handle errors from time or realloc calls. It also doesn't handle memory allocation failures for the mutex lock. In a real-world scenario, you would want to add appropriate error handling code to deal with these situations.
