    $password .= $characterList[rand(0, count($characterList) - 1)]; // Ensure we have at least one of each type
    $password .= strtoupper($characterList[rand(0, count($characterList) - 1)]);
    $password .= rand(0,9);

    while(strlen($password) < $length) {
        $password .= $characterList[rand(0, count($characterList) - 1)];
    }

    return str_shuffle($password); // Randomize the order of characters in the string
}

function securePasswordHashing($password) {
