typedef struct connection {
    char* ip;
    int port;
    time_t lastAccessed;
    int status;
} Connection;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int maxMemory = 1024 * 1024 * 500; // 500MB
int currentMemory = 0;
Connection** pool;
int poolSize = 0;

void* manageResourceUsage(void* arg) {
    char ip[INET6_ADDRSTRLEN];
    int port, status;

    while (scanf("%s %d %d", ip, &port, &status) == 3) {
        pthread_mutex_lock(&mutex);

        if (currentMemory + sizeof(Connection*) > maxMemory) {
            printf("Error: Not enough memory to allocate new connection\n");
            continue;
        }

        pool[poolSize] = malloc(sizeof(Connection));
        if (!pool[poolSize]) {
            printf("Error: Failed to allocate memory for new connection\n");
            pthread_mutex_unlock(&mutex);
            continue;
        }

        pool[poolSize]->ip = malloc(strlen(ip) + 1);
        if (!pool[poolSize]->ip) {
            printf("Error: Failed to allocate memory for IP address\n");
            free(pool[poolSize]);
            pthread_mutex_unlock(&mutex);
            continue;
        }

        strcpy(pool[poolSize]->ip, ip);
        pool[poolSize]->port = port;
        pool[poolSize]->status = status;
        gettimeofday(&(pool[poolSize]->lastAccessed), NULL);

        currentMemory += sizeof(Connection*) + strlen(ip) + 1;
        poolSize++;

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}
```
