    MetadataField** metadata;
} Document;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int* owner_ids;
char** access_levels;

void* createDocument(void* arg) {
    char* corpus = (char*)arg;

    Document* doc = malloc(sizeof(Document));
    if (!doc) return NULL; // Handle allocation failure

    pthread_mutex_lock(&lock);
    int id = rand() % sizeof(owner_ids);
    doc->owner_id = owner_ids[id];

    int level = rand() % sizeof(access_levels);
    doc->access_level = access_levels[level];
    pthread_mutex_unlock(&lock);

    // Generate file name and content from corpus
    size_t len = strlen(corpus) < 10 ? strlen(corpus) : 10;
    doc->file_name = malloc(sizeof(char) * (len + 1));
    if (!doc->file_name) return NULL; // Handle allocation failure

    strncpy(doc->file_name, corpus, len);
    doc->file_name[len] = '\0';

    size_t contentLen = strlen(corpus) < 100 ? strlen(corpus) : 100;
    doc->content = malloc(sizeof(char) * (contentLen + 1));
    if (!doc->content) return NULL; // Handle allocation failure

    strncpy(doc->content, corpus, contentLen);
    doc->content[contentLen] = '\0';

    // Compress the content
    Bytef* compressedContent = malloc(sizeof(Bytef) * (strlen(doc->content) + 1));
    if (!compressedContent) return NULL; // Handle allocation failure

    uLongf compressedLen = compressBound(strlen(doc->content));
    compress((Bytef*)compressedContent, &compressedLen, (const Bytef*)doc->content, strlen(doc->content));

    free(doc->content); // Free the original content
    doc->content = compressedContent;

    return doc;
}
```
This code creates a new document with a randomly selected owner_id and access_level. It also generates a file name from the first 10 characters of the corpus, and truncates the content to the first 100 characters before compressing it using zlib's compression function. The compressed content is stored in the Document structure, replacing the original content.
