void logOperation(char *operation, int size) {
    pthread_mutex_lock(&lock);
    fprintf(logFile, "%s: %d bytes\n", operation, size);
    pthread_mutex_unlock(&lock);
}

record* allocateMemoryForRecords(int numOfRecords) {
    int size = sizeof(record)*numOfRecords;

    if (currentMemoryUsage + size > maxMemoryUsage) {
        printf("Not enough memory\n");
        return NULL;
    }

    record *records = malloc(size);
    if (records == NULL) {
        perror("malloc failed");
        return NULL;
    }

    currentMemoryUsage += size;
    logOperation("Allocated", size);

    return records;
}

void deallocateRecords(record *records, int numOfRecords) {
    if (records == NULL) {
        printf("No memory to free\n");
        return;
    }

    int size = sizeof(record)*numOfRecords;
    logOperation("Deallocated", size);
    currentMemoryUsage -= size;

    free(records);
}

void loadConfigFile(char *filePath, record **records, int *numOfRecords) {
    FILE *configFile = fopen(filePath, "r");
    if (configFile == NULL) {
        perror("Failed to open config file");
        return;
    }

    // Assuming each line in the file contains a key and an offset separated by a space.
    int key, offset;
    *numOfRecords = 0;
    while (fscanf(configFile, "%d %ld", &key, &offset) == 2) {
