            record *newRecords = allocateMemoryForRecords(*numOfRecords + 1);
            if (newRecords != NULL && *records != NULL) {
                memcpy(newRecords, *records, sizeof(record)*(*numOfRecords));
                deallocateRecords(*records, *numOfRecords);
            }
            *records = newRecords;
        }

        if (*records != NULL) {
            (*records)[*numOfRecords].key = key;
            (*records)[*numOfRecords].offset = offset;
            (*numOfRecords)++;
        } else {
            break;
        }
    }

    fclose(configFile);
}

int main() {
    logFile = fopen("log.txt", "w");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    record *records = NULL;
    int numOfRecords = 0;
    loadConfigFile("/path/to/config.txt", &records, &numOfRecords);

    // Use the records...

    deallocateRecords(records, numOfRecords);
    fclose(logFile);

    return 0;
}
