#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>

typedef struct record {
    int key;
    long offset;
} Record;

typedef struct cache_entry {
    Record *record;
    struct cache_entry *next;
} CacheEntry;

CacheEntry *cache = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void add_to_cache(Record *record) {
    pthread_mutex_lock(&cache_lock);
    CacheEntry *entry = malloc(sizeof(CacheEntry));
    entry->record = record;
    entry->next = cache;
    cache = entry;
    pthread_mutex_unlock(&cache_lock);
}

Record* get_from_cache(int key) {
    pthread_mutex_lock(&cache_lock);
    CacheEntry *entry = cache;
    while (entry != NULL) {
        if (entry->record->key == key) {
            Record *result = entry->record;
            pthread_mutex_unlock(&cache_lock);
            return result;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void *manage_memory(void *arg) {
    int range = *((int *) arg);
    Record *records = malloc(range * sizeof(Record));
    for (int i = 0; i < range; ++i) {
        records[i].key = i;
        records[i].offset = i * 1024L;
        add_to_cache(&records[i]);
    }
    while (1) {
        sleep(5); // simulate work
        Record *record = get_from_cache(rand() % range);
        if (record != NULL) {
            printf("Key: %d, Offset: %ld\n", record->key, record->offset);
        } else {
            printf("Record not found in cache.\n");
        }
    }
}

int main() {
    int range = 10; // for example
    pthread_t thread;
    pthread_create(&thread, NULL, manage_memory, &range);
    pthread_join(thread, NULL);
    return 0;
}
