#include <iostream>
#include <string>
#include <vector>
#include <functional>
#include <chrono>
#include <random>
#include <openssl/sha.h> // include OpenSSL for SHA-256, SHA-512, MD5
#include <zlib.h> // include zlib for Zlib compression

class Record {
public:
    std::string id;
    int statusCode;
    std::vector<uint8_t> payload;
    double timestamp;
    std::function<void()> callback;

    Record(std::vector<uint8_t> payload, std::function<void()> callback) {
        this->id = generateRandomId();
        this->timestamp = getCurrentTimestamp();
        this->payload = payload;
        this->callback = callback;
    }

private:
    std::string generateRandomId() {
        static auto& chrs = "0123456789"
            "abcdefghijklmnopqrstuvwxyz"
            "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

        thread_local static std::mt19937 rg{std::random_device{}()};
        thread_local static std::uniform_int_distribution<std::string::size_type> pick(0, sizeof(chrs) - 2);

        std::string s;
        s.reserve(16); // length of the id
        while(s.size() != 16) {
            s += chrs[pick(rg)];
        }
        return s;
    }

    double getCurrentTimestamp() {
        auto now = std::chrono::system_clock::now();
        auto now_ms = std::chrono::time_point_cast<std::chrono::milliseconds>(now);
        auto epoch = now_ms.time_since_epoch();
        return static_cast<double>(epoch.count());
    }
