['Here is an example of how you might implement such a function in C using pthreads for thread safety and error handling. This code does not include logging or integration with external libraries as those would significantly increase complexity. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

Record* records = NULL;
size_t recordCount = 0;
size_t maxRecords = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize(size_t initialSize) {
    pthread_mutex_lock(&mutex);

    if (records != NULL) {
        free(records);
    }

    records = malloc(initialSize * sizeof(Record));
    maxRecords = initialSize;
    recordCount = 0;

    pthread_mutex_unlock(&mutex);
}

void addRecord(long offset, int key, double value) {
    pthread_mutex_lock(&mutex);

    if (recordCount >= maxRecords) {
        // Resize the array
        Record* newArray = realloc(records, 2 * maxRecords * sizeof(Record));

        if (newArray == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }

        records = newArray;
        maxRecords *= 2;
    }

    // Add the record
    Record* record = &records[recordCount];
    record->offset = offset;
    record->key = key;
    record->value = value;
    ++recordCount;

    pthread_mutex_unlock(&mutex);
}
```
This code provides a basic example of how you might manage a dynamic collection of records in C. It uses a mutex to ensure that only one thread can modify the record array at a time, preventing race conditions and deadlocks. The `initialize` function initializes the record array with a specified size, while the `addRecord` function adds a new record to the array. If the array is full, it resizes the array by doubling its size using realloc.
