```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    long offset;
    int key;
    char *value;
    time_t timestamp;
    pthread_mutex_t lock;
    size_t refCount;
    struct Record *parent;
} Record;

typedef void (*ObserverCallback)(Record*);

typedef struct Observer {
    ObserverCallback callback;
    struct Observer *next;
} Observer;

typedef struct RecordManager {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    Observer *observers;
} RecordManager;

char* generateRandomString(size_t length) {
    static char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString;

    if (length) {
        randomString = malloc(length + 1);

        if (randomString) {
            for (size_t n = 0;n < length;n++) {
                int key = rand() % (int)(sizeof charset - 1);
                randomString[n] = charset[key];
            }

            randomString[length] = '\0';
        }
    }

    return randomString;
}

Record* createRecord(long offset, int key, char *value) {
    Record *record = malloc(sizeof(Record));

    if (record != NULL) {
        record->offset = offset;
        record->key = key;
        record->value = value;
        record->timestamp = time(NULL);
        pthread_mutex_init(&record->lock, NULL);
        record->refCount = 0;
        record->parent = NULL;
    }

    return record;
}

void destroyRecord(Record *record) {
    if (record != NULL) {
        pthread_mutex_destroy(&record->lock);
        free(record->value);
        free(record);
    }
}

int registerObserver(RecordManager *manager, ObserverCallback callback) {
    Observer *observer = malloc(sizeof(Observer));

    if (observer != NULL) {
        observer->callback = callback;
        pthread_mutex_lock(&manager->lock);
        observer->next = manager->observers;
        manager->observers = observer;
        pthread_mutex_unlock(&manager->lock);

        return 0;
    }

    return -1;
}

void unregisterObserver(RecordManager *manager, ObserverCallback callback) {
    pthread_mutex_lock(&manager->lock);
    Observer **prevNext = &manager->observers;
    Observer *current = manager->observers;

    while (current != NULL) {
        if (current->callback == callback) {
            *prevNext = current->next;
            free(current);

            break;
        }

        prevNext = &current->next;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void notifyObservers(RecordManager *manager, Record *record) {
    Observer *observer = manager->observers;

    while (observer != NULL) {
        observer->callback(record);
        observer = observer->next;
    }
}
```
