int delete_record(RecordManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            // Shift all records after the deleted one to fill the gap.
            memmove(&manager->records[i], &manager->records[i + 1], 
                    (manager->count - i - 1) * sizeof(Record));

            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;  // Success.
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;  // Record not found.
}
