["Here is an example of how you might implement this in C using pthreads for synchronization and OpenSSL for hashing:

```c
#include <stdlib.h>
#include <pthread.h>
#include <openssl/sha.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct data {
    long* offsets;
    size_t numOffsets;
    unsigned char* keys;
    size_t numKeys;
    Record* records;
    size_t numRecords;
    uint8_t* metadata;
    size_t numMetadata;
} Data;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned char* hash(long offset) {
    unsigned char* digest = malloc(SHA256_DIGEST_LENGTH);
    SHA256((unsigned char*)&offset, sizeof(long), digest);
    return digest;
}

Data* initializeArrays(size_t sizeOffsets, size_t sizeRecords) {
    if (sizeOffsets <= 0 || sizeRecords <= 0) {
        return NULL;
    }

    Data* data = malloc(sizeof(Data));
    if (!data) {
        return NULL;
    }

    pthread_mutex_lock(&lock);

    data->offsets = malloc(sizeOffsets * sizeof(long));
    data->numOffsets = sizeOffsets;
    for (size_t i = 0; i < sizeOffsets; ++i) {
        if (!data->offsets) {
            pthread_mutex_unlock(&lock);
            free(data);
            return NULL;
        }
        data->offsets[i] = i + 1; // Initialize offset values to unique values based on index.
    }

    data->keys = malloc(sizeOffsets * SHA256_DIGEST_LENGTH);
    data->numKeys = sizeOffsets;
    for (size_t i = 0; i < sizeOffsets; ++i) {
        if (!data->keys) {
            pthread_mutex_unlock(&lock);
            free(data->offsets);
            free(data);
            return NULL;
        }
        unsigned char* key = hash(data->offsets[i]); // Generate unique keys by hashing offset values.
        memcpy(data->keys + i * SHA256_DIGEST_LENGTH, key, SHA256_DIGEST_LENGTH);
        free(key);
    }

    data->records = malloc(sizeRecords * sizeof(Record));
    data->numRecords = sizeRecords;
    srand((unsigned int)time(NULL)); // Seed random number generator.
    for (size_t i = 0; i < sizeRecords; ++i) {
        if (!data->records) {
            pthread_mutex_unlock(&lock);
            free(data->offsets);
            free(data->keys);
            free(data);
            return NULL;
        }
        data->records[i].value = rand() % 100 + 1; // Generate random int value within specified range.
    }

    data->metadata = calloc(sizeRecords, sizeof(uint8_t));
    data->numMetadata = sizeRecords;

    pthread_mutex_unlock(&lock);

    return data;
}
```
This code uses a mutex to ensure that only one thread can access and modify the arrays at any given time, preventing race conditions. The `hash` function generates unique keys by hashing offset values using SHA-256. The random number generator is seeded with the current time to avoid predictable sequences.

Please note that this code does not handle memory deallocation upon completion or error. You would need to add appropriate cleanup code in your application's main function or wherever you are calling `initializeArrays` from.
