```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.script.*;

public class DynamicJavaScriptLoader {
    private static final String FILE_CONFIG = "config.txt";
    private static final int MAX_CACHE_SIZE = 10;

    private Map<String, byte[]> cache = new ConcurrentHashMap<>();
    private List<Future<?>> futures = Collections.synchronizedList(new ArrayList<>());
    private ExecutorService executor = Executors.newCachedThreadPool();

    public void loadAndExecuteScripts() {
        try (BufferedReader reader = new BufferedReader(new FileReader(FILE_CONFIG))) {
            String line;
            while ((line = reader.readLine()) != null) {
                futures.add(executor.submit(() -> loadAndExecuteScript(line)));
            }
        } catch (IOException e) {
            System.err.println("Error reading config file: " + e);
        }
    }

    private void loadAndExecuteScript(String filename) {
        try {
            byte[] bytes = cache.computeIfAbsent(filename, this::loadFileBytes);

            if (bytes != null) {
                ScriptEngineManager manager = new ScriptEngineManager();
                ScriptEngine engine = manager.getEngineByName("JavaScript");

                engine.eval(new String(bytes));
            }
        } catch (Exception e) {
            System.err.println("Error loading or executing script " + filename + ": " + e);
        }
    }

    private byte[] loadFileBytes(String filename) {
        try {
            return Files.readAllBytes(Paths.get(filename));
        } catch (IOException e) {
            System.err.println("Error loading file " + filename + ": " + e);
            return null;
        }
    }

    public String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());

        return new BigInteger(1, messageDigest).toString(16);
    }

    public void shutdown() {
        executor.shutdown();

        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
