DataStructure* create_data_structure(size_t size) {
    srand(time(NULL));

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(size, sizeof(long));
    ds->keys = calloc(size, sizeof(int));
    ds->records = calloc(size, sizeof(Record));
    ds->size = size;

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        free_data_structure(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        int value;

        do {
            value = rand() % INT_MAX;
        } while (contains(ds->keys, ds->size, value));

        ds->records[i].value = value;
    }

    return ds;
}

void free_data_structure(DataStructure* ds) {
    if (ds == NULL) return;

    pthread_mutex_destroy(&ds->lock);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

int contains(const int* array, size_t size, int value) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == value) return 1;
    }

    return 0;
}
