    array->events = calloc(initial_capacity, sizeof(event));
    return array;
}

void add_event(event_array* array, event evt) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->events = realloc(array->events, new_capacity * sizeof(event));
        array->capacity = new_capacity;
    }

    array->events[array->count] = evt;
    array->count++;

    pthread_mutex_unlock(&array->lock);
}
