        return std::hash<int>{}(pdu.RNTI); // or any other hash function you want to use
    }
};

void processBatch(std::vector<NFAPI_CRC_INDICATION_PDU_T>& batch, std::unordered_set<NFAPI_CRC_INDICATION_PDU_T, NFAPI_CRC_INDICATION_PDU_T_Hash>& processed) {
    for (auto& pdu : batch) {
        if (processed.find(pdu) != processed.end()) {
            // Duplicate found
            continue;
        } else {
            processed.insert(pdu);
        }

        // Process the PDU here...
    }
