    std::unordered_set<NFAPI_CRC_INDICATION_PDU_T, NFAPI_CRC_INDICATION_PDU_T_Hash> processed;

    while (true) {
        std::unique_lock<std::mutex> lck(mtx);

        // Wait until main thread signals that a batch is ready.
        cv.wait(lck, [] { return ready.load(); });

        processBatch(batch, processed);

        // Notify the main thread that we're done processing this batch.
        ready = false;
        lck.unlock();
        cv.notify_one();
    }
}

int main() {
    std::thread worker(workerThread);

    while (true) {
        // Fetch a new batch of PDUs from the external data source...

        std::unique_lock<std::mutex> lck(mtx);

        // Wait until the worker thread is done processing the previous batch.
        cv.wait(lck, [] { return !ready; });

        // Fill the batch with new PDUs...

        ready = true;
        lck.unlock();
