#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    double start_time;
    double duration;
    int status_flag;
    int priority_level;
} TaskDescriptor;

TaskDescriptor* tasks = NULL;
int task_count = 0;
int max_tasks = 100; // initial size of the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_task(TaskDescriptor* task) {
    task->id = -1;
    task->start_time = 0.0;
    task->duration = 0.0;
    task->status_flag = 0;
    task->priority_level = 0;
}

void add_task(TaskDescriptor* new_task) {
    pthread_mutex_lock(&mutex);

    if (task_count >= max_tasks) {
        // resize the array
        max_tasks *= 2;
        tasks = realloc(tasks, max_tasks * sizeof(TaskDescriptor));

        if (!tasks) {
            printf("Failed to allocate memory for new task\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    tasks[task_count] = *new_task;
    task_count++;

    pthread_mutex_unlock(&mutex);
}

void modify_job_id(int index, char* identifier_type) {
    if (index < 0 || index >= task_count) {
        printf("Invalid task index\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    // generate a unique sequence number for the new job id
    static int sequence = 1;
    char new_id[256];
    sprintf(new_id, "%d-%s", sequence++, identifier_type);

    tasks[index].id = atoi(new_id);

    pthread_mutex_unlock(&mutex);
}
```
