["Here is a basic implementation of your requirements using C language with POSIX threads (pthreads) for thread safety and error handling. This code does not include the integration with an external monitoring and logging framework or configurable resource limits as these would require additional libraries and complexities that are beyond the scope of this task.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    char* name;
    int port_number;
    bool enabled;
    double timeout_value;
} config;

config** configurations = NULL;
size_t configuration_count = 0;
pthread_mutex_t lock;

void add_configuration(const char* name, int port_number, bool enabled, double timeout_value) {
    if (name == NULL || strlen(name) == 0) return; // validate input

    pthread_mutex_lock(&lock);

    configuration_count++;
    configurations = realloc(configurations, sizeof(*configurations) * configuration_count);
    if (configurations == NULL) {
        configuration_count--; // rollback on error
        pthread_mutex_unlock(&lock);
        return;
    }

    configurations[configuration_count - 1] = malloc(sizeof(**configurations));
    if (configurations[configuration_count - 1] == NULL) {
        configuration_count--; // rollback on error
        pthread_mutex_unlock(&lock);
        return;
    }

    configurations[configuration_count - 1]->name = strdup(name);
    if (configurations[configuration_count - 1]->name == NULL) {
        free(configurations[configuration_count - 1]); // rollback on error
        configuration_count--;
        pthread_mutex_unlock(&lock);
        return;
    }

    configurations[configuration_count - 1]->port_number = port_number;
    configurations[configuration_count - 1]->enabled = enabled;
    configurations[configuration_count - 1]->timeout_value = timeout_value;

    pthread_mutex_unlock(&lock);
}
```
This code provides a basic mechanism for adding configuration parameters. It uses `pthread_mutex_t` to ensure thread safety and protects the shared resource (the configurations array) from concurrent access and modification. The function also validates input before attempting to add it, ensuring data integrity. 

