    manager->count = 0;
    manager->offsets = malloc(initialCapacity * sizeof(long));
    manager->keys = malloc(initialCapacity * sizeof(int));
    manager->records = malloc(initialCapacity * sizeof(Record*));

    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL) {
        free_manager(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void free_manager(MemoryManager* manager) {
    if (manager != NULL) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->records[i]);
        }

        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
    }

    free(manager);
}

int add_record(MemoryManager* manager, long offset, int key, int value) {
    assert(manager != NULL);

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;

        long* newOffsets = realloc(manager->offsets, newCapacity * sizeof(long));
        int* newKeys = realloc(manager->keys, newCapacity * sizeof(int));
        Record** newRecords = realloc(manager->records, newCapacity * sizeof(Record*));

        if (newOffsets == NULL || newKeys == NULL || newRecords == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1;  // Allocation failed.
        }

        manager->capacity = newCapacity;
        manager->offsets = newOffsets;
        manager->keys = newKeys;
        manager->records = newRecords;
    }

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -1;  // Allocation failed.
    }

    record->value = value;
    manager->offsets[manager->count] = offset;
    manager->keys[manager->count] = key;
    manager->records[manager->count++] = record;

    pthread_mutex_unlock(&manager->lock);
    return 0;  // Success.
}
