    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    item->type = type;
    switch (type) {
        case 0: // int
            item->data.i = *((int*)value);
            break;
        case 1: // double
            item->data.d = *((double*)value);
            break;
        case 2: // string
            item->data.s = strdup((char*)value);
            if (!item->data.s) {
                printf("Memory allocation failed\n");
                free(item);
                return NULL;
            }
            break;
        default:
            printf("Invalid type\n");
            free(item);
            return NULL;
    }

    pthread_mutex_unlock(&lock); // Unlock after allocation

    return item;
}
