const fs = require('fs').promises;
const crypto = require('crypto');
const path = require('path');

async function processFiles(directory) {
    let summary = { totalLines: 0, emptyLines: 0 };

    try {
        const files = await fs.readdir(directory);

        for (let file of files) {
            const content = await fs.readFile(path.join(directory, file), 'utf8');

            summary.totalLines += content.split('\n').length;
            summary.emptyLines += content.split('\n').filter(line => line === '').length;
        }
    } catch (err) {
        console.error("Error processing files:", err);
    }

    return summary;
}

async function initializeCipher(password, salt = crypto.randomBytes(16)) {
    let key = crypto.pbkdf2Sync(password, salt, 100000, 32, 'sha512'); // Adhere to best practices for key derivation

    try {
        const iv = crypto.randomBytes(16); // Secure random number generator for IV creation

        return crypto.createCipheriv('aes-256-cbc', key, iv);
    } catch (err) {
        console.error("Error initializing cipher:", err);
    }
}
