    return 0;
}

void update_theme_cache(ThemeCache *cache, char *name) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->count; ++i) {
        if (!strcmp(cache->themes[i]->name, name)) {
            cache->themes[i]->access_count++;
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }

    if (cache->count >= cache->max_size) {
        log_error("Theme cache is full.", -3);
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    Theme *theme = malloc(sizeof(Theme));
    theme->name = malloc(strlen(name) + 1);
    strcpy(theme->name, name);
    theme->access_count = 1;

    cache->themes = realloc(cache->themes, (cache->count + 1) * sizeof(Theme *));
    cache->themes[cache->count++] = theme;

    pthread_mutex_unlock(&cache->lock);
}

void log_error(char *message, int error_code) {
