        return;
    }

    for (size_t i = 0; i < manager->recordCount; ++i) {
        freeRecord(manager->records[i]);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

Record* createRandomRecord() {
