        return NULL;
    }
    for (size_t i = 0; i < 9; ++i) {
        record->string[i] = 'a' + rand() % 26;  // Generate a random lowercase letter.
    }
    record->string[9] = '\0';

    return record;
}

void addRecord(DataManager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->recordCount >= manager->maxRecords) {
        manager->errorCallback("Maximum records limit exceeded.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Record* record = createRandomRecord();
    if (record == NULL) {
        manager->errorCallback("Failed to allocate memory for a new record.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->records[manager->recordCount] = record;
    ++manager->recordCount;

    pthread_mutex_unlock(&manager->lock);
}
