#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <pthread.h>

typedef struct {
    int key;
    char* identifier;
} Record;

Record* init_store(int min, int max, unsigned char* seed, size_t len) {
    if (max <= min || len < 16) return NULL; // Invalid range or seed length too short

    RAND_seed(seed, len); // Seed the random number generator

    Record* store = malloc((max - min + 1) * sizeof(Record));
    if (store == NULL) return NULL; // Out of memory

    for (int i = 0; i <= max - min; ++i) {
        store[i].key = min + i;

        unsigned char rand_str[16]; // Generate a random string identifier
        RAND_bytes(rand_str, sizeof(rand_str));
        store[i].identifier = malloc(2 * sizeof(rand_str) + 1);
        if (store[i].identifier == NULL) return NULL; // Out of memory

        for (size_t j = 0; j < sizeof(rand_str); ++j) {
            sprintf(&store[i].identifier[2 * j], "%02x", rand_str[j]);
        }
    }

    return store;
}
```
