    size_t used;
    size_t size;
    pthread_mutex_t lock; // For thread safety
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (NR_DL_FRAME_TRANSPORT_CONTEXT*)malloc(initialSize * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL); // Initialize the mutex
}

void insertDynamicArray(DynamicArray *a, NR_DL_FRAME_TRANSPORT_CONTEXT element) {
    pthread_mutex_lock(&a->lock); // Lock for thread safety

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (NR_DL_FRAME_TRANSPORT_CONTEXT*)realloc(a->array, a->size * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    }

    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock); // Unlock after operation
}

