['This is quite an extensive task that requires a lot of code and detailed design. Here's a simplified example of how you might start implementing such a system in C using POSIX threads (pthreads). This doesn't include all the features you requested, but it should give you a good starting point:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct Task {
    int id;
    void (*task_func)(void *);
    void *arg;
} Task;

typedef struct WorkerPool {
    pthread_t *workers;
    size_t worker_count;
    Task **queue;
    size_t queue_size;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} WorkerPool;

void *worker(void *arg) {
    WorkerPool *pool = (WorkerPool *)arg;
    Task *task;

    while (1) {
        pthread_mutex_lock(&pool->lock);
        while (pool->head == pool->tail) {  // Queue is empty
            pthread_cond_wait(&pool->cond, &pool->lock);
        }

        task = pool->queue[pool->head];
        pool->head = (pool->head + 1) % pool->queue_size;

        pthread_mutex_unlock(&pool->lock);

        // Execute the task
        task->task_func(task->arg);
    }
}

WorkerPool *create_worker_pool(size_t worker_count, size_t queue_size) {
    WorkerPool *pool = malloc(sizeof(WorkerPool));
    pool->workers = calloc(worker_count, sizeof(pthread_t));
    pool->queue = calloc(queue_size, sizeof(Task *));
    pool->head = 0;
    pool->tail = 0;
    pool->worker_count = worker_count;
    pool->queue_size = queue_size;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);

    for (int i = 0; i < worker_count; ++i) {
        pthread_create(&pool->workers[i], NULL, worker, pool);
    }

    return pool;
}

void submit_task(WorkerPool *pool, Task *task) {
    pthread_mutex_lock(&pool->lock);

    while ((pool->tail + 1) % pool->queue_size == pool->head) {  // Queue is full
        printf("Queue is full. Retrying...\n");
        sleep(1);
    }

    pool->queue[pool->tail] = task;
    pool->tail = (pool->tail + 1) % pool->queue_size;

    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}
```
This is a very basic example and doesn't include many of the features you requested, such as task dependencies or integration with external services. It also lacks error handling and cleanup code for simplicity. You would need to add these in a real implementation. 

For more complex systems, consider using a library like OpenMP or Intel TBB that provides higher-level abstractions for parallelism and concurrency. For managing tasks and dependencies, you might want to look into task schedulers like Luvit's cosmo or Facebook's Borg. For logging, consider using a mature logging framework like Google's glog or Apache log4cxx.
']

