        memmove(&array[index], &array[index + 1], (size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array = realloc(array, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&lock);
    } else {
        // Handle out of bounds error here
    }
}

void cleanup() {
    free(array);
    array = NULL;
    size = 0;
    pthread_mutex_destroy(&lock);
}
```
