// Function to calculate mean, median and standard deviation
double calculate_mean(record* data, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; ++i) {
        sum += data[i].value;
    }
    return sum / size;
}

// Function to calculate median
double calculate_median(record* data, int size) {
    // Sort the array first
    qsort(data, size, sizeof(record), compare);

    if (size % 2 == 0)
        return (data[size / 2 - 1].value + data[size / 2].value) / 2.0;
    else
        return data[size / 2].value;
}

// Function to calculate standard deviation
double calculate_stddev(record* data, int size, double mean) {
    double sum = 0.0;
    for (int i = 0; i < size; ++i) {
        sum += pow(data[i].value - mean, 2);
    }
    return sqrt(sum / size);
}

// Function to export data in CSV or JSON format
