#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} Element;

typedef struct {
    int RNTI;
    int CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxInfoTag;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    Element* elements;
    size_t capacity;
    size_t count;
} DynamicArray;

DynamicArray createArray(size_t initialCapacity) {
    DynamicArray array;
    array.capacity = initialCapacity;
    array.count = 0;
    array.elements = (Element*)malloc(initialCapacity * sizeof(Element));
    return array;
}

void addElement(DynamicArray* array, Element element) {
    if (array->count == array->capacity) {
        // Double the capacity when full
        array->capacity *= 2;
        array->elements = realloc(array->elements, array->capacity * sizeof(Element));
    }
    array->elements[array->count++] = element;
}

void removeElement(DynamicArray* array, size_t index) {
    if (index >= array->count) return;

    // Shift elements to fill the gap
    for (size_t i = index; i < array->count - 1; ++i) {
        array->elements[i] = array->elements[i + 1];
    }
    --array->count;
}

void updateElement(DynamicArray* array, size_t index, Element newValue) {
    if (index >= array->count) return;

    array->elements[index] = newValue;
}

void freeArray(DynamicArray* array) {
    free(array->elements);
    array->capacity = 0;
    array->count = 0;
}
```
