#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long* offset;
    int key;
    pthread_mutex_t refCountMutex;
    int refCount;
} Record;

long* allocateOffsets(int n) {
    // Allocate memory for 'n' long integers and initialize to zero.
    long* offsets = calloc(n, sizeof(long));
    if (offsets == NULL) {
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* allocateKeys(int m) {
    // Allocate memory for 'm' int keys and initialize randomly.
    srand(time(NULL));
    int* keys = calloc(m, sizeof(int));
    if (keys == NULL) {
        exit(EXIT_FAILURE);
    }

    // Avoid duplicates to prevent collision with existing keys in the system.
    for (int i = 0; i < m; ++i) {
        int key;
        do {
            key = rand() % 2001 - 1000;
        } while (contains(keys, key, i));

        keys[i] = key;
    }

    return keys;
}

Record* allocateRecords(long* offsets, int* keys, int n, int m) {
    // Allocate memory for an array of Record structures.
    Record* records = calloc(n, sizeof(Record));
    if (records == NULL) {
        exit(EXIT_FAILURE);
    }

    // Initialize each record with a pointer to one of the allocated long offsets, 
    // an integer key from the int keys array, and a reference count.
    for (int i = 0; i < n; ++i) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i % m];
        pthread_mutex_init(&records[i].refCountMutex, NULL);
        records[i].refCount = 0;
    }

    return records;
}

void addRecord(Record* records, int n, long offset, int key) {
    // Add a record to the Record array. Ensure that no two threads can 
    // add a record with the same key at the same time.
    for (int i = 0; i < n; ++i) {
        if (records[i].key == key) {
            pthread_mutex_lock(&records[i].refCountMutex);
            ++records[i].refCount;
            pthread_mutex_unlock(&records[i].refCountMutex);
            return;
        }
    }
}

void incrementRefCount(Record* records, int n, int key) {
    // Increment the reference count for a specific record by its key.
    for (int i = 0; i < n; ++i) {
        if (records[i].key == key) {
            pthread_mutex_lock(&records[i].refCountMutex);
            ++records[i].refCount;
            pthread_mutex_unlock(&records[i].refCountMutex);
            return;
        }
    }
}
