typedef struct Node {
    Value* value;
    struct Node* next;
} Node;

// Define the data structure
typedef struct DataStructure {
    Node** nodes;
    pthread_mutex_t lock;
    int threshold;
    int count;
} DataStructure;

DataStructure* createDataStructure(int size, int threshold) {
    // Initialize the data structure
    DataStructure* ds = malloc(sizeof(DataStructure));
    ds->nodes = calloc(size, sizeof(Node*));
    pthread_mutex_init(&ds->lock, NULL);
    ds->threshold = threshold;
    ds->count = 0;

    return ds;
}

void insertValue(DataStructure* ds, int nodeIndex, Value* value) {
    // Lock the data structure to ensure thread safety
    pthread_mutex_lock(&ds->lock);

    // Check if we've exceeded the threshold
    if (ds->count >= ds->threshold) {
        // If so, remove the least recently used value from the linked list
        Node* node = ds->nodes[nodeIndex];
        while (node && node->next) {
            node = node->next;
        }

        if (node) {
            free(node->value);
            free(node);
            ds->count--;
        }
    }

    // Insert the new value at the beginning of the linked list
    Node* newNode = malloc(sizeof(Node));
    newNode->value = value;
    newNode->next = ds->nodes[nodeIndex];
    ds->nodes[nodeIndex] = newNode;

    // Unlock the data structure
    pthread_mutex_unlock(&ds->lock);
}

void iterateValues(DataStructure* ds, int nodeIndex) {
