["Implementing such a complex system from scratch would be quite extensive and beyond the scope of this platform. However, I can give you an outline of how you might approach creating such a function. 

```cpp
#include <vector>
#include <algorithm>
#include <future>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <thread>

struct Point {
    // Define your point structure here
};

class KDTreeNode {
public:
    KDTreeNode(const std::vector<Point>& points, int depth = 0) : left(nullptr), right(nullptr) {
        if (points.size() == 0) return;

        // Select axis based on depth so as to cycle through all axes.
        int k = points[0].dimensions();
        auto mid_point = points.begin() + points.size() / 2;

        std::nth_element(points.begin(), mid_point, points.end(), [&](Point a, Point b) {
            return a[depth % k] < b[depth % k];
        });

        point = *mid_point;
        left = new KDTreeNode(std::vector<Point>(points.begin(), mid_point), depth + 1);
        right = new KDTreeNode(std::vector<Point>(mid_point + 1, points.end()), depth + 1);
    }

    ~KDTreeNode() {
        delete left;
        delete right;
    }

private:
    Point point;
    KDTreeNode* left;
    KDTreeNode* right;
};

class KDTree {
public:
    void insert(const Point& p) {
        std::lock_guard<std::mutex> lock(m);

        points.push_back(p);
        needsUpdate = true;
    }

    void update() {
        if (!needsUpdate) return;

        delete root;
        root = new KDTreeNode(points);

        std::lock_guard<std::mutex> lock(m);
        needsUpdate = false;
    }

private:
    std::vector<Point> points;
    std::atomic<bool> needsUpdate{false};
    KDTreeNode* root;
    std::mutex m;
};
```
