typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    atomic_int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add(NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        exit(-1);
    }

    newNode->data = value;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeAll() {
    pthread_mutex_lock(&lock);

    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}

void verifyAndPrint() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        // Verify and print data
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", 
               current->data.RX_UE_INFORMATION_TAG, 
               current->data.RNTI, 
               atomic_load(&current->data.CRC_INDICATION_REL8_TAG));

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
```
