['Here's a Java method to compute MD5 hashes of strings with size constraints and logging processing time:

```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

public class HashProcessor {
    private static final Log log = LogFactory.getLog(HashProcessor.class);

    public List<String> processStrings(List<String> strings, int maxSize) {
        long startTime = System.currentTimeMillis();

        List<String> hashes = new ArrayList<>();
        List<String> invalidStrings = new ArrayList<>();

        for (String string : strings) {
            if (string.getBytes(StandardCharsets.UTF_8).length > maxSize) {
                log.error("Invalid string: " + string);
                invalidStrings.add(string);
                continue;
            }

            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(string.getBytes(StandardCharsets.UTF_8));

                StringBuilder sb = new StringBuilder();
                for (byte b : hashBytes) {
                    sb.append(String.format("%02x", b & 0xff));
                }

                hashes.add(sb.toString());
            } catch (Exception e) {
                log.error("Failed to process string: " + string, e);
            }
        }

        long endTime = System.currentTimeMillis();
        log.info("Processing time: " + (endTime - startTime) + " ms");

        if (!invalidStrings.isEmpty()) {
            return Collections.emptyList();
        }

        return hashes;
    }
}
```

