    int key;
    char* string;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_records = 0;
static size_t max_string_size = 0;

void error_callback(const char* message) {
    fprintf(stderr, "%s\n", message);
}

typedef void (*error_callback_func)(const char*);

record* allocate_and_initialize_records(size_t num_records, size_t string_length, int key_range, error_callback_func callback) {
    pthread_mutex_lock(&lock);

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        callback("Memory allocation failed");
        return NULL;
    }

    total_records += num_records;
    max_string_size = string_length > max_string_size ? string_length : max_string_size;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % key_range;

        records[i].string = malloc(string_length + 1);
        if (!records[i].string) {
            callback("Memory allocation failed");
            free(records);
            return NULL;
        }

        for (size_t j = 0; j < string_length; ++j) {
            records[i].string[j] = 'A' + rand() % 26; // Generate random alphanumeric character
        }
        records[i].string[string_length] = '\0';
    }

    pthread_mutex_unlock(&lock);

    return records;
}

void free_records(record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].string);
    }

    pthread_mutex_lock(&lock);
    total_records -= num_records;
    pthread_mutex_unlock(&lock);

    free(records);
}
```
