    for (int i = 0; i < num; ++i) {
        records[i].offset = get_offset(); // Get offset from external data source
        if (records[i].offset > MAX_SIZE) { // Check against predefined maximum size limit
            fprintf(logfile, "Offset exceeds max size\n");
            pthread_mutex_unlock(&lock); // Unlock mutex before returning
            free(records);
            return NULL;
        }

        records[i].key = get_key(); // Get key from external data source
    }

    fprintf(logfile, "Allocation succeeded\n");
    pthread_mutex_unlock(&lock); // Unlock mutex after successful allocation
    return records;
}
