    pthread_mutex_lock(&mutex);

    directory->logRecords = realloc(directory->logRecords, (directory->numLogRecords + 1) * sizeof(LogRecord));
    if (directory->logRecords == NULL) {
        fprintf(stderr, "Failed to allocate memory for log records\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    directory->logRecords[directory->numLogRecords] = record;
    directory->numLogRecords++;

    pthread_mutex_unlock(&mutex);
}

void freeDirectory(FileNode* directory) {
