    char* id;
    void* value;
    int type; // 0: integer, 1: float, 2: boolean, 3: string array
    struct ConfigNode *left, *right;
} ConfigNode;

ConfigNode* new_node(char* id, void* value, int type) {
    ConfigNode* node = (ConfigNode*) malloc(sizeof(ConfigNode));
    if (!node) return NULL; // handle allocation failure

    node->id = strdup(id);
    if (!node->id) {
        free(node);
        return NULL; // handle allocation failure
    }

    node->value = value;
    node->type = type;
    node->left = node->right = NULL;
    return node;
}

void insert_node(ConfigNode** root, char* id, void* value, int type) {
    if (*root == NULL) {
        *root = new_node(id, value, type);
        return;
    }

    int cmp = strcmp((*root)->id, id);
    if (cmp < 0) {
        insert_node(&(*root)->right, id, value, type);
    } else if (cmp > 0) {
        insert_node(&(*root)->left, id, value, type);
    }
}

void delete_tree(ConfigNode* root) {
    if (root != NULL) {
        delete_tree(root->left);
        delete_tree(root->right);
        free(root->id);
        free(root->value);
        free(root);
    }
}
```
