typedef struct {
    int latency;
    float packet_loss;
    double throughput;
} NetworkMetrics;

typedef struct Node {
    NetworkMetrics metrics;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;
int total_metrics = 0;
int validation_errors = 0;
int cache_updates = 0;

void addMetric(NetworkMetrics metrics) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    newNode->metrics = metrics;
    newNode->next = head;
    head = newNode;

    total_metrics++;
    cache_updates++;

    pthread_mutex_unlock(&lock);
}

NetworkMetrics getMetric() {
    pthread_mutex_lock(&lock);

    if(head == NULL) {
        printf("Cache is empty.\n");
        return (NetworkMetrics){0, 0.0f, 0.0};
    }

    NetworkMetrics metrics = head->metrics;
    Node* temp = head;
    head = head->next;
    free(temp);

    pthread_mutex_unlock(&lock);

    return metrics;
}

void validateMetric(NetworkMetrics* metrics) {
    if(metrics->latency < 0 || metrics->packet_loss < 0.0f || metrics->throughput < 0.0) {
        validation_errors++;
        printf("Validation error: Invalid metric.\n");
    }
}

void* collectMetricsThread(void* arg) {
    NetworkMetrics metrics = *((NetworkMetrics*)arg);

    validateMetric(&metrics);
    addMetric(metrics);

    return NULL;
}
```
