#include <time.h>

typedef struct {
    int key;
    float weight;
    long offset;
    char* string;
} record;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    void** cache;
} allocator;

allocator createAllocator(size_t initialCapacity) {
    allocator a = { PTHREAD_MUTEX_INITIALIZER, initialCapacity, 0, malloc(initialCapacity * sizeof(void*)) };
    return a;
}

void* allocate(allocator* a, size_t size) {
    pthread_mutex_lock(&a->mutex);

    if (a->size == a->capacity) {
        a->capacity *= 2;
        a->cache = realloc(a->cache, a->capacity * sizeof(void*));
    }

    void* memory = malloc(size);
    a->cache[a->size++] = memory;

    pthread_mutex_unlock(&a->mutex);

    return memory;
}

void deallocateAllocator(allocator* a) {
    for (size_t i = 0; i < a->size; ++i) {
        free(a->cache[i]);
    }

    free(a->cache);
}

record* createRecords(allocator* a, size_t count, int keyRange, size_t stringLength) {
    srand(time(NULL));

    record* records = allocate(a, count * sizeof(record));

    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % keyRange;
        records[i].weight = (float)rand() / RAND_MAX;
        records[i].offset = rand();

        records[i].string = allocate(a, stringLength + 1);
