// Define a lock-free linked list node
typedef struct Node {
    record_t data;
    struct Node* next;
} Node;

// Define the collection as an atomic pointer to the head of the linked list
atomic_intptr_t collection = ATOMIC_VAR_INIT(0);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addRecord(record_t record) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle allocation failure, e.g., by retrying with backoff
        return;
    }

    newNode->data = record;
    newNode->next = NULL;

    pthread_mutex_lock(&mutex);
    Node* head = (Node*)atomic_load(&collection);
    if (head == NULL) {
        atomic_store(&collection, (intptr_t)newNode);
    } else {
        while(1) {
            Node* next = head->next;
            if (next == NULL) {
                if (atomic_compare_exchange_weak(&head->next, &next, newNode)) break;
            } else {
                head = next;
            }
        }
    }
    pthread_mutex_unlock(&mutex);
}
```
