```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t maxSize;
    size_t currentSize;
} List;

List list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0};

Record createRecord(long offset, int key, int minValue, int maxValue) {
    Record record;
    record.offset = offset;
    record.key = key;
    record.value = rand() % (maxValue - minValue + 1) + minValue;
    return record;
}

void insertRecord(Record record) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        // Handle allocation failure
        return;
    }

    pthread_mutex_lock(&list.lock);
    if (list.currentSize >= list.maxSize) {
        // Handle list full error
        pthread_mutex_unlock(&list.lock);
        free(node);
        return;
    }

    node->record = record;
    node->next = list.head;
    list.head = node;
    list.currentSize++;
    pthread_mutex_unlock(&list.lock);
}

Record* getRecord(int key) {
    pthread_mutex_lock(&list.lock);
    Node* currentNode = list.head;
    while (currentNode != NULL) {
        if (currentNode->record.key == key) {
            pthread_mutex_unlock(&list.lock);
            return &(currentNode->record);
        }
        currentNode = currentNode->next;
    }

    pthread_mutex_unlock(&list.lock);
    // Handle record not found error
    return NULL;
}
```
