    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int size;
    int maxSize;
    NFAPI_CRC_INDICATION_PDU_T **list;
} List;

List *createList(int maxSize) {
    List *list = (List *)malloc(sizeof(List));
    if (!list) return NULL;

    list->maxSize = maxSize;
    list->size = 0;
    list->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * maxSize);
    if (!list->list) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int addToList(List *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    if (!list || !item) return -1;

    pthread_mutex_lock(&list->lock);
    if (list->size >= list->maxSize) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    list->list[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void destroyList(List *list) {
    if (!list) return;

    for (int i = 0; i < list->size; ++i) {
        free(list->list[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list->list);
    free(list);
}
```
