} CACHE_RECORD;

typedef struct {
    pthread_mutex_t lock;
    FILE_SYSTEM_ENTRY* file_system_entries;
    CACHE_RECORD* cache_records;
    int fs_size;
    int cr_size;
} DataManager;

DataManager* init_data_manager() {
    DataManager* dm = malloc(sizeof(DataManager));
    pthread_mutex_init(&dm->lock, NULL);
    dm->fs_size = 0;
    dm->cr_size = 0;
    return dm;
}

void add_file_system_entry(DataManager* dm, char* path, long size, int access_control) {
    pthread_mutex_lock(&dm->lock);
    dm->fs_size++;
    dm->file_system_entries = realloc(dm->file_system_entries, sizeof(FILE_SYSTEM_ENTRY) * dm->fs_size);
    FILE_SYSTEM_ENTRY* entry = &dm->file_system_entries[dm->fs_size - 1];
    entry->path = strdup(path);
    entry->size = size;
    entry->access_control = access_control;
    pthread_mutex_unlock(&dm->lock);
}

void add_cache_record(DataManager* dm, int status, int key, long offset) {
    pthread_mutex_lock(&dm->lock);
    dm->cr_size++;
    dm->cache_records = realloc(dm->cache_records, sizeof(CACHE_RECORD) * dm->cr_size);
    CACHE_RECORD* record = &dm->cache_records[dm->cr_size - 1];
    record->status = status;
    record->key = malloc(sizeof(int));
    *record->key = key;
    record->offset = malloc(sizeof(long));
    *record->offset = offset;
    pthread_mutex_unlock(&dm->lock);
}

CACHE_RECORD* get_cache_record(DataManager* dm, int key) {
    if (dm->cr_size == 0) return NULL;

    pthread_mutex_lock(&dm->lock);
    int low = 0;
    int high = dm->cr_size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (*dm->cache_records[mid].key == key) {
            pthread_mutex_unlock(&dm->lock);
            return &dm->cache_records[mid];
        } else if (*dm->cache_records[mid].key < key) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    pthread_mutex_unlock(&dm->lock);

    return NULL;
}

void cleanup(DataManager* dm) {
    for (int i = 0; i < dm->fs_size; ++i) {
        free(dm->file_system_entries[i].path);
    }

    for (int i = 0; i < dm->cr_size; ++i) {
        free(dm->cache_records[i].key);
        free(dm->cache_records[i].offset);
    }

    free(dm->file_system_entries);
    free(dm->cache_records);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}
```
