Profile* allocate_profiles(int max_profiles) {
    // Check if system resources are available for allocation
    void *ptr = malloc(max_profiles * sizeof(Profile));
    if (ptr == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    return ptr;
}

void read_csv(const char* filename, Profile* profiles, int max_profiles) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        exit(EXIT_FAILURE);
    }

    char line[1024];
    int i = 0;
    while (fgets(line, sizeof(line), file) && i < max_profiles) {
        // Parse CSV line into profile fields
        if (sscanf(line, "%d,%d,%lf", &profiles[i].status, &profiles[i].age, &profiles[i].balance) != 3) {
            fprintf(stderr, "Malformed entry in CSV file\n");
            exit(EXIT_FAILURE);
        }
        ++i;
    }

    if (ferror(file)) {
        perror("Failed to read from file");
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

int main() {
    int max_profiles = 10; // Example value, should be user-specified
    Profile* profiles = allocate_profiles(max_profiles);

    const char* filename = "users.csv"; // Example CSV file
    read_csv(filename, profiles, max_profiles);

