typedef struct Job {
    time_t submissionTime;
    int priority;
    char* status;
} Job;

typedef struct JobList {
    pthread_mutex_t lock;
    Job** jobs;
    size_t capacity;
    size_t size;
} JobList;

JobList jobList = { PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0 };

void* addJob(void* arg) {
    Job* job = (Job*)arg;

    pthread_mutex_lock(&jobList.lock);

    if (jobList.size == jobList.capacity) {
        size_t newCapacity = jobList.capacity == 0 ? 1 : jobList.capacity * 2;
        Job** newJobs = realloc(jobList.jobs, sizeof(Job*) * newCapacity);

        if (newJobs == NULL) {
            fprintf(stderr, "Failed to allocate memory for jobs\n");
            pthread_mutex_unlock(&jobList.lock);
            return NULL;
        }

        jobList.jobs = newJobs;
        jobList.capacity = newCapacity;
    }

    jobList.jobs[jobList.size++] = job;

    pthread_mutex_unlock(&jobList.lock);

    return NULL;
}
