dynamic_data_structure* create_dynamic_data_structure(size_t size, int min, int max) {
    srand((unsigned int)time(NULL));

    dynamic_data_structure* dds = malloc(sizeof(dynamic_data_structure));
    if (dds == NULL) return NULL;

    dds->offsets = calloc(size, sizeof(long));
    dds->keys = malloc(size * sizeof(int));
    dds->records = malloc(size * sizeof(record*));
    dds->key_references = calloc(max - min + 1, sizeof(int));

    if (dds->offsets == NULL || dds->keys == NULL || dds->records == NULL || dds->key_references == NULL) {
        free_dynamic_data_structure(dds);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        int key = rand() % (max - min + 1) + min;
        ++dds->key_references[key - min];
        dds->keys[i] = key;
        dds->records[i] = malloc(sizeof(record));
        if (dds->records[i] == NULL) {
            free_dynamic_data_structure(dds);
            return NULL;
        }
        dds->records[i]->value = rand() % (max - min + 1) + min;
    }

    dds->size = size;
    return dds;
}

void free_dynamic_data_structure(dynamic_data_structure* dds) {
    if (dds == NULL) return;
    for (size_t i = 0; i < dds->size; ++i) {
        free(dds->records[i]);
    }
    free(dds->offsets);
    free(dds->keys);
    free(dds->records);
    free(dds->key_references);
    free(dds);
}
