    SERVICE_CONFIG_CONTEXT(int serviceTypeId, bool optimizeResourceAllocation) : 
        serviceTypeId_(serviceTypeId), 
        optimizeResourceAllocation_(optimizeResourceAllocation) {}
    ~SERVICE_CONFIG_CONTEXT() {
        for (auto& block : parameterBlocks_) {
            delete block.offset;
        }
