    void addParameterBlock(int value, long* offset) {
        std::lock_guard<std::mutex> lock(mtx_);
        PARAMETER_BLOCK newBlock{value, offset};
        parameterBlocks_.push_back(newBlock);
        // Sort the blocks by value to enable binary search.
        std::sort(parameterBlocks_.begin(), parameterBlocks_.end(), 
            [](const PARAMETER_BLOCK& a, const PARAMETER_BLOCK& b) { return a.value < b.value; });
    }

    PARAMETER_BLOCK* getParameterBlock(int key) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = std::lower_bound(parameterBlocks_.begin(), parameterBlocks_.end(), key, 
            [](const PARAMETER_BLOCK& block, int value) { return block.value < value; });
        if (it != parameterBlocks_.end() && it->value == key) {
            return &(*it);
        } else {
            return nullptr; // Key not found.
        }
    }
private:
    int serviceTypeId_;
    bool optimizeResourceAllocation_;
    std::vector<PARAMETER_BLOCK> parameterBlocks_;
    std::mutex mtx_;
};
