#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <string.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t* refCounts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int (*compare)(const void*, const void*);
} DataStructure;

DataStructure* createDataStructure(size_t initialCapacity) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(initialCapacity, sizeof(long));
    ds->keys = calloc(initialCapacity, sizeof(int));
    ds->records = malloc(initialCapacity * sizeof(record*));
    ds->refCounts = calloc(initialCapacity, sizeof(size_t));

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL || ds->refCounts == NULL) {
        freeDataStructure(ds);
        return NULL;
    }

    ds->capacity = initialCapacity;
    ds->count = 0;
    pthread_mutex_init(&ds->lock, NULL);
    ds->compare = NULL;

    return ds;
}

void freeDataStructure(DataStructure* ds) {
    if (ds == NULL) return;

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->refCounts);
    pthread_mutex_destroy(&ds->lock);

    free(ds);
}

int insertRecord(DataStructure* ds, int key, int value) {
    assert(ds != NULL);

    if (ds->count >= ds->capacity) return -1; // limit reached

    pthread_mutex_lock(&ds->lock);

    size_t index = ds->count++;
    ds->keys[index] = key;
    ds->refCounts[index] = 1;

    record* r = malloc(sizeof(record));
    if (r == NULL) {
        --ds->count;
        pthread_mutex_unlock(&ds->lock);
        return -2; // out of memory
    }

    ds->records[index] = r;
    ds->records[index]->value = value;

    pthread_mutex_unlock(&ds->lock);

    return 0; // success
}
```
This code provides a basic structure for managing dynamic data structures with multiple components. It includes functions to create and free the data structure, as well as an insert function that checks if there is space in the data structure before adding a new record. The `insertRecord` function uses a mutex lock to ensure thread safety when modifying the data structure concurrently.
