}

void initializeOffsetArray(MetaData* metaData, int nOffsets) {
    srand((unsigned int)time(NULL));
    long size = calculateSize(nOffsets);
    metaData->offsetArray = malloc(size);
    for (int i = 0; i < nOffsets; ++i) {
        metaData->offsetArray[i] = BASE_OFFSET + i;
    }
}

void initializeKeyArray(MetaData* metaData, int nOffsets) {
    srand((unsigned int)time(NULL));
    metaData->keyArray = malloc(nOffsets * sizeof(int));
    for (int i = 0; i < nOffsets; ++i) {
        double sqrtValue = sqrt((double)metaData->offsetArray[i]);
        metaData->keyArray[i] = (int)sqrtValue; // round down to nearest integer
    }
}

void initializeRecordArray(MetaData* metaData, int nRecords, int minValue, int maxValue) {
    srand((unsigned int)time(NULL));
    metaData->recordArray = malloc(nRecords * sizeof(Record));
    for (int i = 0; i < nRecords; ++i) {
        metaData->recordArray[i].key = metaData->keyArray[i % metaData->nOffsets];
        metaData->recordArray[i].value = rand() % (maxValue - minValue + 1) + minValue; // random number between min and max inclusive
    }
}

void calculateStats(MetaData* metaData, Stats* stats) {
    if (metaData->nRecords == 0) return;

    int sum = 0, minVal = INT_MAX, maxVal = INT_MIN;
    for (int i = 0; i < metaData->nRecords; ++i) {
        int value = metaData->recordArray[i].value;
        sum += value;
        if (value < minVal) minVal = value;
        if (value > maxVal) maxVal = value;
    }

    stats->avgValue = (double)sum / metaData->nRecords;
    stats->minValue = minVal;
    stats->maxValue = maxVal;
}
