import java.util.logging.Logger;

public class DataManager {
    private static final Logger logger = Logger.getLogger(DataManager.class.getName());
    private Map<String, Double> dataStore = new ConcurrentHashMap<>();
    private CloseableHttpClient httpclient = HttpClients.createDefault();

    public void addEntry(String key, double value) {
        if (dataStore.size() >= Integer.MAX_VALUE) {
            logger.severe("Memory limit exceeded!");
            return;
        }

        dataStore.put(key, value);
    }

    public void sendPostRequest(String url, String jsonPayload) throws IOException {
        HttpPost httpPost = new HttpPost(url);
        StringEntity entity = new StringEntity(jsonPayload);
        httpPost.setEntity(entity);
        httpPost.setHeader("Accept", "application/json");
        httpPost.setHeader("Content-type", "application/json");

        CloseableHttpResponse response = httpclient.execute(httpPost);
        try {
            logger.info(response.getStatusLine().toString());
            EntityUtils.consume(response.getEntity());
        } finally {
            response.close();
        }
    }

    public static void main(String[] args) throws IOException {
        DataManager dataManager = new DataManager();

        for (int i = 0; i < 1000; i++) {
            String key = "key" + i;
            double value = Math.random() * 100;

            dataManager.addEntry(key, value);
            dataManager.sendPostRequest("http://example.com", "{\"" + key + "\":" + value + "}");
