        return NULL;
    }

    Packet* packet = &packet_pool[num_packets++];
    pthread_mutex_unlock(&pool_lock);

    log_message("Packet allocated.");
    return packet;
}

void initialize_packet(Packet* packet, const char* source_ip, const char* dest_ip, int protocol, size_t payload_size) {
    if (packet == NULL) {
        log_message("Error: Attempted to initialize null packet.");
