    snprintf(packet->source_ip, sizeof(packet->source_ip), "%s", source_ip);
    snprintf(packet->dest_ip, sizeof(packet->dest_ip), "%s", dest_ip);
    packet->protocol = protocol;
    packet->payload_size = payload_size;
