#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* initialize_records(int n, long max_mem, int min_records) {
    // Calculate the size of a single record in bytes
    const size_t recordSize = sizeof(Record);

    // If the total memory required exceeds the maximum allowed, adjust 'n' to fit within the constraint
    while (recordSize * n > max_mem && n > min_records) {
        n--;
    }

    // Allocate memory for an array of Record structures
    Record* records = malloc(recordSize * n);
    if (!records) {
        return NULL;  // Return NULL on allocation failure
    }

    // Initialize each record with a random key and value between -1000 and 1000
    srand((unsigned int)time(NULL));
    for (int i = 0; i < n; ++i) {
