    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->max_mem = max_mem;
    pool->used_mem = 0;
    pool->num_records = 0;
    pool->min_records = min_records;

    return pool;
