        free(record);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->records[pool->num_records] = *record;
    pool->used_mem += sizeof(Record);
    pool->num_records++;

    pthread_mutex_unlock(&pool->lock);
    return record;
}

