typedef struct {
    long offset;
    int key;
} record;

int initialize(long max_memory, int num_records, long min_offset, long max_offset, 
               int min_key, int max_key, record **records) {

    if (num_records <= 0 || max_memory < sizeof(record) * num_records || 
        min_offset > max_offset || min_key > max_key) {
        return -1; // Invalid input parameters
    }

    srand(time(NULL));

    *records = malloc(sizeof(record) * num_records);
    if (*records == NULL) {
