typedef struct {
    int id;
    float weight;
    char* key;
} Record;

// Thread-local storage to manage records independently
__thread Record** localRecords = NULL;
__thread size_t recordCount = 0;
__thread size_t maxRecordCount = 1024;  // Initial maximum number of records per thread

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for a new record
Record* createRecord(int id, float weight, const char* key) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->id = id;
    record->weight = weight;
    record->key = strdup(key);  // Dynamically allocate memory for the key string

    return record;
}

// Function to add a new record to local storage
void addRecord(Record* record) {
    pthread_mutex_lock(&mutex);

    if (recordCount >= maxRecordCount) {
        // Resize the records array when it's full
        maxRecordCount *= 2;  // Double the maximum number of records per thread
        localRecords = realloc(localRecords, maxRecordCount * sizeof(Record*));
    }

    localRecords[recordCount++] = record;

    pthread_mutex_unlock(&mutex);
}

// Function to free memory of a record and its key string
void destroyRecord(Record* record) {
    free(record->key);  // Free the dynamically allocated key string
    free(record);  // Free the record structure
}

// Function to handle dynamic changes in resource availability
void adjustMaxRecords() {
    pthread_mutex_lock(&mutex);

    size_t availableMemory = getAvailableSystemMemory();  // Assume this function exists
    maxRecordCount = (availableMemory / sizeof(Record)) * 0.8;  // Use 80% of available memory for records

    pthread_mutex_unlock(&mutex);
}
