['Here's an example of how you might implement this in C. Note that this code does not include all the features mentioned, but it provides a starting point for your requirements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <errno.h>

typedef struct {
    char* command;
    struct timespec timeout;
} Task;

typedef struct {
    pid_t id;
    Task* task;
} Process;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *msg) {
    // Implement logging here.
    printf("%s\n", msg);
}

int execute_command(Task* task) {
    pid_t pid = fork();

    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", task->command, NULL);
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        log_message("Failed to fork process");
        return -1;
    }

    // Wait for the command to finish or timeout.
    struct timespec remaining = task->timeout;
    while(nanosleep(&remaining, &remaining) == -1 && errno == EINTR);

    if (kill(pid, 0) == 0) {
        kill(pid, SIGKILL);
        log_message("Command timed out");
        return -1;
    }

    int status;
    waitpid(pid, &status, 0);

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        log_message("Command failed");
        return -1;
    }

    return 0;
}

void* process_task(void *arg) {
    Process* process = (Process*) arg;
    execute_command(process->task);
    free(process->task->command);
    free(process->task);
    free(process);

    return NULL;
}

int main() {
    int taskCount = 0;
    Task** tasks = malloc(sizeof(Task*));
    char command[256];
    struct timespec timeout;

    while (scanf("%s %ld", command, &timeout.tv_sec) == 2) {
        tasks = realloc(tasks, sizeof(Task*) * ++taskCount);

        Task* task = malloc(sizeof(Task));
        if (!task) {
            log_message("Failed to allocate memory for task");
            continue;
        }

        task->command = strdup(command);
        task->timeout = timeout;
        tasks[taskCount - 1] = task;
    }

    Process** processes = calloc(taskCount, sizeof(Process*));
    if (!processes) {
        log_message("Failed to allocate memory for processes");
        return EXIT_FAILURE;
    }

    pthread_t threads[taskCount];
    for (int i = 0; i < taskCount; ++i) {
        Process* process = malloc(sizeof(Process));
        if (!process) {
            log_message("Failed to allocate memory for process");
            continue;
        }

        process->id = i + 1;
        process->task = tasks[i];
        processes[i] = process;

        pthread_create(&threads[i], NULL, process_task, process);
    }

    for (int i = 0; i < taskCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(tasks);
    free(processes);

    return EXIT_SUCCESS;
}
```
This code reads command strings and timeout values from standard input, stores them in an array of `Task` structures, and executes each command with the specified timeout. It uses a separate thread for each process to ensure that commands are executed concurrently without blocking the main thread. The function logs all operations using printf, which can be replaced with a call to your logging library.
']

