typedef struct Record {
    int value;
} Record;

typedef struct ArrayManager {
    pthread_mutex_t lock;
    Record* records;
    long* offsets;
    size_t capacity;
    size_t size;
} ArrayManager;

ArrayManager* createArrayManager(size_t initialCapacity) {
    ArrayManager* manager = malloc(sizeof(ArrayManager));
    if (manager == NULL) {
        logError("Failed to allocate memory for ArrayManager");
        return NULL;
    }

    manager->records = calloc(initialCapacity, sizeof(Record));
    if (manager->records == NULL) {
        logError("Failed to allocate memory for records array");
        free(manager);
        return NULL;
    }

    manager->offsets = calloc(initialCapacity, sizeof(long));
    if (manager->offsets == NULL) {
        logError("Failed to allocate memory for offsets array");
        free(manager);
        free(manager->records);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    logInfo("ArrayManager created with capacity: %zu", initialCapacity);
    return manager;
}

void resizeArray(ArrayManager* manager) {
    size_t newCapacity = manager->capacity * 2;
    Record* newRecords = realloc(manager->records, newCapacity * sizeof(Record));
    if (newRecords == NULL) {
        logError("Failed to resize records array");
        return;
    }

    long* newOffsets = realloc(manager->offsets, newCapacity * sizeof(long));
    if (newOffsets == NULL) {
        logError("Failed to resize offsets array");
        free(newRecords);
        return;
    }

    manager->records = newRecords;
    manager->offsets = newOffsets;
    manager->capacity = newCapacity;

    logInfo("ArrayManager resized to capacity: %zu", newCapacity);
}

void addRecord(ArrayManager* manager, int value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        resizeArray(manager);
    }

    manager->records[manager->size].value = value;
    manager->offsets[manager->size] = manager->size * sizeof(Record);
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
}

int findLargestIntegerInArray(ArrayManager* manager) {
    int maxValue = INT_MIN;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].value > maxValue) {
            maxValue = manager->records[i].value;
        }
    }

    return maxValue;
}

void loadDataFromFile(ArrayManager* manager, const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        logError("Failed to open file: %s", strerror(errno));
        return;
    }

    int value;
    while (fscanf(file, "%d", &value) == 1) {
        addRecord(manager, value);
    }

    if (!feof(file)) {
        logError("Failed to read from file: %s", strerror(errno));
    }

    fclose(file);
}

void checkMemoryLeaks() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    logInfo("Current heap usage: %ld", usage.ru_maxrss);
}
```
