```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef enum {PENDING, COMPLETED, FAILED} Status;

typedef struct Transaction {
    int id;
    time_t timestamp;
    char* description;
    Status status;
    void* payload; // This can be any type of data
    pthread_mutex_t lock;
    struct Transaction *next;
} Transaction;

#define TABLE_SIZE 2069
Transaction *transactionTable[TABLE_SIZE];
pthread_mutex_t tableLock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash(int key) {
    return key % TABLE_SIZE;
}

void insertTransaction(Transaction* transaction) {
    pthread_mutex_lock(&tableLock);
    unsigned int index = hash(transaction->id);
    Transaction *node, *lastNode = NULL;

    for (node = transactionTable[index]; node != NULL && node->id != transaction->id; node = node->next) {
        lastNode = node;
    }

    if (node == NULL) { // New transaction
        pthread_mutex_init(&transaction->lock, NULL);

        if (lastNode == NULL) { // First in the list
            transactionTable[index] = transaction;
        } else {
            lastNode->next = transaction;
        }
    } else { // Existing transaction
        pthread_mutex_lock(&node->lock);

        node->timestamp = transaction->timestamp;
        free(node->description);
        node->description = strdup(transaction->description);
        node->status = transaction->status;
        // Update payload as well...
    }

    pthread_mutex_unlock(&tableLock);
}

Transaction* getTransaction(int id) {
    unsigned int index = hash(id);
    Transaction *node;

    for (node = transactionTable[index]; node != NULL && node->id != id; node = node->next);

    return node;
}
```
