['Here is an example of how you might implement this task using C with POSIX threads (pthreads) for synchronization and error handling mechanisms. This code does not include the CSV export functionality or integration with an external logging library, as these would require additional libraries and complexities that are beyond the scope of this question.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

typedef struct {
    long offset;
    int key;
    float value;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    Record *records;
} Dataset;

Dataset dataset = { PTHREAD_MUTEX_INITIALIZER, 0, 0, NULL };
size_t maxMemoryUsage = 1024 * 1024 * 1024; // 1GB

int addRecord(long offset, int key, float value) {
    pthread_mutex_lock(&dataset.mutex);

    if (dataset.size >= dataset.capacity && sizeof(Record) > maxMemoryUsage - dataset.size * sizeof(Record)) {
        fprintf(stderr, "Error: Out of memory\n");
        pthread_mutex_unlock(&dataset.mutex);
        return -1;
    }

    if (dataset.size >= dataset.capacity) {
        size_t newCapacity = dataset.capacity ? dataset.capacity * 2 : 1;
        Record *newRecords = realloc(dataset.records, newCapacity * sizeof(Record));

        if (newRecords == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for records: %s\n", strerror(errno));
            pthread_mutex_unlock(&dataset.mutex);
            return -1;
        }

        dataset.records = newRecords;
        dataset.capacity = newCapacity;
    }

    dataset.records[dataset.size].offset = offset;
    dataset.records[dataset.size].key = key;
    dataset.records[dataset.size].value = value;
    dataset.size++;

    pthread_mutex_unlock(&dataset.mutex);
    return 0;
}
```
This code defines a `Record` struct to hold the data for each record, and a `Dataset` struct to manage an array of records. The `addRecord` function is thread-safe and resizes the dataset as needed to avoid exceeding the maximum memory usage limit. It uses pthread mutexes to ensure that only one thread can modify the dataset at a time.
']

