file_record* read_config(const char* filename, int* count) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Failed to open config file\n");
        return NULL;
    }

    // Assume each line in the configuration file is a path.
    char buffer[256];
    int capacity = 10, size = 0;
    file_record* records = malloc(capacity * sizeof(file_record));
    while (fgets(buffer, sizeof(buffer), fp)) {
        // Remove trailing newline.
        buffer[strcspn(buffer, "\n")] = 0;

        if (size == capacity) {
            capacity *= 2;
            records = realloc(records, capacity * sizeof(file_record));
        }

        // Allocate memory for the path and copy it.
        records[size].path = malloc(strlen(buffer) + 1);
        strcpy(records[size].path, buffer);

        // Set timestamp to current time.
        records[size].timestamp = time(NULL);

        size++;
    }

    fclose(fp);

    *count = size;
    return records;
}
```
