Packet* createPackets(size_t num, const char* startIP, const char* endIP) {
    // Convert IP addresses to long for easy comparison and incrementing
    unsigned long start = inet_addr(startIP);
    unsigned long end = inet_addr(endIP);

    if (end < start || num > end - start + 1) {
        fprintf(stderr, "Invalid IP range or number of packets\n");
        return NULL;
    }

    Packet* packets = malloc(num * sizeof(Packet));
    if (!packets) {
        perror("Failed to allocate memory for packets");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < num; ++i) {
        Packet* packet = &packets[i];

        packet->packetSize = 0;
        strcpy(packet->sourceIP, inet_ntoa(start + rand() % (end - start + 1)));
        strcpy(packet->destIP, inet_ntoa(start + rand() % (end - start + 1)));
        packet->timestamp = time(NULL);
    }

    return packets;
}
