// Global array and its size
packet_header_t* headers = NULL;
atomic_int header_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_headers(size_t count) {
    pthread_mutex_lock(&lock);

    if (headers != NULL) {
        // If headers are already initialized, free the old memory
        free(headers);
    }

    headers = malloc(count * sizeof(packet_header_t));
    header_count = count;

    pthread_mutex_unlock(&lock);
}

void set_header(int index, packet_header_t* header) {
    if (index < 0 || index >= atomic_load(&header_count)) {
        // Handle out of bounds error
        return;
    }

    pthread_mutex_lock(&lock);

    headers[index] = *header;

    pthread_mutex_unlock(&lock);
}

packet_header_t* get_header(int index) {
    if (index < 0 || index >= atomic_load(&header_count)) {
        // Handle out of bounds error
        return NULL;
    }

    pthread_mutex_lock(&lock);

    packet_header_t* header = &headers[index];

    pthread_mutex_unlock(&lock);

    return header;
}
