    if (new_capacity <= record_capacity) return;

    Record* new_records = realloc(records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

