void addRecord(int value) {
    pthread_mutex_lock(&lock);

    if (record_count == record_capacity) resizeRecords(2 * record_capacity + 1);

    Record* record = &records[record_count++];
    record->value = value;
    // Initialize other fields as needed...

    pthread_mutex_unlock(&lock);
}

int findMax() {
    int max = 0;
    for (size_t i = 0; i < record_count; ++i) {
        if (records[i].value > max) max = records[i].value;
    }

    return max;
}

double calculateAverage() {
    double sum = 0.0;
    for (size_t i = 0; i < record_count; ++i) {
        sum += records[i].data_value;
    }

    return sum / record_count;
}

