#include "rbtree.h" // Assuming you have a Red-Black tree library
#include "external_config_manager.h" // Assuming you have an external config manager library
#include "logging.h" // Assuming you have a logging library

typedef struct ConfigItem {
    int type; // 0 for int, 1 for float, 2 for bool, 3 for char*
    union {
        int i_value;
        float f_value;
        bool b_value;
        char *s_value;
    } value;
    char *purpose;
    void *parent; // Pointer to parent node
    int ref_count;
} ConfigItem;

typedef struct Observer {
    void (*callback)(ConfigItem*);
    struct Observer *next;
} Observer;

// Global variables for managing observers and the Red-Black tree
Observer *observers = NULL;
RBTree *config_tree = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void register_observer(void (*callback)(ConfigItem*)) {
    Observer *new_observer = malloc(sizeof(Observer));
    new_observer->callback = callback;
    pthread_mutex_lock(&lock);
    new_observer->next = observers;
    observers = new_observer;
    pthread_mutex_unlock(&lock);
}

void unregister_observer(void (*callback)(ConfigItem*)) {
    pthread_mutex_lock(&lock);
    Observer **prev_next = &observers;
    while(*prev_next) {
        if((*prev_next)->callback == callback) {
            Observer *to_free = *prev_next;
            *prev_next = (*prev_next)->next;
            free(to_free);
            break;
        }
        prev_next = &(*prev_next)->next;
    }
    pthread_mutex_unlock(&lock);
}

void notify_observers(ConfigItem *item) {
    Observer *current = observers;
    while(current) {
        current->callback(item);
        current = current->next;
    }
}

// Function to initialize a ConfigItem with random values and unique string
void init_config_item(ConfigItem *item, int type, void *parent) {
    item->type = type;
    item->purpose = generate_random_string(); // Assuming this function exists
    item->ref_count = 0;
    item->parent = parent;

    switch(type) {
        case 0: // int
            item->value.i_value = rand() % MAX_INT_VALUE; // Assuming MAX_INT_VALUE is defined
            break;
        case 1: // float
            item->value.f_value = (float)rand() / RAND_MAX * MAX_FLOAT_VALUE; // Assuming MAX_FLOAT_VALUE is defined
            break;
        case 2: // bool
            item->value.b_value = rand() % 2;
            break;
        case 3: // char*
            item->value.s_value = generate_random_string();
            break;
    }
}
