#include <stdio.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/err.h>

typedef struct Task {
    int id;
    int priority;
    time_t startTime;
    double duration;
} Task;

// Global variables for thread safety and resource management
Task* tasks = NULL;
int taskCount = 0;
pthread_mutex_t lock;
const size_t MAX_MEMORY_USAGE = 1024 * 1024 * 1024; // 1GB
size_t currentMemoryUsage = 0;

// Function to add a task
void addTask(int id, int priority, time_t startTime, double duration) {
    pthread_mutex_lock(&lock);

    if (currentMemoryUsage + sizeof(Task) > MAX_MEMORY_USAGE) {
        printf("Maximum memory usage reached. Cannot add task.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    tasks = realloc(tasks, (taskCount + 1) * sizeof(Task));
    Task newTask = {id, priority, startTime, duration};
    tasks[taskCount++] = newTask;

    currentMemoryUsage += sizeof(Task);

    pthread_mutex_unlock(&lock);
}

// Function to retrieve a task by ID
Task* getTaskById(int id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < taskCount; ++i) {
        if (tasks[i].id == id) {
            pthread_mutex_unlock(&lock);
            return &(tasks[i]);
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to check the status of each task and update its end time
void checkTaskStatus() {
    // Implement your own logic here
}

int main() {
    // Initialize mutex for thread safety
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        return 1;
    }

    // Add tasks
    addTask(1, 5, time(NULL), 2.5);
    addTask(2, 3, time(NULL), 1.0);

    // Retrieve a task by ID
    Task* task = getTaskById(1);
    if (task != NULL) {
        printf("Retrieved task with id %d\n", task->id);
    } else {
        printf("No task found with the given id\n");
    }

    // Check status of each task and update its end time
    checkTaskStatus();

    // Cleanup
    free(tasks);
    pthread_mutex_destroy(&lock);

    return 0;
}
