typedef struct {
    char* message;
    int priority;
    time_t timestamp;
} Event;

char *messageTemplates[] = {"Template 1", "Template 2", "Template 3"}; // Add more templates as needed
const int numMessageTemplates = sizeof(messageTemplates) / sizeof(messageTemplates[0]);

Event* createEvents() {
    Event* events = calloc(100, sizeof(Event));
    if (events == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator with current time

    for (int i = 0; i < 100; ++i) {
        events[i].message = malloc(strlen(messageTemplates[i % numMessageTemplates]) + 1);
        if (events[i].message == NULL) {
            printf("Memory allocation failed.\n");
            // Free previously allocated memory before returning
            for (--i; i >= 0; --i) {
                free(events[i].message);
            }
            free(events);
            return NULL;
        }

        strcpy(events[i].message, messageTemplates[i % numMessageTemplates]);
        events[i].priority = rand() % 10 + 1; // Priorities range from 1 to 10
        events[i].timestamp = time(NULL);
    }

    return events;
}
```

