```cpp
#include <chrono>
#include <fstream>
#include <iostream>
#include <map>
#include <vector>
#include <filesystem>
#include <boost/archive/text_oarchive.hpp> 
#include <boost/archive/text_iarchive.hpp> 
#include <boost/serialization/map.hpp>
#include <zlib.h>

using namespace std;
namespace fs = std::filesystem;

struct LogEvent {
    chrono::system_clock::time_point timestamp;
    string eventType;
    int statusCode;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & timestamp;
        ar & eventType;
        ar & statusCode;
    }
};

class LogManager {
private:
    map<chrono::system_clock::time_point, LogEvent> logEvents;
    fs::path filePath;
    size_t maxFileSizeLimit;

public:
    LogManager(const fs::path& path) : filePath(path), maxFileSizeLimit(1024 * 1024 * 50) {} // 50MB limit as an example

    void addLogEvent(const LogEvent& event) {
        logEvents[event.timestamp] = event;

        if (fs::file_size(filePath) > maxFileSizeLimit) {
            compressAndSave();
        } else {
            saveToDisk();
        }
    }

    void removeLogEvent(const chrono::system_clock::time_point& timestamp) {
        logEvents.erase(timestamp);
        saveToDisk();
    }

    LogEvent getLogEvent(const chrono::system_clock::time_point& timestamp) const {
        auto it = logEvents.find(timestamp);
        if (it != logEvents.end()) {
            return it->second;
        } else {
            throw runtime_error("No such event");
        }
    }

private:
    void saveToDisk() const {
        std::ofstream file(filePath);
        boost::archive::text_oarchive oa(file);
        oa << logEvents;
    }

    void compressAndSave() const {
        vector<char> buffer;

        // Serialize to a string
        std::stringstream ss;
        boost::archive::text_oarchive oa(ss);
        oa << logEvents;
        string data = ss.str();

        // Compress the serialized data
        buffer.resize(compressBound(data.size()));
        uLongf compressedSize = buffer.size();
        compress((Bytef*)buffer.data(), &compressedSize, (const Bytef*)data.c_str(), data.size());

        // Write the compressed data to disk
        std::ofstream file(filePath, ios::binary);
        file.write(buffer.data(), compressedSize);
    }
};
```
This code does not handle errors and it doesn't support text format serialization/deserialization or indexing. It also doesn't dynamically adjust the maxFileSizeLimit based on system resources, which would require a more complex implementation. 

Please note that this is just a basic example and real-world applications will need to handle many other aspects such as concurrency control, error handling, efficient memory usage etc. Also, compression/decompression operations can be expensive in terms of CPU time, so they should be used judiciously based on the specific requirements of your application.
