    if (str == NULL) {
        errorCallback("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < length; ++i) {
        int randomChar = rand() % (26 + 26 + 10);
        if (randomChar < 26)
            str[i] = 'a' + randomChar;
        else if (randomChar < 52)
            str[i] = 'A' + randomChar - 26;
        else
            str[i] = '0' + randomChar - 52;
    }

    str[length] = 0;
    return str;
}

