typedef struct {
    long offset;
    int key;
} record_t;

typedef struct {
    pthread_mutex_t lock;
    size_t max_size;
    size_t current_size;
    record_t *records;
} memory_manager_t;

memory_manager_t* create_memory_manager(size_t initial_size) {
    memory_manager_t *mm = malloc(sizeof(memory_manager_t));
    if (pthread_mutex_init(&mm->lock, NULL) != 0) {
        free(mm);
        return NULL; 
    }
    mm->max_size = initial_size;
    mm->current_size = 0;
    mm->records = malloc(initial_size * sizeof(record_t));
    if (mm->records == NULL) {
        free(mm);
        return NULL; 
    }
    return mm;
}

void destroy_memory_manager(memory_manager_t *mm) {
    pthread_mutex_destroy(&mm->lock);
    free(mm->records);
    free(mm);
}

int add_record(memory_manager_t *mm, record_t record) {
    pthread_mutex_lock(&mm->lock);

    if (mm->current_size >= mm->max_size) {
        size_t new_size = mm->max_size * 2;
        record_t *new_records = realloc(mm->records, new_size * sizeof(record_t));
        if (new_records == NULL) {
            pthread_mutex_unlock(&mm->lock);
            return -1; 
        }
        mm->max_size = new_size;
        mm->records = new_records;
    }

    mm->records[mm->current_size++] = record;

    pthread_mutex_unlock(&mm->lock);
    return 0; 
}
```
