// Define a structure to hold connection information
typedef struct {
    char ip[INET6_ADDRSTRLEN];
    int port;
    time_t lastAccessed;
    int statusFlag;
    double latencyValue;
} ConnectionRecord;

// Define a structure to manage the pool of connections
typedef struct {
    pthread_mutex_t mutex;
    ConnectionRecord* records;
    size_t count;
    size_t capacity;
} ConnectionPool;

// Initialize the connection pool
void initConnectionPool(ConnectionPool* pool) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->records = NULL;
    pool->count = 0;
    pool->capacity = 0;
}

// Add a connection to the pool
void addConnection(ConnectionPool* pool, const char* ip, int port) {
    pthread_mutex_lock(&pool->mutex);

    // Check if we need to resize the array
    if (pool->count == pool->capacity) {
        size_t newCapacity = pool->capacity == 0 ? 1 : pool->capacity * 2;
        ConnectionRecord* newRecords = realloc(pool->records, newCapacity * sizeof(ConnectionRecord));

        if (newRecords == NULL) {
            fprintf(stderr, "Failed to allocate memory for connection records\n");
            pthread_mutex_unlock(&pool->mutex);
            return;
        }

        pool->records = newRecords;
        pool->capacity = newCapacity;
    }

    // Add the new connection to the array
    ConnectionRecord* record = &pool->records[pool->count];
    strncpy(record->ip, ip, sizeof(record->ip));
    record->port = port;
    gettimeofday(&record->lastAccessed, NULL);

    pool->count++;

    pthread_mutex_unlock(&pool->mutex);
}
```
