void processAndAggregateLogFiles(const char* directory) {
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir (directory)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            // Skip "." and ".." directories
            if(strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

            char* filePath = malloc(strlen(directory) + strlen(ent->d_name) + 2); // +2 for '/' and '\0'
            sprintf(filePath, "%s/%s", directory, ent->d_name);

            FILE* file = fopen(filePath, "r");
            if (file == NULL) {
                syslog(LOG_ERR, "Failed to open file: %s", strerror(errno));
                free(filePath);
                continue;
            }

            processFile(file);

            fclose(file);
            free(filePath);
        }
        closedir (dir);
    } else {
        syslog(LOG_ERR, "Failed to open directory: %s", strerror(errno));
    }
}

void processFile(FILE* file) {
    json_error_t error;
    json_t *root = json_loadf(file, 0, &error);

    if(!json_is_array(root)) {
        syslog(LOG_ERR, "Invalid JSON format: root is not an array");
        return;
    }

    for(size_t i = 0; i < json_array_size(root); i++) {
        json_t *data = json_array_get(root, i);

        if(!json_is_object(data)) {
            syslog(LOG_ERR, "Invalid JSON format: data is not an object");
            continue;
        }

        Event* event = malloc(sizeof(Event));
        // Populate the event fields from the json data...

        pthread_mutex_lock(&lock);
        addToList(event);
        pthread_mutex_unlock(&lock);
    }

    json_decref(root);
}

void addToList(Event* event) {
    Node* node = malloc(sizeof(Node));
    node->data = event;
    node->next = head;
    head = node;

    if(strcmp(event->severity_level, "INFO") == 0) infoCount++;
    else if(strcmp(event->severity_level, "WARNING") == 0) warningCount++;
    else if(strcmp(event->severity_level, "ERROR") == 0) errorCount++;

    totalEvents++;
}
