void insert(Event* event) {
    pthread_mutex_lock(&list.lock);

    Node* node = malloc(sizeof(Node));
    node->data = event;
    node->prev = list.tail;
    node->next = NULL;

    if (list.head == NULL) {
        list.head = node;
    } else {
        list.tail->next = node;
    }

    list.tail = node;

    pthread_mutex_unlock(&list.lock);
}

Event* retrieve() {
    pthread_mutex_lock(&list.lock);

    if (list.head == NULL) {
        pthread_mutex_unlock(&list.lock);
        return NULL;
    }

    Event* event = list.head->data;
    Node* next = list.head->next;
    free(list.head);
    list.head = next;

    if (list.head == NULL) {
        list.tail = NULL;
    } else {
        list.head->prev = NULL;
    }

    pthread_mutex_unlock(&list.lock);

    return event;
}
