} HashTable;

HashTable* createHashTable(size_t initialCapacity, float minValue, float maxValue) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->entries = calloc(initialCapacity, sizeof(Entry*));
    if (table->entries == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = initialCapacity;
    table->count = 0;
    table->minValue = minValue;
    table->maxValue = maxValue;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insertEntry(HashTable* table, Entry* entry) {
    if (entry == NULL || table == NULL) return;

    pthread_mutex_lock(&table->lock);

    // Check if we need to resize the hash table
    if (table->count >= table->capacity / 2) {
        size_t newCapacity = table->capacity * 2;
        Entry** newEntries = realloc(table->entries, sizeof(Entry*) * newCapacity);

        if (newEntries == NULL) {
            pthread_mutex_unlock(&table->lock);
            return;
        }

        table->capacity = newCapacity;
        table->entries = newEntries;
    }

    // Insert the entry into the hash table
    size_t index = rand() % table->capacity;  // Simple hashing function for demonstration purposes
    while (table->entries[index] != NULL) {
        index = (index + 1) % table->capacity;  // Linear probing to resolve collisions
    }

    table->entries[index] = entry;
    table->count++;

    pthread_mutex_unlock(&table->lock);
}
