    int priority;
} job;

typedef struct {
    job* jobs;
    size_t count;
    pthread_mutex_t mutex;
    pthread_barrier_t barrier;
} job_collection;

job_collection* create_job_collection(size_t initial_capacity) {
    job_collection* collection = malloc(sizeof(job_collection));
    if (collection == NULL) {
        fprintf(stderr, "Failed to allocate memory for job collection\n");
        return NULL;
    }

    collection->jobs = calloc(initial_capacity, sizeof(job));
    if (collection->jobs == NULL) {
        fprintf(stderr, "Failed to allocate memory for jobs array\n");
        free(collection);
        return NULL;
    }

    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    pthread_barrier_init(&collection->barrier, NULL, initial_capacity);

    return collection;
}

void add_job(job_collection* collection, job new_job) {
    if (new_job.task_id < 0 || new_job.priority < 0) {
        fprintf(stderr, "Invalid task ID or priority\n");
        return;
    }

    pthread_mutex_lock(&collection->mutex);

    if (collection->count == collection->capacity) {
        // Resize the array and update capacity
        size_t new_capacity = collection->capacity * 2;
        job* new_jobs = realloc(collection->jobs, new_capacity * sizeof(job));
        if (new_jobs == NULL) {
            fprintf(stderr, "Failed to resize jobs array\n");
            pthread_mutex_unlock(&collection->mutex);
            return;
        }

        collection->jobs = new_jobs;
        collection->capacity = new_capacity;
    }

    collection->jobs[collection->count++] = new_job;

    pthread_mutex_unlock(&collection->mutex);
}
