    pthread_mutex_t lock;
    size_t memory_limit;
    size_t current_memory;
} LinkedList;

LinkedList* create_linked_list(size_t memory_limit) {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;

    atomic_init(&list->head, NULL);
    pthread_mutex_init(&list->lock, NULL);
    list->memory_limit = memory_limit;
    list->current_memory = 0;

    return list;
}

void insert(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (list->current_memory + sizeof(Node) > list->memory_limit) {
        // Handle memory limit exceeding. You might want to trigger garbage collection or resize the memory pool here.
    } else {
        node->next = atomic_load(&list->head);

        while (!atomic_compare_exchange_weak(&list->head, &node->next, node)) {}

        list->current_memory += sizeof(Node);
    }

    pthread_mutex_unlock(&list->lock);
}

void delete(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (atomic_load(&list->head) == node) {
        atomic_store(&list->head, node->next);

        free(node->string);
        free(node);

        list->current_memory -= sizeof(Node);
    } else {
        Node* prev = NULL;
        Node* curr = atomic_load(&list->head);

        while (curr != node && curr != NULL) {
            prev = curr;
            curr = curr->next;
        }

        if (curr == node) {
            prev->next = curr->next;

            free(node->string);
            free(node);

            list->current_memory -= sizeof(Node);
        }
    }

    pthread_mutex_unlock(&list->lock);
}
```
