```java
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class MetricsManager {
    private static final Logger logger = LoggerFactory.getLogger(MetricsManager.class);

    private ConcurrentHashMap<String, Double> doubleValues = new ConcurrentHashMap<>();
    private ConcurrentHashMap<String, String> stringKeys = new ConcurrentHashMap<>();
    private ConcurrentHashMap<String, DataPoint> dataPoints = new ConcurrentHashMap<>();

    private AtomicInteger requestsCount = new AtomicInteger(0);
    private AtomicInteger failedMetricsCount = new AtomicInteger(0);
    private AtomicInteger internalErrorsCount = new AtomicInteger(0);

    public void addDoubleValue(String key, Double value) {
        doubleValues.put(key, value);
    }

    public void addStringKey(String key, String value) {
        stringKeys.put(key, value);
    }

    public void addDataPoint(String key, DataPoint dataPoint) {
        dataPoints.put(key, dataPoint);
    }

    public void sendMetricsToAPI() throws IOException {
        CloseableHttpClient httpclient = HttpClients.createDefault();

        for (Map.Entry<String, Double> entry : doubleValues.entrySet()) {
            String key = entry.getKey();
            Double value = entry.getValue();

            HttpPost httpPost = new HttpPost("http://api.example.com/metrics");
            String json = "{\"key\": \"" + key + "\", \"value\":" + value + "}";
            StringEntity entity = new StringEntity(json);
            httpPost.setEntity(entity);
            httpPost.setHeader("Accept", "application/json");
            httpPost.setHeader("Content-type", "application/json");

            CloseableHttpResponse response = httpclient.execute(httpPost);
            requestsCount.incrementAndGet();

            if (response.getStatusLine().getStatusCode() != 200) {
                failedMetricsCount.incrementAndGet();
                logger.error("Failed to send metric: " + key);
            } else {
                logger.info("Metric sent successfully: " + key);
            }
        }
    }

    public void logInternalErrors() {
        logger.error("Number of requests: " + requestsCount);
        logger.error("Number of failed metrics: " + failedMetricsCount);
        logger.error("Number of internal errors: " + internalErrorsCount);
    }
}
```

