        module->identifier[i] = charset[key];
    }
    module->identifier[identifier_length] = '\0';

    module->ref_count = 0;
    module->parent = NULL;

    return module;
}

void destroy_module(Module *module) {
    free(module->identifier);
    free(module);
}
