    char* message;
    size_t length;
} data_packet;

static const char* messages[] = {"Message1", "Message2", "Message3"};
static const int num_messages = sizeof(messages) / sizeof(char*);

typedef struct {
    pthread_mutex_t lock;
    data_packet** packets;
    size_t capacity;
    size_t size;
} packet_array;

void init_packets(packet_array* array) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = 10;
    array->size = 0;
    array->packets = malloc(array->capacity * sizeof(data_packet*));
}

void add_packet(packet_array* array, data_packet* packet) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        // Resize the array when it's full
        array->capacity *= 2;
        data_packet** new_packets = realloc(array->packets, array->capacity * sizeof(data_packet*));

        if (new_packets == NULL) {
            // Handle allocation failure gracefully
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->packets = new_packets;
    }

    array->packets[array->size++] = packet;

    pthread_mutex_unlock(&array->lock);
}

void free_packet(data_packet* packet) {
    if (packet != NULL) {
        free(packet->message);
        free(packet);
    }
}

void destroy_packets(packet_array* array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        free_packet(array->packets[i]);
    }

    free(array->packets);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

void init_data() {
    packet_array array;
    init_packets(&array);

    for (int i = 0; i < num_messages; ++i) {
        data_packet* packet = malloc(sizeof(data_packet));

        if (packet == NULL) {
            // Handle allocation failure gracefully
            continue;
        }

        packet->length = strlen(messages[i]);
        packet->message = malloc(packet->length + 1);

        if (packet->message == NULL) {
            // Handle allocation failure gracefully
            free_packet(packet);
            continue;
        }

        strcpy(packet->message, messages[i]);
        add_packet(&array, packet);
    }

    destroy_packets(&array);
}
```
This code is a basic example and does not include logging or other advanced features. It's recommended to use a more robust memory management library for production-level code. Also, error handling in this code is quite rudimentary and may need to be expanded upon depending on your specific requirements.
