    int* keys;
    Record** records;
    size_t capacity;
    pthread_mutex_t lock;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager* manager = malloc(sizeof(ArrayManager));
    if (manager == NULL) {
        fprintf(stderr, "Failed to allocate memory for ArrayManager: %s\n", strerror(errno));
        return NULL;
    }

    manager->offsets = malloc(initial_capacity * sizeof(long));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->records = malloc(initial_capacity * sizeof(Record*));
    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for arrays: %s\n", strerror(errno));
        free_array_manager(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resize_arrays(ArrayManager* manager, size_t new_capacity) {
    manager->offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    manager->keys = realloc(manager->keys, new_capacity * sizeof(int));
    manager->records = realloc(manager->records, new_capacity * sizeof(Record*));

    if (new_capacity > manager->capacity) {
        for (size_t i = manager->capacity; i < new_capacity; ++i) {
            manager->records[i] = malloc(sizeof(Record));
        }
    } else {
        for (size_t i = new_capacity; i < manager->capacity; ++i) {
            free(manager->records[i]);
        }
    }

    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL) {
        fprintf(stderr, "Failed to resize arrays: %s\n", strerror(errno));
        exit(EXIT_FAILURE); // or handle error in a different way
    }

    manager->capacity = new_capacity;
}

void add_record(ArrayManager* manager, long offset, int key, double value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->records[manager->capacity - 1] != NULL) {
        resize_arrays(manager, manager->capacity * 2); // increase capacity by a factor of 2 when full
    }

    size_t index = 0;
    while (manager->records[index] != NULL) {
        ++index;
    }

    manager->offsets[index] = offset;
    manager->keys[index] = key;
    manager->records[index]->value = value;

    pthread_mutex_unlock(&manager->lock);
}

void free_array_manager(ArrayManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->records[i] != NULL) {
            free(manager->records[i]);
        }
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```
