#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

typedef struct {
    char* message;
    atomic_size_t length;
} data_packet;

static const char* messages[] = {"Hello", "World", "How", "Are", "You"};

data_packet** allocate_packets(int num_packets) {
    // Allocate memory for the array of packets
    data_packet** packets = malloc(num_packets * sizeof(data_packet*));
    if (packets == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for packets");
        return NULL;
    }

    // Initialize each packet with a unique message
    for (int i = 0; i < num_packets; ++i) {
        data_packet* packet = malloc(sizeof(data_packet));
        if (packet == NULL) {
            syslog(LOG_ERR, "Failed to allocate memory for packet %d", i);
            // Free previously allocated packets and return NULL on failure
            while (--i >= 0) free(packets[i]);
            free(packets);
            return NULL;
        }

        size_t length = strlen(messages[i % 5]);
        packet->message = malloc(length + 1);
        if (packet->message == NULL) {
            syslog(LOG_ERR, "Failed to allocate memory for message of packet %d", i);
            // Free previously allocated packets and return NULL on failure
            free(packet);
            while (--i >= 0) free(packets[i]);
            free(packets);
            return NULL;
        }

        strcpy(packet->message, messages[i % 5]);
        atomic_init(&packet->length, length);

        packets[i] = packet;
    }

    syslog(LOG_INFO, "Successfully allocated and initialized %d packets", num_packets);
    return packets;
}
