    int value;
    char* string;
    char* encrypted_string;
} Record;

// Global variables
int offset[10];
char key[10][256];
Record** records;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a record
void init_record(Record* record, int min_value, int max_value, size_t string_length, size_t encrypted_length) {
    // Generate random value within range
    srand(time(NULL));
    record->value = rand() % (max_value - min_value + 1) + min_value;

    // Allocate memory for string and encrypted string
    record->string = malloc((string_length + 1) * sizeof(char));
    record->encrypted_string = malloc((encrypted_length + 1) * sizeof(char));

    // Generate random string
    int i;
    for (i = 0; i < string_length; i++) {
        record->string[i] = 'a' + rand() % 26;
    }
    record->string[string_length] = '\0';

    // Encrypt the string using EVP functions (assuming ECB mode for simplicity)
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_ecb(), key[record->value % 10], NULL);

    int len;
    EVP_EncryptUpdate(ctx, (unsigned char*) record->encrypted_string, &len, (const unsigned char*) record->string, string_length);
    EVP_EncryptFinal(ctx, (unsigned char*) record->encrypted_string + len, &len);

    EVP_CIPHER_CTX_free(ctx);
}

// Function to initialize multiple records concurrently
void* init_records(void* arg) {
    int min_value = *((int*) arg);
    int max_value = *((int*) arg + 1);
    size_t string_length = *((size_t*) arg + 2);
    size_t encrypted_length = *((size_t*) arg + 3);

    pthread_mutex_lock(&lock);
    for (int i = 0; i < 10; i++) {
        init_record(records[i], min_value, max_value, string_length, encrypted_length);
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();

    // Generate random keys for encryption
    srand(time(NULL));
    int i, j;
    for (i = 0; i < 10; i++) {
        for (j = 0; j < 256; j++) {
            key[i][j] = rand() % 256;
        }
    }

    // Allocate memory for records
    records = malloc(10 * sizeof(Record*));
    for (i = 0; i < 10; i++) {
        records[i] = malloc(sizeof(Record));
    }

    // Initialize multiple records concurrently
    pthread_t threads[4];
    int args[4][4] = {{0, 5, 8, 16}, {6, 10, 8, 16}, {11, 15, 8, 16}, {16, 20, 8, 16}};
    for (i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, init_records, args[i]);
    }

    // Wait for all threads to finish
    for (i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    EVP_cleanup();

    return 0;
}
