typedef struct network_config {
    char* ip;
    char* subnetMask;
    char* gateway;
    char* dnsServer;
} NetworkConfig;

typedef struct cache_entry {
    NetworkConfig config;
    sem_t semaphore;
    int accessCount;
    struct cache_entry *next;
} CacheEntry;

CacheEntry *cacheHead = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphorePool[10]; // Assume a pool of 10 semaphores for simplicity
int nextSemaphoreIndex = 0;

void initializeCache(NetworkConfig *configs, int configCount) {
    pthread_mutex_lock(&cacheMutex);

    for (int i = 0; i < configCount; ++i) {
        CacheEntry *entry = malloc(sizeof(CacheEntry));
        entry->config = configs[i];
        sem_init(&entry->semaphore, 0, 1); // Initialize the semaphore with a value of 1
        entry->accessCount = 0;

        if (cacheHead == NULL) {
            cacheHead = entry;
        } else {
            CacheEntry *current = cacheHead;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = entry;
        }
    }

    pthread_mutex_unlock(&cacheMutex);
}
```
