```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int sender_id;
    int receiver_id;
    double amount;
    time_t timestamp;
} TRANSACTION_REQUEST;

// Global variables for thread synchronization and rate limiting
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_transaction_timestamp = 0;
double transaction_volume = 0.0;
int transaction_count = 0;

void* processTransaction(void *arg) {
    TRANSACTION_REQUEST *request = (TRANSACTION_REQUEST *) arg;

    // Acquire lock before processing transaction
    pthread_mutex_lock(&lock);

    // Perform payment gateway API authorization and settlement here...

    // Update rate limiting variables
    time_t current_time = time(NULL);
    if (current_time - last_transaction_timestamp < 1) {  // Rate limit is 1 transaction per second
        printf("Rate limit exceeded. Transaction rejected.\n");
        pthread_mutex_unlock(&lock);  // Release lock before returning
        return NULL;
    }

    last_transaction_timestamp = current_time;
    transaction_volume += request->amount;
    transaction_count++;

    printf("Transaction processed successfully.\n");

    pthread_mutex_unlock(&lock);  // Release lock after processing transaction

    return NULL;
}

void batchProcessTransactions(TRANSACTION_REQUEST *requests, int num_transactions) {
    pthread_t threads[num_transactions];

    for (int i = 0; i < num_transactions; i++) {
        if (pthread_create(&threads[i], NULL, processTransaction, &requests[i]) != 0) {
            perror("Failed to create thread");
            return;
        }
    }

    for (int i = 0; i < num_transactions; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return;
        }
    }
}
```
