['Here is a basic implementation in C using pthreads for thread safety and logging via syslog. This code does not include all the features you requested but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>

typedef struct {
    double value;
    char* id;
} Request;

typedef struct {
    Request** requests;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} Transaction;

Transaction* create_transaction() {
    Transaction* transaction = malloc(sizeof(Transaction));
    if (transaction == NULL) return NULL;

    transaction->requests = NULL;
    transaction->count = 0;
    transaction->capacity = 0;
    pthread_mutex_init(&transaction->lock, NULL);

    syslog(LOG_INFO, "Transaction created");
    return transaction;
}

void add_request(Transaction* transaction, double value, const char* id) {
    if (transaction == NULL || id == NULL) return;

    pthread_mutex_lock(&transaction->lock);

    // Check if we need to resize the array
    if (transaction->count >= transaction->capacity) {
        size_t newCapacity = transaction->capacity == 0 ? 1 : transaction->capacity * 2;

        Request** newRequests = realloc(transaction->requests, sizeof(Request*) * newCapacity);
        if (newRequests == NULL) {
            pthread_mutex_unlock(&transaction->lock);
            return;
        }

        transaction->requests = newRequests;
        transaction->capacity = newCapacity;
    }

    // Create the request and add it to the array
    Request* request = malloc(sizeof(Request));
    if (request == NULL) {
        pthread_mutex_unlock(&transaction->lock);
        return;
    }

    request->value = value;
    request->id = strdup(id);
    transaction->requests[transaction->count++] = request;

    syslog(LOG_INFO, "Request added to transaction");

    pthread_mutex_unlock(&transaction->lock);
}
```
This code creates a `Transaction` struct that contains an array of `Request` pointers. The `add_request` function is thread-safe and resizes the requests array when necessary, ensuring efficient memory management. It also logs operations using syslog for debugging purposes. 

