#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct MediaRecord {
    char* title;
    char* artist;
    long duration;
    double size;
    char* genre;
    char* url;
} MediaRecord;

typedef struct Node {
    MediaRecord record;
    struct Node* next;
} Node;

Node* processMediaPlaylistAdvanced(int n) {
    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < n; ++i) {
        MediaRecord record;

        // Allocate memory and read data from standard input
        char title[100], artist[100], genre[50], url[200];
        long duration;
        double size;
        scanf("%s %s %ld %lf %s %s", title, artist, &duration, &size, genre, url);

        // Allocate memory for the record fields and copy data into them
        record.title = malloc(strlen(title) + 1);
        strcpy(record.title, title);
        record.artist = malloc(strlen(artist) + 1);
        strcpy(record.artist, artist);
        record.duration = duration;
        record.size = size;
        record.genre = malloc(strlen(genre) + 1);
        strcpy(record.genre, genre);
        record.url = malloc(strlen(url) + 1);
        strcpy(record.url, url);

        // Create a new node and add it to the list
        Node* node = malloc(sizeof(Node));
        node->record = record;
        node->next = NULL;

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    return head;
}
