#include <string.h>

typedef struct node {
    char *str;
    int key;
    struct node *next;
} Node;

typedef struct list {
    Node *head;
    pthread_mutex_t lock;
    size_t maxSize;
    size_t currentSize;
} List;

List* createList(size_t maxSize) {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->maxSize = maxSize;
    list->currentSize = 0;

    return list;
}

void insert(List *list, char *str, int key) {
    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) return;

    newNode->str = strdup(str);
    newNode->key = key;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->currentSize >= list->maxSize) {
        // Handle memory limit exceeded error here.
        free(newNode->str);
        free(newNode);
        return;
    }

    newNode->next = list->head;
    list->head = newNode;
    list->currentSize++;

    pthread_mutex_unlock(&list->lock);
}

Node* get(List *list, int key) {
    pthread_mutex_lock(&list->lock);

    Node *node = list->head;
    while (node != NULL && node->key != key) {
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);

    return node;
}
```
