```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int value;
    char string[256];
} Record;

static const char *names[] = {"Alice", "Bob", "Charlie", /*...*/};
static const size_t namesCount = sizeof(names) / sizeof(*names);

typedef struct MemoryPool {
    pthread_mutex_t lock;
    Record *records;
    int *used;
    size_t capacity;
} MemoryPool;

MemoryPool *createMemoryPool(size_t capacity) {
    MemoryPool *pool = malloc(sizeof(*pool));
    if (pool == NULL) return NULL;

    pool->records = calloc(capacity, sizeof(*pool->records));
    if (pool->records == NULL) {
        free(pool);
        return NULL;
    }

    pool->used = calloc(capacity, sizeof(*pool->used));
    if (pool->used == NULL) {
        free(pool->records);
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = capacity;

    return pool;
}

void destroyMemoryPool(MemoryPool *pool) {
    free(pool->used);
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record *allocateRecord(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->used[i]) {
            pool->used[i] = 1;
            pthread_mutex_unlock(&pool->lock);
            return &pool->records[i];
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL; // No free slots.
}

void deallocateRecord(MemoryPool *pool, Record *record) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->capacity; ++i) {
        if (&pool->records[i] == record) {
            pool->used[i] = 0;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void initializeRecord(Record *record, int value, const char *string) {
    record->value = value;
    strncpy(record->string, string, sizeof(record->string));
    record->string[sizeof(record->string) - 1] = '\0'; // Ensure null termination.
}

void initializeRecords(MemoryPool *pool, int minValue, int maxValue) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        Record *record = allocateRecord(pool);
        if (record == NULL) break; // No free slots.

        initializeRecord(record, minValue + rand() % (maxValue - minValue + 1), names[rand() % namesCount]);
    }
}
```
This code creates a custom memory pool that can allocate and deallocate records in a thread-safe manner. It uses a simple bitmap to track which slots are used, but it could be optimized further for larger capacities by using a more efficient data structure or algorithm. The `initializeRecords` function fills the pool with random records, and each record is initialized with a random value within a specified range and a unique string from a predefined list of names.
