GArray *offsets, *keys;
GPtrArray *records;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile;

void initDataStructures(int initialSize) {
    offsets = g_array_new(FALSE, FALSE, sizeof(long));
    keys = g_array_new(FALSE, FALSE, sizeof(int));
    records = g_ptr_array_new();

    logFile = fopen("log.txt", "w");
}

void resizeDataStructures() {
    pthread_mutex_lock(&lock);
    long newSize = 2 * offsets->len; // Simple doubling strategy
    g_array_set_size(offsets, newSize);
    g_array_set_size(keys, newSize);
    g_ptr_array_set_size(records, newSize);
    fprintf(logFile, "Resized data structures to size %ld\n", newSize);
    pthread_mutex_unlock(&lock);
}

void addRecord(int key) {
    pthread_mutex_lock(&lock);
    if (offsets->len == records->len) resizeDataStructures(); // Resize if necessary

    long offset = offsets->len;
    gpointer record = g_malloc(sizeof(Record));
    *((int*)record) = key;

    g_array_append_val(offsets, offset);
    g_array_append_val(keys, key);
    g_ptr_array_add(records, record);

    fprintf(logFile, "Added record with key %d at offset %ld\n", key, offset);
    pthread_mutex_unlock(&lock);
}
