    Record* records;
} DataStructure;

DataStructure* create_data_structure(int offset_count, int key_count, int record_count, 
                                     int string_length, int min_value, int max_value) {
    if (offset_count < 0 || key_count < 0 || record_count < 0 || 
        string_length < 0 || min_value > max_value) {
        return NULL; // Invalid input parameters
    }

    DataStructure* data = malloc(sizeof(DataStructure));
    if (data == NULL) {
        return NULL; // Failed to allocate memory
    }

    data->offsets = calloc(offset_count, sizeof(long));
    data->keys = calloc(key_count, sizeof(int));
    data->records = malloc(record_count * sizeof(Record));
    if (data->offsets == NULL || data->keys == NULL || data->records == NULL) {
        free(data->offsets);
        free(data->keys);
        free(data->records);
        free(data);
        return NULL; // Failed to allocate memory
    }

    for (int i = 0; i < record_count; ++i) {
        data->records[i].string = malloc(string_length + 8); // 8 is the length of "PREFIX"
        if (data->records[i].string == NULL) {
            for (int j = 0; j < i; ++j) {
                free(data->records[j].string);
            }
            free(data->offsets);
            free(data->keys);
            free(data->records);
            free(data);
            return NULL; // Failed to allocate memory
        }

        strcpy(data->records[i].string, "PREFIX");
        RAND_bytes((unsigned char*)&data->records[i].string[6], string_length - 6); // Generate random alphanumeric characters
        data->records[i].value = min_value + rand() % (max_value - min_value + 1); // Set a random value within the specified range
    }

    return data;
}

void destroy_data_structure(DataStructure* data) {
    if (data == NULL) {
        return;
    }

    for (int i = 0; i < record_count; ++i) {
        free(data->records[i].string);
    }

    free(data->offsets);
    free(data->keys);
    free(data->records);
    free(data);
}
