['Here is a high-level overview of how you might approach this task in C. Note that this code does not include all the details mentioned above as it would be quite complex to implement them here, but it should give you an idea of what your function could look like. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t mutex;
    long* offsets;
    int* keys;
    record** records;
    size_t allocated_size;
    atomic_int next_key;
} memory_manager;

memory_manager* create_memory_manager(size_t initial_size) {
    memory_manager* manager = malloc(sizeof(memory_manager));
    if (manager == NULL) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->offsets = calloc(initial_size, sizeof(long));
    manager->keys = calloc(initial_size, sizeof(int));
    manager->records = calloc(initial_size, sizeof(record*));

    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL) {
        destroy_memory_manager(manager);
        return NULL;
    }

    manager->allocated_size = initial_size;
    atomic_init(&manager->next_key, 0);
    return manager;
}

void destroy_memory_manager(memory_manager* manager) {
    pthread_mutex_destroy(&manager->mutex);

    for (int i = 0; i < manager->allocated_size; ++i) {
        free(manager->records[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

int add_record(memory_manager* manager, int value) {
    pthread_mutex_lock(&manager->mutex);

    if (atomic_load(&manager->next_key) >= manager->allocated_size) {
        // Resize the arrays. This is a simplistic approach and may not be optimal for all use cases.
        size_t new_size = manager->allocated_size * 2;
        long* new_offsets = realloc(manager->offsets, new_size * sizeof(long));
        int* new_keys = realloc(manager->keys, new_size * sizeof(int));
        record** new_records = realloc(manager->records, new_size * sizeof(record*));

        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Allocation failed.
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->records = new_records;
        manager->allocated_size = new_size;
    }

    int key = atomic_fetch_add(&manager->next_key, 1);
    manager->records[key] = malloc(sizeof(record));
    if (manager->records[key] == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Allocation failed.
    }

    manager->records[key]->value = value;

    pthread_mutex_unlock(&manager->mutex);
    return key;
}
```
This code provides a basic structure for managing memory and adding records in a thread-safe manner. It uses `pthread_mutex` to ensure that only one thread can modify the arrays at a time, which helps prevent race conditions. The `add_record` function checks if there is enough space for a new record before attempting to add it, resizing the arrays if necessary.
']

