typedef struct Record {
    int value;
} Record;

typedef struct MemoryManager {
    long* offsets;
    int* keys;
    Record* records;
    size_t numRecords;
    size_t totalMemorySize;
} MemoryManager;

void initMemoryManager(MemoryManager* manager, size_t numRecords) {
    assert(numRecords >= 0);

    manager->numRecords = numRecords;
    manager->totalMemorySize = 0;

    if (numRecords > 0) {
        // Allocate memory for offsets, keys and records
        manager->offsets = malloc(sizeof(long) * numRecords);
        assert(manager->offsets != NULL);

        manager->keys = malloc(sizeof(int) * numRecords);
        assert(manager->keys != NULL);

        manager->records = malloc(sizeof(Record) * numRecords);
        assert(manager->records != NULL);

        // Calculate total memory size
        manager->totalMemorySize += sizeof(long) * numRecords;
        manager->totalMemorySize += sizeof(int) * numRecords;
        manager->totalMemorySize += sizeof(Record) * numRecords;
    } else {
        // If no records, set pointers to NULL
        manager->offsets = NULL;
        manager->keys = NULL;
        manager->records = NULL;
    }
}

void freeMemoryManager(MemoryManager* manager) {
    if (manager->numRecords > 0) {
        // Free memory for offsets, keys and records
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);

        // Reset pointers to NULL
        manager->offsets = NULL;
        manager->keys = NULL;
        manager->records = NULL;
    }

    manager->numRecords = 0;
    manager->totalMemorySize = 0;
}
```
