    NR_RLC_PDU* pduList;
    int qosConfig;
} NR_DL_FRAME_TRANSPORT_CONTEXT;

typedef struct DynamicArray {
    NR_DL_FRAME_TRANSPORT_CONTEXT *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initializeAndManageDynamicArray(DynamicArray* array) {
    // Initialize the mutex for thread safety
    pthread_mutex_init(&array->lock, NULL);

    // Allocate memory for the initial array
    array->size = 1;
    array->used = 0;
    array->array = (NR_DL_FRAME_TRANSPORT_CONTEXT*)malloc(array->size * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
}

void insertDynamicArray(DynamicArray* array, NR_DL_FRAME_TRANSPORT_CONTEXT element) {
    pthread_mutex_lock(&array->lock);

    // If the array is full, resize it
    if (array->used == array->size) {
        array->size *= 2;
        array->array = (NR_DL_FRAME_TRANSPORT_CONTEXT*)realloc(array->array, array->size * sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    }

    // Add the new element to the array
    array->array[array->used++] = element;

    pthread_mutex_unlock(&array->lock);
}

void deleteDynamicArray(DynamicArray* array, int index) {
    pthread_mutex_lock(&array->lock);

    // If the index is valid, remove the element from the array
    if (index < array->used) {
        for (int i = index; i < array->used - 1; ++i) {
            array->array[i] = array->array[i + 1];
        }

        --array->used;
    }

    pthread_mutex_unlock(&array->lock);
}

void cleanupDynamicArray(DynamicArray* array) {
    // Free the memory allocated for the array
    free(array->array);
    array = NULL;
}
