    EVP_MD_CTX *mdctx;
    z_stream strm;
} IntegrationContext;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* integrationFunction(const char* algorithm, const unsigned char* data, size_t len) {
    assert(algorithm != NULL);
    assert(data != NULL);

    IntegrationContext *ctx = malloc(sizeof(IntegrationContext));
    if (ctx == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    // Initialize OpenSSL context
    const EVP_MD *md = EVP_get_digestbyname(algorithm);
    if (md == NULL) {
        fprintf(stderr, "Invalid algorithm\n");
        pthread_mutex_unlock(&mutex);
        free(ctx);
        return NULL;
    }

    ctx->mdctx = EVP_MD_CTX_new();
    if (ctx->mdctx == NULL || !EVP_DigestInit_ex(ctx->mdctx, md, NULL)) {
        fprintf(stderr, "Failed to initialize OpenSSL context\n");
        pthread_mutex_unlock(&mutex);
        free(ctx);
        return NULL;
    }

    // Hash data
    if (!EVP_DigestUpdate(ctx->mdctx, data, len)) {
        fprintf(stderr, "Failed to update OpenSSL context\n");
        pthread_mutex_unlock(&mutex);
        free(ctx);
        return NULL;
    }

    // Initialize zlib stream
    if (deflateInit2(&ctx->strm, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 15 + 16, MAX_MEM_LEVEL, Z_DEFAULT_STRATEGY) != Z_OK) {
        fprintf(stderr, "Failed to initialize zlib stream\n");
        pthread_mutex_unlock(&mutex);
        free(ctx);
        return NULL;
    }

    // Compress data
    if (deflate(&ctx->strm, Z_FINISH) != Z_STREAM_END) {
        fprintf(stderr, "Failed to compress data\n");
        pthread_mutex_unlock(&mutex);
        free(ctx);
        return NULL;
    }

    pthread_mutex_unlock(&mutex);

    return ctx;
}
