#include <pthread.h>
#include <stdlib.h>
#include <assert.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    record* records;
} memory_pool;

memory_pool pool = { .capacity = 0, .count = 0, .records = NULL };

void init_memory_pool(size_t initial_capacity) {
    pthread_mutex_init(&pool.mutex, NULL);
    pool.records = malloc(initial_capacity * sizeof(record));
    assert(pool.records != NULL);
    pool.capacity = initial_capacity;
}

void resize_memory_pool(size_t new_capacity) {
    pthread_mutex_lock(&pool.mutex);

    record* new_records = realloc(pool.records, new_capacity * sizeof(record));
    assert(new_records != NULL);

    pool.records = new_records;
    pool.capacity = new_capacity;

    pthread_mutex_unlock(&pool.mutex);
}

void add_record(long offset, int key, double value) {
    pthread_mutex_lock(&pool.mutex);

    if (pool.count == pool.capacity) {
        resize_memory_pool(2 * pool.capacity);
    }

    pool.records[pool.count].offset = offset;
    pool.records[pool.count].key = key;
    pool.records[pool.count].value = value;
    ++pool.count;

    pthread_mutex_unlock(&pool.mutex);
}
```
