    pthread_mutex_t lock;
} Record;

Record* records = NULL;
size_t record_count = 0, max_records = 0;
pthread_mutex_t resize_lock = PTHREAD_MUTEX_INITIALIZER;

void init_record(int key, long offset) {
    Record* new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        log_error("Failed to allocate memory for record");
        return;
    }

    new_record->key = key;
    new_record->offset = offset;
    new_record->timestamp = time(NULL);
    pthread_mutex_init(&new_record->lock, NULL);

    pthread_mutex_lock(&resize_lock);
    if (record_count == max_records) {
        size_t new_max_records = max_records ? max_records * 2 : 1;
        Record* new_records = realloc(records, sizeof(Record*) * new_max_records);
        if (new_records == NULL) {
            log_error("Failed to resize records array");
            pthread_mutex_unlock(&resize_lock);
            free(new_record);
            return;
        }

        max_records = new_max_records;
        records = new_records;
    }

    records[record_count++] = new_record;
    pthread_mutex_unlock(&resize_lock);
}
```
This code provides a basic structure for managing an array of `Record` structures. It uses dynamic memory allocation to create and resize the array, ensuring that each record is properly initialized with its own lock. The function also logs errors when allocation or resizing fails. 

