    Record record;
    pthread_mutex_t lock;
    int refCount;
} Entry;

Entry* createEntry(unsigned long id, float randomFloatValue, Record record) {
    Entry* entry = (Entry*) malloc(sizeof(Entry));
    if(entry == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    entry->id = id;
    entry->randomFloatValue = randomFloatValue;
    entry->record = record;
    pthread_mutex_init(&entry->lock, NULL);
    entry->refCount = 1;

    return entry;
}

void incrementRef(Entry* entry) {
    if(entry != NULL) {
        pthread_mutex_lock(&entry->lock);
        entry->refCount++;
        pthread_mutex_unlock(&entry->lock);
    }
}

void decrementRef(Entry* entry) {
    if(entry != NULL) {
        pthread_mutex_lock(&entry->lock);
        entry->refCount--;

        if(entry->refCount == 0) {
            free(entry);
        } else {
            pthread_mutex_unlock(&entry->lock);
        }
    }
}
```
