// Function to add a new frame
void addFrame(NR_DL_FRAME_TRANSPORT_CONTEXT* context) {
    if (frameArraySize >= frameArrayCapacity) {
        printf("Maximum frame limit reached. Cannot add more frames.\n");
        return;
    }

    // Reallocate memory for the array to accommodate new frame
    frameArray = realloc(frameArray, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT) * (frameArraySize + 1));
    if (!frameArray) {
        printf("Failed to allocate memory.\n");
        return;
    }

    // Copy the new frame into the array and increment size
    memcpy(&frameArray[frameArraySize], context, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    frameArraySize++;
}

// Function to update a frame
void updateFrame(size_t index, NR_DL_FRAME_TRANSPORT_CONTEXT* context) {
    if (index >= frameArraySize) {
        printf("Invalid frame index.\n");
        return;
    }

    // Copy the updated frame into the array at specified index
    memcpy(&frameArray[index], context, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
}

// Function to delete a frame
void deleteFrame(size_t index) {
    if (index >= frameArraySize) {
        printf("Invalid frame index.\n");
        return;
    }

    // Shift all frames after the deleted one back by one position
    for (size_t i = index; i < frameArraySize - 1; ++i) {
        memcpy(&frameArray[i], &frameArray[i + 1], sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT));
    }

    // Reallocate memory for the array to remove last frame and decrement size
    frameArray = realloc(frameArray, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT) * (frameArraySize - 1));
    if (!frameArray && frameArraySize != 0) {
        printf("Failed to allocate memory.\n");
        return;
    }
    frameArraySize--;
}
