record_t* create_record(int key, int offset, const char* string) {
    record_t* rec = malloc(sizeof(record_t));
    if (rec == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    rec->key = key;
    rec->offset = offset;
    rec->string = strdup(string);

    printf("Record created: %p\n", rec);
    return rec;
}

void destroy_record(record_t* rec) {
    free(rec->string);
    free(rec);

    printf("Record destroyed: %p\n", rec);
}

char* serialize_record(const record_t* rec, size_t* len) {
    *len = sizeof(int)*2 + strlen(rec->string) + 1; // key, offset, string and null terminator

    char* buffer = malloc(*len);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    memcpy(buffer, &rec->key, sizeof(int));
    memcpy(buffer + sizeof(int), &rec->offset, sizeof(int));
    strcpy(buffer + sizeof(int)*2, rec->string);

    return buffer;
}

record_t* deserialize_record(const char* data) {
    int key = *((int*)data);
    int offset = *((int*)(data + sizeof(int)));
    const char* string = data + sizeof(int)*2;

    return create_record(key, offset, string);
}

