} Record;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    Record** records;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager* manager = malloc(sizeof(ArrayManager));
    if (manager == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for ArrayManager: %m");
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = malloc(initial_capacity * sizeof(long));
    if (manager->offsets == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for offsets: %m");
        free(manager);
        return NULL;
    }

    manager->keys = malloc(initial_capacity * sizeof(int));
    if (manager->keys == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for keys: %m");
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    manager->records = malloc(initial_capacity * sizeof(Record*));
    if (manager->records == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for records: %m");
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    return manager;
}
```
