#include <time.h>

typedef struct {
    int transactionID;
    char sourceIP[16];
    char destIP[16];
    int sourcePort;
    int destPort;
    size_t payloadSize;
} Packet;

typedef struct Node {
    Packet packet;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int maxPackets = 100; // Maximum number of packets that can be processed concurrently

void processPacket(Packet packet) {
    clock_t start, end;
    double cpuTimeUsed;

    start = clock();
    // Perform your operations here...
    end = clock();
    cpuTimeUsed = ((double)(end - start)) / CLOCKS_PER_SEC;

    printf("CPU time used: %f\n", cpuTimeUsed);
}

void* processPacketThread(void* arg) {
    Packet packet = *((Packet*)arg);
    processPacket(packet);
    return NULL;
}

void addToQueue(Packet packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    pthread_mutex_lock(&lock);
    newNode->packet = packet;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

void optimizeNetworkFlow(Packet packet) {
    addToQueue(packet);

    int count = 0;
    Node* node = head;
    while (node != NULL && count < maxPackets) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, processPacketThread, &(node->packet))) {
            printf("Error creating thread\n");
            exit(1);
        }

        node = node->next;
        count++;
    }

    pthread_mutex_lock(&lock);
    head = node; // Update the queue after processing some packets
    pthread_mutex_unlock(&lock);
}
```
