['Here is an example of how you might implement this in C using pthreads for thread safety and a custom memory pool for efficient allocation and deallocation. This is a simplified version and does not cover all the requirements mentioned above. 

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    record* records;
} memory_pool;

memory_pool pool = { .lock = PTHREAD_MUTEX_INITIALIZER, .capacity = 0, .count = 0, .records = NULL };

record* allocate(size_t size) {
    pthread_mutex_lock(&pool.lock);

    if (pool.count + size > pool.capacity) {
        // Resize the memory pool
        size_t newCapacity = pool.capacity == 0 ? 1 : pool.capacity * 2;
        while (newCapacity < pool.count + size) {
            newCapacity *= 2;
        }

        record* newRecords = realloc(pool.records, newCapacity * sizeof(record));
        if (!newRecords) {
            pthread_mutex_unlock(&pool.lock);
            return NULL; // Allocation failed
        }

        pool.capacity = newCapacity;
        pool.records = newRecords;
    }

    record* allocated = &pool.records[pool.count];
    pool.count += size;

    pthread_mutex_unlock(&pool.lock);

    return allocated;
}

void deallocate(record* records, size_t size) {
    // This function is not needed in this simple example as we are not supporting deallocation of individual records
    // However, it would be necessary if we were to support resizing the memory pool or individual record deallocation
