    if (num_offsets <= 0 || num_offsets > LONG_MAX / sizeof(long)) {
        return -1; // Invalid input error code
    }

    long *offsets = malloc(sizeof(long) * num_offsets);
    if (!offsets) {
        return -2; // Memory allocation failure error code
    }

    int *keys = calloc(num_offsets, sizeof(int));
    if (!keys) {
        free(offsets);
