    Record **records = malloc(sizeof(Record*) * num_offsets);
    if (!records) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failure error code
    }

    for (long i = 0; i < num_offsets; ++i) {
        int *value = malloc(sizeof(int));
        if (!value) {
            // Free previously allocated memory and return an error code
            for (--i; i >= 0; --i) {
                free(records[i]->value);
                free(records[i]);
            }
            free(offsets);
            free(keys);
            free(records);
            return -2; // Memory allocation failure error code
        }

        *value = rand() % (max_value - min_value + 1) + min_value;
        records[i] = malloc(sizeof(Record));
