} Record;

Record** createRecords(long max_offsets, int min_value, int max_value) {
    if (max_offsets < 0 || max_offsets > 1000000) {
        return NULL; // Invalid input
    }

    long* offsets = malloc(sizeof(long) * max_offsets);
    for (int i = 0; i < max_offsets; ++i) {
        offsets[i] = i;
    }

    int keyCount = max_offsets / 2;
    if (keyCount > 1000000) { // Limit the size of keys array to prevent excessive memory usage
        return NULL; // Invalid input
    }

    int* keys = malloc(sizeof(int) * keyCount);
    for (int i = 0; i < keyCount; ++i) {
        keys[i] = i + 1;
    }

    Record** records = malloc(sizeof(Record*) * max_offsets);
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < max_offsets; ++i) {
        Record* record = malloc(sizeof(Record));
        record->offset = &offsets[i];
        record->key = keys[rand() % keyCount + min_value]; // Randomly select a key from the array

        if (record->key > max_value || record->key < min_value) {
            free(records);
            return NULL; // Invalid record
        }

        records[i] = record;
    }

    free(offsets);
    free(keys);

    return records;
}

void destroyRecords(Record** records, long max_offsets) {
    for (int i = 0; i < max_offsets; ++i) {
        free(records[i]);
