```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Node {
    char* string;
    time_t timestamp;
    bool status;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initList() {
    pthread_mutex_lock(&lock);
    if (head != NULL) {
        Node* current = head;
        while(current != NULL) {
            Node* temp = current->next;
            free(current->string);
            free(current);
            current = temp;
        }
        head = tail = NULL;
    }
    pthread_mutex_unlock(&lock);
}

void addNode(const char* substring) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    newNode->string = strdup(substring);
    newNode->timestamp = time(NULL);
    newNode->status = false;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL || tail == NULL) {
        head = tail = newNode;
    } else {
        Node* current = head;
        while(current != NULL && difftime(newNode->timestamp, current->timestamp) > 0) {
            current = current->next;
        }

        if (current == head) {
            newNode->next = head;
            head = newNode;
        } else if (current == NULL) {
            tail->next = newNode;
            tail = newNode;
        } else {
            Node* prev = head;
            while(prev->next != current) {
                prev = prev->next;
            }

            newNode->next = current;
            prev->next = newNode;
        }
    }
    pthread_mutex_unlock(&lock);
}

void printList() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while(current != NULL) {
        printf("String: %s, Timestamp: %ld, Status: %d\n", 
               current->string, current->timestamp, current->status);
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void updateStatus(time_t timestamp) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while(current != NULL && current->timestamp != timestamp) {
        current = current->next;
    }

    if (current == NULL) {
        printf("No node with given timestamp\n");
    } else {
        current->status = true;
    }
    pthread_mutex_unlock(&lock);
}
