    NR_RLC_PDU* rlc_pdu_list;
    int qos_config;
} NR_DL_FRAME_TRANSPORT_CONTEXT;

typedef struct FrameContextManager {
    pthread_mutex_t lock;
    NR_DL_FRAME_TRANSPORT_CONTEXT** contexts;
    int size;
    int capacity;
} FrameContextManager;

FrameContextManager* create_manager() {
    FrameContextManager* manager = malloc(sizeof(FrameContextManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = 10000;
    manager->contexts = calloc(manager->capacity, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT*));
    return manager;
}

void add_frame(FrameContextManager* manager, NR_DL_FRAME_TRANSPORT_CONTEXT* context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        // Double the capacity when full
        manager->capacity *= 2;
        manager->contexts = realloc(manager->contexts, sizeof(NR_DL_FRAME_TRANSPORT_CONTEXT*) * manager->capacity);
    }

    manager->contexts[manager->size++] = context;

    pthread_mutex_unlock(&manager->lock);
}

void update_frame(FrameContextManager* manager, int index, NR_DL_FRAME_TRANSPORT_CONTEXT* new_context) {
    pthread_mutex_lock(&manager->lock);

    if (index < manager->size && index >= 0) {
        free(manager->contexts[index]); // Free the old context
        manager->contexts[index] = new_context;
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_manager(FrameContextManager* manager) {
    for (int i = 0; i < manager->size; ++i) {
        free(manager->contexts[i]); // Free each context
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->contexts);
    free(manager);
