['Here is a high level overview of how you might implement this task using C and some POSIX threading libraries. This code does not include all the details mentioned in your request, but it should give you an idea of how you could approach this problem. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <sys/resource.h>
#include <time.h>

typedef struct {
    int i;
    long l;
    double d;
} record;

typedef struct {
    record* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    atomic_int resizeInProgress;
} ArrayManager;

ArrayManager* createArrayManager(size_t initialSize) {
    ArrayManager* manager = malloc(sizeof(ArrayManager));
    if (manager == NULL) return NULL;

    manager->data = calloc(initialSize, sizeof(record));
    if (manager->data == NULL) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initialSize;
    pthread_mutex_init(&manager->lock, NULL);
    atomic_store(&manager->resizeInProgress, 0);

    return manager;
}

void destroyArrayManager(ArrayManager* manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addRecord(ArrayManager* manager, record r) {
    if (atomic_load(&manager->resizeInProgress)) return -1; // Resize in progress

    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        atomic_store(&manager->resizeInProgress, 1);

        size_t newCapacity = manager->capacity * 2; // Simple strategy for resizing
        record* newData = realloc(manager->data, newCapacity * sizeof(record));
        if (newData == NULL) {
            atomic_store(&manager->resizeInProgress, 0);
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }

        manager->data = newData;
        manager->capacity = newCapacity;

        atomic_store(&manager->resizeInProgress, 0);
    }

    manager->data[manager->size++] = r;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}
```
