```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* ip;
    int port;
    time_t lastAccessed;
    int status;
    double latency;
} Connection;

typedef struct {
    pthread_mutex_t lock;
    Connection** connections;
    size_t size;
    size_t capacity;
} ConnectionPool;

ConnectionPool* createPool(size_t initialCapacity) {
    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    if (pool == NULL) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->connections = calloc(initialCapacity, sizeof(Connection*));
    if (pool->connections == NULL) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initialCapacity;
    return pool;
}

void destroyPool(ConnectionPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->connections[i]->ip);
        free(pool->connections[i]);
    }

    free(pool->connections);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void addConnection(ConnectionPool* pool, const char* ip, int port) {
    Connection* connection = malloc(sizeof(Connection));
    if (connection == NULL) return;

    connection->ip = strdup(ip);
    if (connection->ip == NULL) {
        free(connection);
        return;
    }

    connection->port = port;
    connection->lastAccessed = 0;
    connection->status = 0;
    connection->latency = 0.0;

    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        Connection** newConnections = realloc(pool->connections, newCapacity * sizeof(Connection*));
        if (newConnections != NULL) {
            pool->connections = newConnections;
            pool->capacity = newCapacity;
        } else {
            free(connection->ip);
            free(connection);
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }

    pool->connections[pool->size++] = connection;
    pthread_mutex_unlock(&pool->lock);
}
```
