["Here is an example of how you might implement this in C using pthreads for thread safety and a custom hash table for efficient lookups. This code does not include the resizing mechanism as it would be quite complex to fully explain here, but it provides a good starting point. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* key;
    double value;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_table(size_t initialCapacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->buckets = calloc(initialCapacity, sizeof(Node*));
    if (table->buckets == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = initialCapacity;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

size_t hash(char* key) {
    size_t hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

int add(HashTable* table, char* key, double value) {
    if (strlen(key) == 0 || strlen(key) > 1024) return -1; // Key length validation

    pthread_mutex_lock(&table->lock);

    size_t index = hash(key) % table->capacity;
    Node* node = table->buckets[index];

    while (node != NULL) { // Check for duplicate keys
        if (strcmp(node->entry.key, key) == 0) {
            pthread_mutex_unlock(&table->lock);
            return -2;
        }

        node = node->next;
    }

    Node* newNode = malloc(sizeof(Node)); // Add new entry
    if (newNode == NULL) {
        pthread_mutex_unlock(&table->lock);
        return -3;
    }

    newNode->entry.key = strdup(key);
    newNode->entry.value = value;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->lock);

    return 0;
}
```
This is a basic implementation and does not include the resizing mechanism or iterator interface. It also doesn't handle memory allocation failures for individual entries, but it does ensure that the entire table can be allocated before adding any entries. The hash function used here is a simple one and may not provide good distribution for all inputs. You might want to use a more robust hash function or consider using an existing library for this purpose.
