#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    if (initial_capacity <= 0) return NULL;

    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->data = malloc(initial_capacity * sizeof(int));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(RecordCollection* collection) {
    if (!collection) return;

    free(collection->data);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection* collection, int record) {
    if (!collection || record < 0) return -1;

    pthread_mutex_lock(&collection->lock);

    // Check if we need to resize the array
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        int* new_data = realloc(collection->data, new_capacity * sizeof(int));

        // If reallocation failed, return error code
        if (!new_data) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    // Add the record to the array
    collection->data[collection->size] = record;
    collection->size++;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}
```
