```c
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T** allocate_records(int min, int max, size_t count) {
    if (min < 0 || max < 0 || count < 1 || max < min) {
        errno = EINVAL;
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T** records = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (records == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (records[i] == NULL) {
            // Clean up previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);

            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[i]->RX_UE_INFORMATION_TAG = rand() % (max - min + 1) + min;
        records[i]->RNTI = 0; // Set to 0 for simplicity, replace with actual value as needed
        records[i]->CRC_INDICATION_REL8_TAG = 0; // Set to 0 for simplicity, replace with actual value as needed
        records[i]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
    }

    pthread_mutex_unlock(&lock);
    return records;
}
```
