    if (node == NULL) {
        logError("Failed to allocate memory for new node");
        return NULL;
    }

    node->key = strdup(key);
    if (node->key == NULL) {
        logError("Failed to duplicate key string");
        free(node);
        return NULL;
    }

    node->value = value;
    node->next = NULL;
    return node;
}

void addNode(char* key, int value) {
    pthread_mutex_lock(&lock);

    dataNode* newNode = createNode(key, value);
    if (newNode == NULL) {
        logError("Failed to create new node");
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->next = head;
    head = newNode;

    fprintf(logFile, "Added node with key %s and value %d\n", key, value);

    pthread_mutex_unlock(&lock);
}
```

