```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    double precision_number;
} record;

typedef struct {
    pthread_mutex_t mutex;
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
} DataCollection;

DataCollection* create_collection(size_t initial_capacity) {
    DataCollection* collection = malloc(sizeof(DataCollection));
    pthread_mutex_init(&collection->mutex, NULL);
    collection->offsets = malloc(initial_capacity * sizeof(long));
    collection->keys = malloc(initial_capacity * sizeof(int));
    collection->records = malloc(initial_capacity * sizeof(record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

void add_to_collection(DataCollection* collection, long offset, int key, record* rec) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size == collection->capacity) {
        // Reallocate memory with increased capacity
        size_t new_capacity = collection->capacity * 2;
        collection->offsets = realloc(collection->offsets, new_capacity * sizeof(long));
        collection->keys = realloc(collection->keys, new_capacity * sizeof(int));
        collection->records = realloc(collection->records, new_capacity * sizeof(record*));
        collection->capacity = new_capacity;
    }

    // Add the new element to the arrays
    collection->offsets[collection->size] = offset;
    collection->keys[collection->size] = key;
    collection->records[collection->size] = rec;
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);
}

void free_collection(DataCollection* collection) {
    // Free all records first
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]);
    }

    pthread_mutex_lock(&collection->mutex);
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);

    // Finally, free the collection itself
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
```
This code provides a basic structure for managing a collection of records. It uses a mutex to ensure thread safety when adding elements to the collection. The capacity of the arrays is doubled each time it needs to be increased, which minimizes the number of reallocations and thus the cost of frequent allocations and deallocations.

Please note that this code does not include any error checking or validation for simplicity. In a real-world application, you would want to add appropriate checks and handle errors gracefully. Also, logging mechanism is not included in this basic implementation. You may need to use external libraries like log4c or glib for logging.
