int* generate_unique_random(int min, int max, size_t count) {
    if (max - min + 1 < count) {
        fprintf(stderr, "Cannot generate %zu unique random numbers in range [%d, %d]\n", count, min, max);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    int* numbers = allocate_buffer(sizeof(int) * count);
    for (size_t i = 0; i < count; ++i) {
        int number;
        do {
            number = rand() % (max - min + 1) + min;
        } while (memchr(numbers, number, sizeof(int) * i));
        numbers[i] = number;
