    mgr->chunk_limit = chunk_limit;
    mgr->memory_budget = memory_budget;
    mgr->current_memory = 0;
    mgr->records = NULL;
    mgr->num_records = 0;

    return mgr;
}

int add_record(ArrayManager *mgr, int key, int min_value, int max_value) {
    if (max_value < min_value || min_value < 0 || max_value < 0) return -1; // Invalid parameters

    pthread_mutex_lock(&mgr->lock);

    if (mgr->current_memory + sizeof(Record) > mgr->memory_budget) {
        pthread_mutex_unlock(&mgr->lock);
        return -2; // Insufficient memory
    }

    Record *record = malloc(sizeof(Record));
