    if (mgr->records == NULL) {
        free(record->value);
        free(record);
        pthread_mutex_unlock(&mgr->lock);
        return -3; // Allocation failure
    }

    mgr->records[mgr->num_records++] = record;
    mgr->current_memory += sizeof(Record) + sizeof(int);

    pthread_mutex_unlock(&mgr->lock);

    return 0; // Success
}
