#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

// Global variables
Record* records = NULL;
size_t recordCount = 0;
size_t maxRecords = 0;
pthread_mutex_t lock;

void initialize() {
    pthread_mutex_init(&lock, NULL);
}

int allocate(size_t count) {
    pthread_mutex_lock(&lock);

    if (recordCount + count > maxRecords) {
        size_t newMax = recordCount + count;

        // Reallocate memory with exponential growth strategy
        Record* newRecords = realloc(records, newMax * sizeof(Record));
        if (!newRecords) {
            pthread_mutex_unlock(&lock);
            return -1;  // Allocation failed
        }

        records = newRecords;
        maxRecords = newMax;
    }

    recordCount += count;

    pthread_mutex_unlock(&lock);
    return 0;  // Allocation succeeded
}

void deallocate() {
    pthread_mutex_lock(&lock);

    free(records);
    records = NULL;
    recordCount = 0;
    maxRecords = 0;

    pthread_mutex_unlock(&lock);
}
```
