typedef struct Resource {
    int id;
} Resource;

typedef struct DependencyNode {
    int taskId;
    struct DependencyNode* next;
} DependencyNode;

typedef struct Task {
    int id;
    int priority;
    Resource** resources;
    DependencyNode* dependencies;
    pthread_mutex_t lock;
} Task;

Task* tasks = NULL;
Resource** resources = NULL;
int taskCount = 0, resourceCount = 0;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void addTask(int id, int priority) {
    pthread_mutex_lock(&globalLock);

    tasks = realloc(tasks, sizeof(Task) * (taskCount + 1));
    Task* newTask = &tasks[taskCount++];
    newTask->id = id;
    newTask->priority = priority;
    newTask->resources = NULL;
    newTask->dependencies = NULL;
    pthread_mutex_init(&newTask->lock, NULL);

    pthread_mutex_unlock(&globalLock);
}

void addResource(int id) {
    pthread_mutex_lock(&globalLock);

    resources = realloc(resources, sizeof(Resource*) * (resourceCount + 1));
    Resource* newResource = malloc(sizeof(Resource));
    newResource->id = id;
    resources[resourceCount++] = newResource;

    pthread_mutex_unlock(&globalLock);
}

void addDependency(int taskId, int dependencyTaskId) {
    for (int i = 0; i < taskCount; ++i) {
        if (tasks[i].id == taskId) {
            DependencyNode* newNode = malloc(sizeof(DependencyNode));
            newNode->taskId = dependencyTaskId;
            newNode->next = tasks[i].dependencies;
            tasks[i].dependencies = newNode;
        }
    }
}

void assignResourceToTask(int taskId, int resourceId) {
    for (int i = 0; i < taskCount; ++i) {
        if (tasks[i].id == taskId) {
            tasks[i].resources = realloc(tasks[i].resources, sizeof(Resource*) * (resourceCount + 1));
            tasks[i].resources[resourceCount++] = &resources[resourceId];
        }
    }
}
