// Function to execute external command in background
void executeCommand(const char* cmd) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        system(cmd);
        exit(EXIT_SUCCESS);
    } else if (pid < 0) { // Fork failed
        perror("fork");
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for child to finish
    }
}

