DataStructure* createDataStructure(size_t size) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL;

    ds->offset = calloc(size, sizeof(long));
    ds->key = calloc(size, sizeof(int));
    pthread_mutex_init(&ds->mutex, NULL);

    if (ds->offset == NULL || ds->key == NULL) {
        freeDataStructure(ds);
        return NULL;
    }

    return ds;
}

void freeDataStructure(DataStructure* ds) {
    pthread_mutex_destroy(&ds->mutex);
    free(ds->offset);
    free(ds->key);
    free(ds);
}

char* computeMD5Hash(DataStructure* ds, size_t size) {
    char* input = malloc(sizeof(long) * 2 * size + 1); // long and int are usually the same size

    if (input == NULL) return NULL;

    memcpy(input, ds->offset, sizeof(long) * size);
    memcpy(input + sizeof(long) * size, ds->key, sizeof(int) * size);

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*) input, sizeof(long) * 2 * size, md5);

    free(input);

    // Convert the hash to a hexadecimal string
    char* output = malloc(MD5_DIGEST_LENGTH * 2 + 1);

    if (output == NULL) return NULL;

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&output[i*2], "%02x", md5[i]);
    }

    return output;
}
