#include <sys/syscall.h>
#include <stdatomic.h>

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long* offsets = NULL;
int* keys = NULL;
record** records = NULL;
size_t size = 0, capacity = 1024;
atomic_bool resizing = ATOMIC_VAR_INIT(false);

void* resize(void* arg) {
    while (1) {
        sleep(60); // wait for a minute

        pthread_mutex_lock(&lock);
        if (!resizing && size > capacity * 0.8) {
            atomic_store(&resizing, true);

            long* new_offsets = realloc(offsets, sizeof(*new_offsets) * capacity * 2);
            int* new_keys = realloc(keys, sizeof(*new_keys) * capacity * 2);

            if (new_offsets && new_keys) {
                offsets = new_offsets;
                keys = new_keys;

                capacity *= 2;
            } else {
                // handle memory allocation failure
            }

            atomic_store(&resizing, false);
        }
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

void init(size_t initial_capacity) {
    capacity = initial_capacity;
    offsets = malloc(sizeof(*offsets) * capacity);
    keys = malloc(sizeof(*keys) * capacity);
    records = calloc(capacity, sizeof(*records));

    pthread_t thread;
    if (pthread_create(&thread, NULL, resize, NULL)) {
        // handle thread creation failure
    }
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&lock);

    if (size == capacity && !atomic_load(&resizing)) {
        atomic_store(&resizing, true);

        long* new_offsets = realloc(offsets, sizeof(*new_offsets) * capacity * 2);
        int* new_keys = realloc(keys, sizeof(*new_keys) * capacity * 2);

        if (new_offsets && new_keys) {
            offsets = new_offsets;
            keys = new_keys;

            capacity *= 2;
        } else {
            // handle memory allocation failure
        }

        atomic_store(&resizing, false);
    }

    if (size < capacity) {
        offsets[size] = offset;
        keys[size] = key;

        record* new_record = malloc(sizeof(*new_record));
        new_record->value = rand() % 1000; // random value within a specified range
        new_record->offset_ptr = &offsets[size];
        new_record->key_ptr = &keys[size];

        records[size] = new_record;
        ++size;
    } else {
        // handle array full
    }

    pthread_mutex_unlock(&lock);
}
```
