        }

        Record record = { .value = key };
        records[offset++] = record;

        pthread_mutex_unlock(&lock);
    }

    int maxValue = findMaxValue(records, offset);

    free(records);

    return NULL;
}

int findMaxValue(Record *records, size_t count) {
    if (count == 0) {
        fprintf(stderr, "No records to process\n");
        exit(EXIT_FAILURE);
    }

    int max = records[0].value;

    for (size_t i = 1; i < count; ++i) {
        if (records[i].value > max) {
            max = records[i].value;
        }
    }

    return max;
}
```
This code reads integers from standard input, stores them in a dynamically allocated array, and finds the maximum value. It uses a mutex to ensure thread safety when accessing the shared data structure. 

