        std::unique_lock<std::shared_mutex> lock(entryMutex);
        entries[key] = Entry{key, value, 1};
    }

    bool remove(const std::string& key) {
        std::unique_lock<std::shared_mutex> lock(entryMutex);
        auto it = entries.find(key);
        if (it != entries.end()) {
            entries.erase(it);
            return true;
        }
        return false;
    }

    bool update(const std::string& key, float value) {
        std::unique_lock<std::shared_mutex> lock(entryMutex);
        auto it = entries.find(key);
        if (it != entries.end()) {
            it->second.value = value;
            return true;
        }
        return false;
    }

    void incrementRefCount(const std::string& key) {
        std::unique_lock<std::shared_mutex> lock(entryMutex);
        auto it = entries.find(key);
        if (it != entries.end()) {
            it->second.refCount++;
        }
    }

    void serialize(std::ofstream& file) const {
        std::shared_lock<std::shared_mutex> lock(entryMutex);
        for (const auto& entry : entries) {
            file << entry.first << "," << entry.second.value << "," << entry.second.refCount << "\n";
        }
    }

