['Here is an example of how you might implement this function in C. This code does not include all the features mentioned above due to their complexity and size. However, it provides a basic structure that can be expanded upon to meet your requirements. 

```c
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>

typedef struct file_info {
    char *filename;
    int size;
    time_t lastModified;
} file_info;

int processDirectory(const char* dirPath, file_info **files, int *count) {
    DIR *dir = opendir(dirPath);
    if (dir == NULL) {
        perror("Failed to open directory");
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", dirPath, entry->d_name);

            struct stat st;
            if (stat(path, &st) == 0) {
                *files = realloc(*files, (*count + 1) * sizeof(file_info));
                if (*files == NULL) {
                    perror("Failed to allocate memory");
                    return -2;
                }

                file_info *fi = &((*files)[*count]);
                fi->filename = strdup(entry->d_name);
                if (fi->filename == NULL) {
                    perror("Failed to allocate memory");
                    return -2;
                }

                fi->size = st.st_size;
                fi->lastModified = st.st_mtime;
            } else {
                perror("Failed to get file info");
                return -3;
            }

            (*count)++;
        }
    }

    closedir(dir);
    return 0;
}
```
This function opens a directory, reads each entry in the directory, checks if it's a regular file, and if so, retrieves its size and last modified timestamp. It then dynamically allocates memory for a new `file_info` structure and copies the filename into it. The function returns 0 on success, or -1 if there was an error opening the directory, -2 if there was an error allocating memory, or -3 if there was an error getting file info.
