typedef struct {
    size_t size;
    atomic_int count;
    pthread_mutex_t lock;
    record* records;
} RecordPool;

RecordPool* create_record_pool(size_t size) {
    RecordPool* pool = malloc(sizeof(RecordPool));
    if (!pool) return NULL;

    pool->records = calloc(size, sizeof(record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    atomic_init(&pool->count, 0);
    pthread_mutex_init(&pool->lock, NULL);
    pool->size = size;

    return pool;
}

record* allocate_record(RecordPool* pool) {
    int index = atomic_fetch_add(&pool->count, 1);
    if (index >= pool->size) {
        pthread_mutex_lock(&pool->lock);
        record* newRecords = realloc(pool->records, pool->size * 2 * sizeof(record));
        if (!newRecords) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        pool->records = newRecords;
        pool->size *= 2;
        pthread_mutex_unlock(&pool->lock);
    }

    return &pool->records[index];
}

void free_record(RecordPool* pool, record* rec) {
