#include <mutex>
#include <vector>

class RandomNumberGenerator {
public:
    static std::mt19937 gen;
    static std::uniform_int_distribution<uint64_t> dis;

    static uint64_t generate(uint64_t min, uint64_t max) {
        std::lock_guard<std::mutex> lock(mtx);
        return dis(gen) % (max - min + 1) + min;
    }
private:
    static std::mutex mtx;
};

std::mt19937 RandomNumberGenerator::gen{std::random_device{}()};
std::uniform_int_distribution<uint64_t> RandomNumberGenerator::dis{0, UINT64_MAX};
std::mutex RandomNumberGenerator::mtx;

class MemoryManager {
public:
    static void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mtx);
        void* ptr = malloc(size);
        if (ptr == nullptr) {
            throw std::bad_alloc();
        }
        allocated.push_back(ptr);
        return ptr;
    }

    static void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find(allocated.begin(), allocated.end(), ptr);
        if (it != allocated.end()) {
            free(*it);
            allocated.erase(it);
        } else {
            throw std::invalid_argument("Pointer not found in the list of allocated memory");
        }
    }
private:
    static std::mutex mtx;
    static std::vector<void*> allocated;
};

std::mutex MemoryManager::mtx;
std::vector<void*> MemoryManager::allocated;

int main() {
    try {
        void* ptr = MemoryManager::allocate(1024);
        std::cout << "Allocated memory at: " << ptr << std::endl;

        uint64_t randomNumber = RandomNumberGenerator::generate(1, 100);
        std::cout << "Random number generated: " << randomNumber << std::endl;

        MemoryManager::deallocate(ptr);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```
