['Here is a basic implementation of your request in C using pthreads for threading and logging with syslog. This code does not include all the optimizations you mentioned as they would significantly increase complexity. Also, it's important to note that this is just a simple example and doesn't cover all aspects of your requirements.

```c
#include <stdlib.h>
#include <pthread.h>
#include <syslog.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    pthread_mutex_t mutex;
    size_t size;
    size_t capacity;
    long* offsets;
    int* keys;
    record** records;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_capacity) {
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (pool == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for memory pool");
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->offsets = malloc(initial_capacity * sizeof(long));
    pool->keys = malloc(initial_capacity * sizeof(int));
    pool->records = malloc(initial_capacity * sizeof(record*));

    if (pool->offsets == NULL || pool->keys == NULL || pool->records == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for arrays in memory pool");
        free(pool);
        return NULL;
    }

    syslog(LOG_INFO, "Created memory pool with capacity %zu", initial_capacity);
    return pool;
}

void resize_memory_pool(memory_pool* pool) {
    pthread_mutex_lock(&pool->mutex);

    size_t new_capacity = pool->capacity * 2;
    long* new_offsets = realloc(pool->offsets, new_capacity * sizeof(long));
    int* new_keys = realloc(pool->keys, new_capacity * sizeof(int));
    record** new_records = realloc(pool->records, new_capacity * sizeof(record*));

    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        syslog(LOG_ERR, "Failed to resize memory pool");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;
    pool->capacity = new_capacity;

    syslog(LOG_INFO, "Resized memory pool to capacity %zu", new_capacity);
    pthread_mutex_unlock(&pool->mutex);
}

void add_record(memory_pool* pool, long offset, int key) {
    if (offset < 0 || key <= 0) {
        syslog(LOG_ERR, "Invalid record: offset=%ld, key=%d", offset, key);
        return;
    }

    pthread_mutex_lock(&pool->mutex);

    if (pool->size == pool->capacity) {
        resize_memory_pool(pool);
    }

    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for a record");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    new_record->offset = offset;
    new_record->key = key;
    pool->records[pool->size] = new_record;
    pool->offsets[pool->size] = offset;
    pool->keys[pool->size] = key;
    ++pool->size;

    syslog(LOG_INFO, "Added record: offset=%ld, key=%d", offset, key);
    pthread_mutex_unlock(&pool->mutex);
}
```
This code creates a memory pool that can dynamically allocate and resize arrays of `long` integers, `int` keys, and `record` structures. It uses mutexes to ensure thread safety when adding records or resizing the pool. The logging is done using syslog, which can be configured to write logs to files or other destinations.
']

