    ~ConfigManager() = default;

    void loadConfiguration(const std::string& filePath);
    void updateConfiguration(const std::string& key, const Json::Value& value);
    Json::Value getConfiguration(const std::string& key);

private:
    std::map<std::string, Json::Value> configMap_;
    std::shared_mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> isUpdating_;
};

void ConfigManager::loadConfiguration(const std::string& filePath) {
    // Load configuration from a JSON file using jsoncpp library.
}

void ConfigManager::updateConfiguration(const std::string& key, const Json::Value& value) {
    std::unique_lock<std::shared_mutex> lock(mutex_);
    isUpdating_.store(true);

    // Update the configuration.
    configMap_[key] = value;

    isUpdating_.store(false);
    cv_.notify_all();  // Notify waiting threads that an update has occurred.
}

Json::Value ConfigManager::getConfiguration(const std::string& key) {
    std::shared_lock<std::shared_mutex> lock(mutex_);

    while (isUpdating_.load()) {  // Wait for ongoing updates to finish.
        cv_.wait(lock);
    }

    return configMap_[key];  // Return the requested configuration setting.
}
