["This is a complex task that involves multiple aspects of programming including concurrent programming, memory management, error handling, logging, resizing strategies, validation, custom seeds for unique keys, cleanup mechanisms, and external persistence layer integration. Here's an outline of how you might approach this in C using POSIX threads (pthreads) for threading and a simple hash table implementation for managing the records:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

// Define record structure
typedef struct {
    int key;
    long offset;
    double value;
} Record;

// Define hash table node structure
typedef struct Node {
    Record* record;
    pthread_mutex_t lock;
    struct Node* next;
} Node;

// Define hash table structure
#define TABLE_SIZE 1024
Node** table;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
int seed = 0;

// Initialize the hash table
void initTable() {
    table = malloc(sizeof(Node*) * TABLE_SIZE);
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i] = NULL;
    }
}

// Generate a unique key
int generateKey() {
    pthread_rwlock_wrlock(&rwlock);
    int key = seed++;
    pthread_rwlock_unlock(&rwlock);
    return key;
}

// Hash function for keys
unsigned long hash(int key) {
    unsigned long hash = 5381;
    int c = key;
    hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % TABLE_SIZE;
}

// Insert a record into the table
void insert(Record* record) {
    unsigned long index = hash(record->key);
    Node* node = malloc(sizeof(Node));
    node->record = record;
    pthread_mutex_init(&node->lock, NULL);
    pthread_mutex_lock(&node->lock);
    node->next = table[index];
    table[index] = node;
    pthread_mutex_unlock(&node->lock);
}

// Retrieve a record from the table
Record* get(int key) {
    unsigned long index = hash(key);
    Node* node = table[index];
    while (node != NULL) {
        if (node->record->key == key) {
            pthread_mutex_lock(&node->lock);
            Record* record = node->record;
            pthread_mutex_unlock(&node->lock);
            return record;
        }
        node = node->next;
    }
    return NULL;
}
```
