    size_t index = HashTable_hash(table, key);
    Entry* entry = Entry_create(key, offset);
    entry->next = table->entries[index];
    table->entries[index] = entry;
    table->size++;

    pthread_mutex_unlock(&table->lock);
}

// Function to retrieve a record from the hash table
Record* HashTable_get(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    size_t index = HashTable_hash(table, key);
    Entry* entry = table->entries[index];
    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);

    return (entry == NULL) ? NULL : Record_get(entry->offset);
}

// Function to serialize a record to a binary file
void Record_serialize(Record* record, int fd) {
    write(fd, &record->value, sizeof(int));
    write(fd, record->metadata, sizeof(record->metadata));
}

// Function to deserialize a record from a binary file
Record* Record_deserialize(int fd) {
    int value;
    char metadata[1024];

    read(fd, &value, sizeof(int));
    read(fd, metadata, sizeof(metadata));

    return Record_create(value, metadata);
}
