#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>
#include <zlib.h> // for compression

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    Record* record;
} OffsetArray;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    OffsetArray* array;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->array = calloc(initial_capacity, sizeof(OffsetArray));
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void resize_dynamic_array(DynamicArray* arr, size_t new_capacity) {
    OffsetArray* new_array = calloc(new_capacity, sizeof(OffsetArray));
    memcpy(new_array, arr->array, arr->count * sizeof(OffsetArray));
    free(arr->array);
    arr->array = new_array;
    arr->capacity = new_capacity;
}

void add_to_dynamic_array(DynamicArray* arr, OffsetArray value) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->count == arr->capacity) {
        resize_dynamic_array(arr, arr->capacity * 2);
    }
    arr->array[arr->count++] = value;
    pthread_mutex_unlock(&arr->mutex);
}

// ... similar functions for other operations (e.g., remove, lookup)

void serialize(DynamicArray* arr, const char* filename) {
    gzFile file = gzopen(filename, "wb");
    assert(file != NULL);
    gzwrite(file, &arr->count, sizeof(size_t));
    for (size_t i = 0; i < arr->count; ++i) {
        gzwrite(file, &arr->array[i], sizeof(OffsetArray));
    }
    gzclose(file);
}

DynamicArray* deserialize(const char* filename) {
    gzFile file = gzopen(filename, "rb");
    assert(file != NULL);
    size_t count;
    gzread(file, &count, sizeof(size_t));
    DynamicArray* arr = create_dynamic_array(count);
    for (size_t i = 0; i < count; ++i) {
        OffsetArray value;
        gzread(file, &value, sizeof(OffsetArray));
        add_to_dynamic_array(arr, value);
    }
    gzclose(file);
    return arr;
}
```
