```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <endian.h>
#include <assert.h>

// Define a record structure with an integer value, metadata, and unique identifier
typedef struct {
    int value;
    char* metadata;
    unsigned long id;
} Record;

// Define a hash table node structure for efficient storage and retrieval of records
typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

// Define the hash table data structure with dynamic resizing strategy
typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

// Custom hash function for mapping keys to their corresponding records
size_t hash(unsigned long key, size_t capacity) {
    return key % capacity;
}

// Initialize the hash table with a given initial capacity
void initHashTable(HashTable* ht, size_t capacity) {
    ht->buckets = (Node**)calloc(capacity, sizeof(Node*));
    ht->capacity = capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->lock, NULL);
}

// Insert a record into the hash table with locking for concurrency control
void insertRecord(HashTable* ht, Record* record) {
    size_t index = hash(record->id, ht->capacity);
    pthread_mutex_lock(&ht->lock);
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    ht->size++;
    pthread_mutex_unlock(&ht->lock);
}

// Retrieve a record from the hash table with locking for concurrency control
Record* getRecord(HashTable* ht, unsigned long id) {
    size_t index = hash(id, ht->capacity);
    pthread_mutex_lock(&ht->lock);
    Node* node = ht->buckets[index];
    while (node != NULL) {
        if (node->record->id == id) {
            pthread_mutex_unlock(&ht->lock);
            return node->record;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}
```
