typedef struct {
    int timestamp;
    double amount;
    char status[20];
} Transaction;

Transaction* loadTransactionsFromFile(const char* filename, size_t* count) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open the file");
        return NULL;
    }

    // Count lines in the file.
    *count = 0;
    int ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') (*count)++;
    }
    rewind(file);

    // Allocate memory for transactions.
    Transaction* transactions = malloc(*count * sizeof(Transaction));
    if (transactions == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Read transactions from the file.
    for (size_t i = 0; i < *count; ++i) {
        if (fscanf(file, "%d %lf %s", &transactions[i].timestamp, 
                   &transactions[i].amount, transactions[i].status) != 3) {
            perror("Failed to read transaction");
            free(transactions);
            return NULL;
        }
    }

    fclose(file);
    return transactions;
}

