['Here is an example of how you might implement such a function in C. This code does not include all the features mentioned in the task description due to its complexity and size. However, it provides a good starting point for building a more complete solution. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t limit;
    size_t count;
    size_t size;
    pthread_mutex_t lock;
    Record* records;
} ArrayManager;

void initArrayManager(ArrayManager* manager, size_t initialSize) {
    manager->limit = sysconf(_SC_PHYS_PAGES);
    manager->count = 0;
    manager->size = initialSize;
    pthread_mutex_init(&manager->lock, NULL);
    manager->records = malloc(initialSize * sizeof(Record));
}

void addToArrayManager(ArrayManager* manager, Record record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->limit || manager->records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    if (manager->count == manager->size) {
        size_t newSize = manager->size * 2;
        Record* temp = realloc(manager->records, newSize * sizeof(Record));

        if (temp == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->records = temp;
        manager->size = newSize;
    }

    manager->records[manager->count++] = record;

    pthread_mutex_unlock(&manager->lock);
}

int findMax(ArrayManager* manager) {
    int maxValue = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].value > maxValue) {
            maxValue = manager->records[i].value;
        }
    }

    return maxValue;
}
```
